/** Raw Zendesk For-Sellers articles, pulled 2026-07-10 via public API. Converted to blocks at first load (store.ts). */
const zendeskRaw: { id: number; title: string; body: string }[] = [{"id":42542690484251,"title":"Getting Started on Fleek: Seller Onboarding Guide","body":"<p class=\"guide-markup\"><span class=\"wysiwyg-font-size-x-large\" style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Welcome to Fleek! 🎉</strong></span></span><br><em class=\"guide-markup\">Becoming a seller is simple and only takes a few steps. Follow this guide to set up your shop, list products, and start receiving orders quickly.</em></p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K5KS6YJZ9J2ZX47X398T92CC\"><strong class=\"guide-markup\">Before You Begin</strong></h2><p class=\"guide-markup\">Make sure you have:</p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"efe527e740bbc4ed8b1b8dec64159d41b\">📱 Unique phone number &amp; email (not already used for another shop)</li>\n<li class=\"guide-markup\" data-list-item-id=\"e109ccca19287802a0ca18240a9b0aab2\">🪪 Government-issued Identity Card</li>\n<li class=\"guide-markup\" data-list-item-id=\"ea08294c2f3a0208acc22faf3833a620b\">🏦 Bank account details for payouts</li>\n<li class=\"guide-markup\" data-list-item-id=\"edf15ace7827731c42d6d458a1163de04\">📷 A few products ready with clear photos &amp; correct size tags</li>\n<li class=\"guide-markup\" data-list-item-id=\"e299027e59e5f2673cf1ded4790938f52\">✅ Agreement to Fleek’s Seller Code of Conduct</li>\n</ul><p class=\"guide-markup\">💡 <em class=\"guide-markup\">Tip: Preparing everything in advance speeds up approval.</em></p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K5KS6YJZPHDPDJV307QRDYDG\"><strong class=\"guide-markup\">Step-by-Step Onboarding</strong></h2><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Step 1: Sign Up</strong></span></span></p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"e549da44885d8b391ef2fcd3ba60bd841\">Follow the <a class=\"guide-markup\" href=\"https://support.joinfleek.com/hc/en-us/articles/42618250910619\"><span style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Seller Sign-Up Guidelines</strong></span></span></a>\n</li>\n<li class=\"guide-markup\" data-list-item-id=\"e295ace2ad0bd65b581ecc64961dcd357\">Download the <strong class=\"guide-markup\">Fleek Seller App</strong> or visit <a class=\"guide-markup\" href=\"https://www.joinfleek.com/home\"><span style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">joinfleek.com</strong></span></span></a>\n</li>\n<li class=\"guide-markup\" data-list-item-id=\"efe00279bfdb8ef607ba300d66f867462\">Register using your phone number or email</li>\n</ul><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Step 2: Setup Your Seller Profile</strong></span></span></p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"eb6525980fcb81245d09d1fac2c75d473\">Get your store profile photo &amp; short description (BIO) uploaded</li>\n<li class=\"guide-markup\" data-list-item-id=\"eb3d0644380826816cda9b52a05701377\">Reach out to Seller Support Center</li>\n</ul><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Step 3: Submit KYC &amp; Bank Account Details</strong></span></span></p><ul class=\"guide-markup\">\n  <li class=\"guide-markup\">Please fill out the Bank/KYC form as per your region:</li>\n  <ul class=\"guide-markup\">\n    <li class=\"guide-markup\">\n      <img src=\"https://flagcdn.com/w20/pk.png\" alt=\"Pakistan Flag\" style=\"width: 20px; vertical-align: middle; margin-right: 6px;\" class=\"guide-markup\"><strong class=\"guide-markup\">For Pakistani Sellers</strong>\n      →\n      <a href=\"https://docs.google.com/forms/d/e/1FAIpQLSfGGLIy5VtkKwmLkxK4IbAlwESWQ8spNlpQ48IT-9GQd-KukQ/viewform?pli=1\" target=\"_blank\" style=\"color: #ffcc00; font-weight: 600;\" class=\"guide-markup\">KYC - Bank Details Form</a>\n    </li>\n    <li class=\"guide-markup\">\n      <img src=\"https://flagcdn.com/w20/in.png\" alt=\"India Flag\" style=\"width: 20px; vertical-align: middle; margin-right: 6px;\" class=\"guide-markup\"><strong class=\"guide-markup\">For Indian / 🌍 Other Countries Sellers</strong>\n      →\n      <a href=\"https://docs.google.com/forms/d/e/1FAIpQLSc9YiQ4H6JqRwt0bPAekdRlbFXxa8mVoZeTb0dD59cQJTpMsw/viewform\" target=\"_blank\" style=\"color: #ffcc00; font-weight: 600;\" class=\"guide-markup\">Bank Details Form</a>\n    </li>\n  </ul>\n  <li class=\"guide-markup\">\n    Submit ID card + correct account details (double-check to avoid delays)\n  </li>\n  <li class=\"guide-markup\">⏳ Approval SLA: 24 hours (excluding weekends/holidays)</li>\n</ul><p><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Step 4: Understand Policies</strong></span></span></p><p>Review and agree to:</p><ul>\n<li data-list-item-id=\"ed58ba8851a6a265bee6daa9c44bc68cd\">📦 <a href=\"https://support.joinfleek.com/hc/en-us/articles/42543042225307\">Product Listing Guidelines</a>\n</li>\n<li data-list-item-id=\"e55d7ccd35443d5e1d77afd8c5812e8f0\">🚚 <a href=\"https://support.joinfleek.com/hc/en-us/articles/42543546606491\">Order Fulfilment Policy</a>\n</li>\n<li data-list-item-id=\"ee2ba69f2553f12af9c223b731188616e\">🔍 <a href=\"https://support.joinfleek.com/hc/en-us/articles/42546589245211\">Quality Check Guidelines</a>\n</li>\n<li data-list-item-id=\"eb5051762172f8a4195f16cb0b4401a28\">💰 <a href=\"https://support.joinfleek.com/hc/en-us/articles/42539527252891\">Payment Guidelines</a>\n</li>\n</ul><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Step 5: Quick App Walk Through and Key Features</strong></span></span></p><p class=\"guide-markup\">The seller application in one accesible platform to make your life easy as a partner on Fleek</p><p class=\"guide-markup\">Click <a class=\"guide-markup\">here</a> for a detailed understanding of our Vendor Application.</p><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Step 6: Upload Your First Products</strong></span></span></p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"ebddf459ecf2deafcfc6491913c81b595\">Follow the <a class=\"guide-markup\" href=\"https://support.joinfleek.com/hc/en-us/articles/42543042225307\">Product Listing Guidelines</a> carefully</li>\n<li class=\"guide-markup\" data-list-item-id=\"e3c162fbd8991ceee046a35aea9ff999b\">Ensure product photos are clear &amp; size tags are correct</li>\n</ul><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Step 7: Go Live &amp; Start Selling 🚀</strong></span></span></p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"e1e6e2eb18950da4dd95db650e15a5927\">Once approved, your products go live</li>\n<li class=\"guide-markup\" data-list-item-id=\"ecc096b5a9c24ce6a3dcba8c8cde0e6fa\">Buyers can now place orders with you</li>\n</ul><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K5KS6YJZ8PXECZP93DZEM3F5\"><strong class=\"guide-markup\">Frequently Asked Questions</strong></h2><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">1. What do I need before starting the onboarding process?</span>\n  </summary>\n  <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    <ul class=\"guide-markup\">\n      <li class=\"guide-markup\">A unique phone number &amp; email</li>\n      <li class=\"guide-markup\">CNIC (government-issued ID)</li>\n      <li class=\"guide-markup\">Bank account details (IBAN)</li>\n      <li class=\"guide-markup\">Product photos with correct size tags</li>\n    </ul>\n  </ul>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">2. Can I use the same email/phone number for multiple shops?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\"> </p>\n<ul class=\"guide-markup\">\n      No. Each shop must have a unique phone number and email address.\n      <ul class=\"guide-markup\">\n  </ul>\n    </ul>\n  <p class=\"guide-markup\"> </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">3. How do I sign up as a seller?</span>\n  </summary>\n  <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    <ul class=\"guide-markup\">\n      <li class=\"guide-markup\">Download the Fleek Seller App or visit joinfleek.com</li>\n      <li class=\"guide-markup\">Register using your unique phone number or email</li>\n    </ul>\n  </ul>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">4. How do I create my seller profile?</span>\n  </summary>\n  <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    To add your store name, short description (BIO) and profile picture.\n    Please reach out to our seller support via WhatsApp: +447435853808)\n    \n  </ul>\n    \n  \n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">5. What happens if I enter incorrect bank details?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    Incorrect bank details may cause payout delays. Always double-check your\n    IBAN and account information before submission.\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">6. When can I upload my first products?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    After creating your profile and submitting bank details, you can upload\n    your first products following the Product Listing Guidelines.\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">7. How long does it take for my products to go live?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    Your profile and products undergo Fleek’s review and QC check.<br class=\"guide-markup\">\n    Once approved, your products will go live (usually within\n    <strong class=\"guide-markup\">24–72 hours</strong>, excluding weekends/holidays).\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">8. Who should I contact if I face issues during onboarding?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    Reach out to Seller Support via WhatsApp: +447435853808 for help with\n    your profile, KYC, or product listings.\n  </p>\n</details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    Pakistan: 11:00 AM – 7:00 PM PKT |\n    India: 10:30 AM – 6:30 PM IST |\n    UK: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n  </p>\n</div>"},{"id":52305309189659,"title":"Sea Shipping Policy and Guide","body":"<p>Sea Shipping is a new, lower-cost freight option on Fleek. The same products from the same suppliers travel by sea freight instead of air, cutting the shipping cost by up to <strong>70%</strong>. This makes your bulk and heavy lots significantly more affordable for buyers and helps you close more orders.</p><p>This article answers the most common questions sellers have about Sea Shipping.</p><hr><h2 id=\"h_01KW97T2PCGS7P86Z25R4PD436\">1. What is Sea Shipping, and why should I offer it?</h2><p>Sea Shipping is a cheaper freight option that makes your bulk and heavy lots far more affordable for buyers, helping you win and grow orders. Buyers are actively requesting it in chats, so offering it removes a common reason deals stall.</p><p>Sea shipping orders usually require 60 to 90 days for delivery, depending on the destination region. The estimated delivery time is clearly shown to buyers during checkout before they place their order.</p><p>Your fulfillment and order-preparation time remains exactly the same as it is today.</p><hr><h2 id=\"h_01KW995DZ7VZA9V9WW6GQQ8PB8\">2. How do I enable Sea Shipping on a listing?</h2><p>You do not need to change anything in your current process. Simply select the <strong>Sea Shipping</strong> option when you create a <strong>Custom Handpick</strong> listing.</p><p><em><strong>Note:</strong> Sea Shipping is <strong>not yet available</strong> on Exact or Representative listings.</em></p><figure class=\"wysiwyg-media\"><div data-oembed-url=\"https://www.loom.com/share/4d98e54be2464eaca990422234cc5480\"><iframe src=\"//www.loom.com/embed/4d98e54be2464eaca990422234cc5480\" frameborder=\"0\" allowfullscreen=\"\" allow=\"encrypted-media\" style=\"width: 100%; aspect-ratio: 16 / 9;\"></iframe></div></figure><hr><h2 id=\"h_01KW996E21WR7Y8AW2E4EBNTAP\">3. Am I eligible? Why can't I see the Sea Shipping option?</h2><p>Sea Shipping is currently available only to sellers with a <strong>customer rating of 4.0 or above</strong>. If you don't see the option on a handpick listing, your rating likely doesn't yet meet this threshold.</p><p>Keep delivering quality orders to build your rating and unlock Sea Shipping.</p><p>It is available for buyers from all over the world. Only PK sellers are eligible to avail sea-shipping though.</p><hr><h2 class=\"guide-markup\" id=\"h_01K7T2FTCQ10KHYBMABQQ5PF38\"><strong class=\"guide-markup\" data-start=\"147\" data-end=\"188\">Frequently Asked Questions:</strong></h2><details class=\"guide-markup\">\n  <summary style=\"list-style: none; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">Does Sea Shipping change my grading, QC, or protection terms?</span>\n  </summary>\n  <b class=\"guide-markup\">No.</b> Grading, QC, and\n  <b class=\"guide-markup\">Buyer &amp; Seller Protection</b> remain exactly the\n  same.\n  Only the freight cost differs.\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">How do payouts work for Sea Shipping orders?</span>\n  </summary>\n  Payouts work exactly the same way as your current orders. There is\n  <b class=\"guide-markup\">no change</b> to how or when you are paid.\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">I am an EPZ (Export Processing Zone) vendor, how should sea orders be handled?</span>\n  </summary>\n  Sea Shipping orders must <b class=\"guide-markup\">not</b> be moved under a\n  normal GD. After preparing the order (approximately\n  <b class=\"guide-markup\">5 days</b>), EPZ sellers may need to hold their stock\n  in the facility for <b class=\"guide-markup\">up to 20 days</b> before Fleek\n  picks it up or shares further delivery instructions.\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">Why are my sea links not converting?</span>\n  </summary>\n  A few common reasons:\n  <ul class=\"guide-markup\">\n    <li class=\"guide-markup\">\n      The buyer is weighing the longer wait against the saving - sea converts\n      best on <b class=\"guide-markup\">heavy or high-value lots</b>.\n    </li>\n    <li class=\"guide-markup\">\n      The saving is <b class=\"guide-markup\">not being made visible</b> to the\n      buyer.\n    </li>\n    <li class=\"guide-markup\">The link was shared but payment was never completed.</li>\n  </ul>\n  <b class=\"guide-markup\">Tip:</b> Always communicate the potential savings to\n  the buyer explicitly when sharing a sea link.\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">In which regions is the sea shipping option currently available?</span>\n  </summary>\n  <b class=\"guide-markup\">It is available for buyers from all over the world. Only PK sellers are eligible to avail sea-shipping though.\n</b></details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":48295960376091,"title":"Fleek Role Based Access Management System — Staff Accounts and Roles","body":"<figure class=\"wysiwyg-media\"><div data-oembed-url=\"https://www.loom.com/share/edc49d88ca5746a8818fb64afd16ec36\"><iframe src=\"//www.loom.com/embed/edc49d88ca5746a8818fb64afd16ec36\" frameborder=\"0\" allowfullscreen=\"\" allow=\"encrypted-media\" style=\"width: 100%; aspect-ratio: 16 / 9;\"></iframe></div></figure><p> </p><p>The newly launched of Fleek Role Based Access Management System allows you to create separate logins for your team members on the Fleek Vendor App. Each person gets their own username and password, and sees only the authorized sections/ parts of the Fleek Application they need for their job.</p><p>Your own login stays exactly the same. Team Management is a new section in the app where you can create, manage, and remove staff accounts.</p><hr><h2 id=\"h_01KMMP1XZHBHHPH9M9ZEG51KC5\"><strong>Understanding Roles:</strong></h2><div><section dir=\"auto\" data-turn-id=\"request-WEB:33cd1f0d-59e2-4400-8bff-e0f53668fc04-30\" data-testid=\"conversation-turn-28\" data-scroll-anchor=\"true\" data-turn=\"assistant\"><div><div><div><div dir=\"auto\" tabindex=\"0\" data-message-author-role=\"assistant\" data-message-id=\"6e312d63-cb11-49b5-8a82-a1fc5c40d2d8\" data-message-model-slug=\"gpt-5-3\" data-turn-start-message=\"true\"><div><div>\n<p data-start=\"0\" data-end=\"210\" data-is-last-node=\"\" data-is-only-node=\"\">When creating a staff account, you assign a role. Each role determines which parts of the app the user can access. Any sections they don’t have permission for are completely hidden and won’t be visible to them.</p>\n<figure class=\"wysiwyg-table wysiwyg-table-align-left\" style=\"width: 100%;\"><table class=\"wysiwyg-table-resized\" style=\"margin-left: 0px; margin-right: auto;\">\n<colgroup>\n<col style=\"width: 13%;\">\n<col style=\"width: 48%;\">\n<col style=\"width: 39%;\">\n</colgroup>\n<thead><tr>\n<th><strong>Role</strong></th>\n<th><strong>Access</strong></th>\n<th><strong>Best For</strong></th>\n</tr></thead>\n<tbody>\n<tr>\n<td><strong>Owner</strong></td>\n<td>Full access to everything. Only role that can see Payouts and manage Team settings.</td>\n<td>Business owner with complete control over all operations.</td>\n</tr>\n<tr>\n<td><strong>Admin</strong></td>\n<td>Full access except Payouts. Can access Inventory, Orders, Upload, Tools, and Chat.</td>\n<td>Trusted manager or partner handling day-to-day operations.</td>\n</tr>\n<tr>\n<td><strong>Associate</strong></td>\n<td>Can manage listings and respond to buyers. Access to Inventory, Upload, and Chat.</td>\n<td>Staff responsible for product uploads and buyer communication.</td>\n</tr>\n<tr>\n<td><strong>Picker</strong></td>\n<td>Can access Inventory (without Trending tab), Orders (view only, no prices), and Upload.</td>\n<td>Warehouse or fulfilment staff handling grading and order picking.</td>\n</tr>\n</tbody>\n</table></figure><hr>\n<h3 id=\"h_01KMMP5TP5KRSDCYNMWN4J12A9\"><strong>How to Add a Team Member</strong></h3>\n<p><strong>Step 1:</strong> Open the Fleek Vendor App and go to <strong>Team Management</strong>.</p>\n<p><strong>Step 2:</strong> Tap <strong>\"Add Team Member\"</strong>.</p>\n<p><strong>Step 3:</strong> Fill in the form:</p>\n<ul>\n<li data-list-item-id=\"ed4357877042846d12c19040c4e336c21\">\n<strong>Full Name</strong> — their real name (e.g., Ahmed Khan)</li>\n<li data-list-item-id=\"e9c702ed9d680eb3785205fa15561d278\">\n<strong>Username</strong> — a short name they'll use to log in (e.g., ahmed)</li>\n<li data-list-item-id=\"e778c8827237b17c164d4de5b36f1b4bd\">\n<strong>Password</strong> — set a password for them</li>\n<li data-list-item-id=\"e2c734ea49af29999199d3c3851efe133\">\n<strong>Role</strong> — choose what they can access (see roles below)</li>\n</ul>\n<p><strong>Step 4:</strong> Tap <strong>\"Create\"</strong>. The account is created instantly.</p>\n<p><strong>Step 5:</strong> Tap <strong>\"Copy login details\"</strong> to get a ready-to-share message with their username and password. Send it to them via WhatsApp or tell them in person.</p>\n<figure class=\"wysiwyg-image\"><img style=\"aspect-ratio: 2560/1440;\" src=\"https://support.joinfleek.com/hc/article_attachments/48311360327835\" width=\"2560\" height=\"1440\"></figure><hr>\n<h2 id=\"h_01KMMPKK41VS5HX5QW7KXS3SW8\"><strong>Permission Matrix:</strong></h2>\n<figure class=\"wysiwyg-table wysiwyg-table-align-left\" style=\"width: 100%;\"><table class=\"wysiwyg-table-resized\" id=\"eac44984-b5c2-4f1e-8546-c550f81c593f\">\n<colgroup>\n<col style=\"width: 19%;\">\n<col style=\"width: 17%;\">\n<col style=\"width: 16%;\">\n<col style=\"width: 15%;\">\n<col style=\"width: 12%;\">\n<col style=\"width: 11%;\">\n<col style=\"width: 10%;\">\n</colgroup>\n<thead><tr id=\"9d5a580d-52f2-46e8-a7b5-94eecc149974\">\n<th id=\"H|]t\">Role</th>\n<th id=\"jhgi\">Inventory</th>\n<th id=\"chON\">Orders</th>\n<th id=\"A]Ir\">Upload</th>\n<th id=\"\\AU{\">Tools</th>\n<th id=\"qLWC\">Chat</th>\n<th id=\"cQ;Q\">Payouts</th>\n</tr></thead>\n<tbody>\n<tr id=\"07c18fb0-01b6-4653-a832-666c03472847\">\n<td id=\"H|]t\"><strong>Owner</strong></td>\n<td id=\"jhgi\">✓</td>\n<td id=\"chON\">✓</td>\n<td id=\"A]Ir\">✓</td>\n<td id=\"\\AU{\">✓</td>\n<td id=\"qLWC\">✓</td>\n<td id=\"cQ;Q\">✓</td>\n</tr>\n<tr id=\"d4bd26b4-6e72-4fd3-9204-4ee4262a7aa7\">\n<td id=\"H|]t\"><strong>Admin</strong></td>\n<td id=\"jhgi\">✓</td>\n<td id=\"chON\">✓</td>\n<td id=\"A]Ir\">✓</td>\n<td id=\"\\AU{\">✓</td>\n<td id=\"qLWC\">✓</td>\n<td id=\"cQ;Q\">—</td>\n</tr>\n<tr id=\"0532796f-e9ba-47fe-aee5-905a78ce4e68\">\n<td id=\"H|]t\"><strong>Associate</strong></td>\n<td id=\"jhgi\">✓</td>\n<td id=\"chON\">—</td>\n<td id=\"A]Ir\">✓</td>\n<td id=\"\\AU{\">—</td>\n<td id=\"qLWC\">✓</td>\n<td id=\"cQ;Q\">—</td>\n</tr>\n<tr id=\"2cb7f15e-ec62-48f1-82d9-cf2543a020c4\">\n<td id=\"H|]t\"><strong>Picker</strong></td>\n<td id=\"jhgi\">✓ (no Trending)</td>\n<td id=\"chON\">View only (no prices)</td>\n<td id=\"A]Ir\">✓</td>\n<td id=\"\\AU{\">—</td>\n<td id=\"qLWC\">—</td>\n<td id=\"cQ;Q\">—</td>\n</tr>\n</tbody>\n</table></figure><p><span data-token-index=\"0\">Important:</span> Only the owner of a Seller Account can ever see Payouts. Even Admins cannot access your financial information.</p>\n<hr>\n<h2 id=\"h_01KMMQ574KZWYTDRWHA1MCKGV3\"><strong>How to Reset a Staff Password</strong></h2>\n<p><strong>Step 1:</strong> Go to <strong>Team Management</strong>.</p>\n<p><strong>Step 2:</strong> Tap on the staff member's name.</p>\n<p><strong>Step 3:</strong> Tap <strong>\"Reset Password\"</strong> and set a new password.</p>\n<p><strong>Step 4:</strong> Share the new password with them.</p>\n<figure class=\"wysiwyg-image\"><img style=\"aspect-ratio: 2560/1440;\" src=\"https://support.joinfleek.com/hc/article_attachments/48311360330907\" width=\"2560\" height=\"1440\"></figure><hr>\n<h2 id=\"h_01KMMQ574P6G9B5BYZQK29Y9S8\"><strong>How to Remove a Team Member</strong></h2>\n<p><strong>Step 1:</strong> Go to <strong>Team Management</strong>.</p>\n<p><strong>Step 2:</strong> Tap on the staff member's name.</p>\n<p><strong>Step 3:</strong> Tap <strong>\"Remove Access\"</strong>.</p>\n<p>They will lose access immediately on all devices. Any work they were doing in the app is not affected — uploaded items and messages remain.</p>\n<figure class=\"wysiwyg-image\"><img style=\"aspect-ratio: 2560/1440;\" src=\"https://support.joinfleek.com/hc/article_attachments/48311375698331\" width=\"2560\" height=\"1440\"></figure><hr>\n<h2 class=\"guide-markup\" id=\"h_01K7SA64WRQCA2CBVRK6VJYT2P\" data-start=\"1937\" data-end=\"1957\"><strong class=\"guide-markup\">Frequently Asked Question</strong></h2>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. What changes for me?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Nothing changes unless you choose to create staff accounts. Your login and\n    everything you see stays exactly the same. You will now also have access\n    to the Team Management section.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. Can my staff see my financial info?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    No. Only the Owner can view Payouts. Admins and other staff members do not\n    have access to financial information.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. How many staff can I add?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    There is no limit. You can add as many staff members as needed to manage\n    your store.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. Can I change someone's role later?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Currently, roles cannot be edited. You will need to remove the staff account\n    and create a new one with the correct role. Improvements for this are in\n    progress.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. What if I forget my staff's password?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    You can reset your staff member’s password at any time through the Team Management\n    section.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">6. My staff member can't log in.</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Ensure they are using the correct format: username@storehandle (for example,\n    ahmed@creed-vintage). If the issue persists, reset their password from Team\n    Management.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">7. I used to share my login with staff. Does that still work?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes, your existing login (email and password) still works. However, you can\n    now create separate staff accounts so your team does not need access to your\n    personal login, keeping your Payouts private.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">8. What happens if I remove a staff member?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    The staff member will lose access immediately on all devices. Any items they\n    uploaded or messages they sent will remain unchanged and will not be deleted.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">9. Who can use Team Management?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Only the account owner of the seller account can create and manage staff accounts. Staff members cannot\n    create accounts for other people.\n  </div>\n</details><hr>\n<div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>\n</div></div></div></div></div></div></section></div>"},{"id":43605410943387,"title":"Protected Payouts for Selected Orders - Policy & Guidelines","body":"<h2 id=\"h_01KANY7K627SAQGXZT37VBJ5CK\" data-start=\"279\" data-end=\"315\"><strong data-start=\"282\" data-end=\"315\">1. Why We are Updating Payouts</strong></h2><p data-start=\"316\" data-end=\"560\">Fleek is entering a new phase of growth with higher order volumes, larger buyers, and stronger expectations around quality and authenticity. To support sellers in this next stage, we are updating how payouts are handled for <strong data-start=\"540\" data-end=\"559\">selected orders</strong>.</p><p data-start=\"562\" data-end=\"589\">This update is designed to:</p><ul data-start=\"591\" data-end=\"761\">\n<li data-start=\"591\" data-end=\"652\" data-list-item-id=\"ee197115ef804897decfab1560d364fa5\"><p data-start=\"593\" data-end=\"652\">Increase buyer confidence for larger and repeat purchases</p></li>\n<li data-start=\"653\" data-end=\"712\" data-list-item-id=\"e8738a56b68dee1e2c1f9817f26162455\"><p data-start=\"655\" data-end=\"712\">Protect the reputation of serious, Top-Performing &amp; Trusted sellers</p></li>\n<li data-start=\"713\" data-end=\"761\" data-list-item-id=\"e53ce26280d46c73813b4f8e14414c520\"><p data-start=\"715\" data-end=\"761\">Reduce the impact of late or unfair disputes</p></li>\n</ul><p data-start=\"763\" data-end=\"839\">As part of this improvement, we’re introducing a <strong data-start=\"812\" data-end=\"833\">Protected Payouts</strong> flow.</p><hr data-start=\"841\" data-end=\"844\"><h2 id=\"h_01KANY7K6BBAR0KM079PEK7AB1\" data-start=\"846\" data-end=\"885\"><strong data-start=\"849\" data-end=\"885\">2. What Are “Protected Payouts”?</strong></h2><p data-start=\"886\" data-end=\"944\">Protected Payouts split the seller payout into two stages:</p><ul data-start=\"946\" data-end=\"1093\">\n<li data-start=\"946\" data-end=\"984\" data-list-item-id=\"e5cb668fbe68981590eb015140fcaa7d9\"><p data-start=\"948\" data-end=\"984\"><strong>50% of the payout will be released post-QC approval, handover, or fulfillment</strong>, according to the applicable regional policy.</p></li>\n<li data-start=\"985\" data-end=\"1093\" data-list-item-id=\"ef0acf75f08656aa1465f273b4cfd0b51\"><p data-start=\"987\" data-end=\"1093\"><strong data-start=\"987\" data-end=\"1025\">50% released 7 days after delivery</strong>, provided no product quality complaint is raised during this period</p></li>\n</ul><p data-start=\"1095\" data-end=\"1132\">The 7-day post-delivery window helps:</p><ul data-start=\"1134\" data-end=\"1305\">\n<li data-start=\"1134\" data-end=\"1178\" data-list-item-id=\"e3cb134c678c65a3d59d60e6a2298c4af\"><p data-start=\"1136\" data-end=\"1178\">Ensure products match buyer expectations</p></li>\n<li data-start=\"1179\" data-end=\"1223\" data-list-item-id=\"ec87fbbe35752223b15d998411cf2a060\"><p data-start=\"1181\" data-end=\"1223\">Reduce late disputes or quality concerns</p></li>\n<li data-start=\"1224\" data-end=\"1305\" data-list-item-id=\"e22e753e2b1b2df51988e2dd6c9299c17\"><p data-start=\"1226\" data-end=\"1305\">Maintain a safer and more trustworthy marketplace for both sellers and buyers</p></li>\n</ul><p data-start=\"1307\" data-end=\"1359\">This approach is standard among global marketplaces.</p><hr data-start=\"1361\" data-end=\"1364\"><h2 id=\"h_01KANY7K6M0QZX60EM966JMRD3\" data-start=\"1366\" data-end=\"1408\"><strong data-start=\"1369\" data-end=\"1408\">3. Which Orders Does This Apply To?</strong></h2><p data-start=\"1409\" data-end=\"1548\">Protected Payouts apply <strong data-start=\"1433\" data-end=\"1475\">only to selected orders and/or sellers</strong> where an additional short protection period improves transaction safety.</p><p data-start=\"1550\" data-end=\"1567\">This may include:</p><ul data-start=\"1569\" data-end=\"1730\">\n<li data-start=\"1569\" data-end=\"1596\" data-list-item-id=\"ee0cc60ca28f789de6cd782363d986ac2\"><p data-start=\"1571\" data-end=\"1596\">Certain Newly onboarded sellers</p></li>\n<li data-start=\"1597\" data-end=\"1659\" data-list-item-id=\"ed7e188eea88eaaa909df5e40e109f8b8\"><p data-start=\"1599\" data-end=\"1659\">Orders that meet certain internal risk or quality criteria</p></li>\n<li data-start=\"1660\" data-end=\"1730\" data-list-item-id=\"ef7940df96cb3675b08241d257de16f2c\"><p data-start=\"1662\" data-end=\"1730\">Orders flagged based on operational signals or historical patterns</p></li>\n</ul><p data-start=\"1732\" data-end=\"1805\">We use a combination of automated checks and manual reviews to determine when an order falls under Protected Payouts.</p><blockquote data-start=\"1807\" data-end=\"1894\"><p data-start=\"1809\" data-end=\"1894\"><em data-start=\"1812\" data-end=\"1894\"><em>To ensure fairness, Fleek does not disclose specific risk signals or thresholds.</em></em></p></blockquote><p data-start=\"1896\" data-end=\"1944\">Not all orders in your account will be impacted.</p><hr data-start=\"1946\" data-end=\"1949\"><h2 id=\"h_01KANY7K6V5MCRP5XZYSDME5M6\" data-start=\"1951\" data-end=\"1996\"><strong data-start=\"1954\" data-end=\"1996\">4. How the Payout Works (Step-by-Step)</strong></h2><figure class=\"wysiwyg-image\"><img style=\"aspect-ratio: 2543/422;\" src=\"https://support.joinfleek.com/hc/article_attachments/43605366570651\" width=\"2543\" height=\"422\"></figure><h3 id=\"h_01KANY7K6WH96H3RYBG0Y7MW7W\" data-start=\"1998\" data-end=\"2038\"><strong data-start=\"2002\" data-end=\"2038\">Step 1: Order Placed &amp; Processed</strong></h3><p data-start=\"2039\" data-end=\"2095\">The buyer places the order and it is processed as usual.</p><h3 id=\"h_01KANY7K6X7PGYVWZJR9B20VJ7\" data-start=\"2097\" data-end=\"2124\"><strong data-start=\"2101\" data-end=\"2124\">Step 2: Order Fulfilled</strong></h3><p data-start=\"2125\" data-end=\"2176\">After the order clears Fleek QC or is fulfilled, the payout calculation begins.</p><h3 id=\"h_01KANY7K6Y13GGZ8V4E591BHPC\" data-start=\"2178\" data-end=\"2212\"><strong data-start=\"2182\" data-end=\"2212\">Step 3: First Payout — 50%</strong></h3><p data-start=\"2213\" data-end=\"2313\">50% of the payout (after commission and shipping) is released according to your normal payout cycle.</p><h3 id=\"h_01KANY7K6ZD5KDVZRTH51ETKST\" data-start=\"2315\" data-end=\"2362\"><strong data-start=\"2319\" data-end=\"2362\">Step 4: Delivery + 7-Day Quality Window</strong></h3><p data-start=\"2363\" data-end=\"2455\">Once delivered, a 7-day window begins where buyers can raise product quality issues such as:</p><ul data-start=\"2457\" data-end=\"2533\">\n<li data-start=\"2457\" data-end=\"2477\" data-list-item-id=\"e8c62995c36ff54c93c508f80673c59a2\"><p data-start=\"2459\" data-end=\"2477\">Not as described</p></li>\n<li data-start=\"2478\" data-end=\"2507\" data-list-item-id=\"e0b79c9a01961a29bbb9441126fb000fa\"><p data-start=\"2480\" data-end=\"2507\">Undisclosed major defects</p></li>\n<li data-start=\"2508\" data-end=\"2533\" data-list-item-id=\"eb99418ab94d5e9e628d145ee0d171ca9\"><p data-start=\"2510\" data-end=\"2533\">Authenticity concerns</p></li>\n</ul><h3 id=\"h_01KANY7K73TM58Q4D4RXK1FAXQ\" data-start=\"2535\" data-end=\"2580\"><strong data-start=\"2539\" data-end=\"2580\">Step 5: Second Payout — Remaining 50%</strong></h3><p data-start=\"2581\" data-end=\"2698\">If no quality complaint is raised within 7 days, the remaining payout is released in the next available payout cycle.</p><p data-start=\"2700\" data-end=\"2809\">If a complaint is raised, the second payout of that specific order may be held temporarily or adjusted depending on the outcome (for example, in case of returns, partial refunds, etc).</p><hr data-start=\"2811\" data-end=\"2814\"><h2 id=\"h_01KANY7K75PEJ36Y4RRZYMQ5RD\" data-start=\"2816\" data-end=\"2871\"><strong data-start=\"2819\" data-end=\"2871\">5. What If There Is a Product Quality Complaint?</strong></h2><p data-start=\"2872\" data-end=\"2917\">If a buyer opens a product quality complaint:</p><ul data-start=\"2919\" data-end=\"3051\">\n<li data-start=\"2919\" data-end=\"2966\" data-list-item-id=\"e29e41d52c47f20a39a89c3e267512d04\"><p data-start=\"2921\" data-end=\"2966\">The second 50% payout is <strong data-start=\"2946\" data-end=\"2966\">temporarily held</strong></p></li>\n<li data-start=\"2967\" data-end=\"3051\" data-list-item-id=\"e9b1d9233258d0a51432cb88b792d95f9\"><p data-start=\"2969\" data-end=\"3051\">Fleek reviews the case, including buyer evidence, listing details, and QC images</p></li>\n</ul><p data-start=\"3053\" data-end=\"3076\">The held payout may be:</p><ul data-start=\"3078\" data-end=\"3319\">\n<li data-start=\"3078\" data-end=\"3140\" data-list-item-id=\"e351d0c9bd77b133e1392c0fb96057997\"><p data-start=\"3080\" data-end=\"3140\"><strong data-start=\"3080\" data-end=\"3100\">Released in full</strong> if the item is confirmed as described</p></li>\n<li data-start=\"3141\" data-end=\"3215\" data-list-item-id=\"e59b559d293ae367093a1a0153ae9200e\"><p data-start=\"3143\" data-end=\"3215\"><strong data-start=\"3143\" data-end=\"3177\">Partially released or adjusted</strong> if a partial compensation is agreed</p></li>\n<li data-start=\"3216\" data-end=\"3319\" data-list-item-id=\"eeebca5f65a674bc216acc774154baa5b\"><p data-start=\"3218\" data-end=\"3319\"><strong data-start=\"3218\" data-end=\"3243\">Used to cover refunds</strong> if the product clearly fails to meet quality or authenticity expectations</p></li>\n</ul><p data-start=\"3321\" data-end=\"3388\">The goal is to ensure fairness while preventing misuse of disputes.</p><hr data-start=\"3390\" data-end=\"3393\"><h2 id=\"h_01KANY7K7BCXBDTCZR03RF14G4\" data-start=\"3395\" data-end=\"3452\"><strong data-start=\"3398\" data-end=\"3452\">6. Does This Mean Fleek Doesn’t Trust My Business?</strong></h2><p data-start=\"3453\" data-end=\"3543\">No. Protected Payouts are introduced to <strong data-start=\"3495\" data-end=\"3523\">support reliable sellers</strong>, not penalize them.</p><p data-start=\"3545\" data-end=\"3555\">They help:</p><ul data-start=\"3557\" data-end=\"3709\">\n<li data-start=\"3557\" data-end=\"3603\" data-list-item-id=\"e88c23534f249901d26854698e1d43883\"><p data-start=\"3559\" data-end=\"3603\">Reduce the impact of unfair or late claims</p></li>\n<li data-start=\"3604\" data-end=\"3641\" data-list-item-id=\"e9d0ad549fd56caf7cd8408cc522dd0aa\"><p data-start=\"3606\" data-end=\"3641\">Improve buyer trust and retention</p></li>\n<li data-start=\"3642\" data-end=\"3709\" data-list-item-id=\"e9a672b561d4c426b31bb0a34434f5055\"><p data-start=\"3644\" data-end=\"3709\">Maintain quality and authenticity standards across the platform</p></li>\n</ul><p data-start=\"3711\" data-end=\"3782\">As Fleek grows, these protections ensure good sellers can scale safely.</p><hr data-start=\"3784\" data-end=\"3787\"><h2 id=\"h_01KANY7K7GW6SGR3TZKKC31NFK\" data-start=\"3789\" data-end=\"3842\"><strong data-start=\"3792\" data-end=\"3842\">7. Can I Move to Faster Payouts in the Future?</strong></h2><p data-start=\"3843\" data-end=\"3980\">Yes.<br>While we don’t disclose exact internal thresholds, sellers naturally move toward more flexible payout flows when they demonstrate:</p><ul data-start=\"3982\" data-end=\"4210\">\n<li data-start=\"3982\" data-end=\"4017\" data-list-item-id=\"ea7605caf7053f8047406be8df3a1fcf0\"><p data-start=\"3984\" data-end=\"4017\">Low producty quality complaint and dispute rates</p></li>\n<li data-start=\"4018\" data-end=\"4045\" data-list-item-id=\"e668aef1fc44be733d721ac9044b9e75d\"><p data-start=\"4020\" data-end=\"4045\">Strong grading accuracy</p></li>\n<li data-start=\"4046\" data-end=\"4091\" data-list-item-id=\"e7a8d9f224d8c2fdbd6b54a5e6c7b6258\"><p data-start=\"4048\" data-end=\"4091\">Good authenticity and quality performance</p></li>\n<li data-start=\"4092\" data-end=\"4149\" data-list-item-id=\"e651ea6ce94373c2b0e293d1fad5917e4\"><p data-start=\"4094\" data-end=\"4149\">Policy compliance (listings, shipping, communication)</p></li>\n<li data-start=\"4150\" data-end=\"4210\" data-list-item-id=\"e666ec0b6dd572eb7a4dc7e11e10dfc10\"><p data-start=\"4152\" data-end=\"4210\">Reliable operations (e.g., dispatch time, documentation)</p></li>\n</ul><p data-start=\"4212\" data-end=\"4264\">Fleek regularly reviews accounts and order patterns.</p><hr data-start=\"4266\" data-end=\"4269\"><h2 id=\"h_01KANY7K7MCXCZ30SGPTSJC8M8\" data-start=\"4271\" data-end=\"4333\"><strong data-start=\"4274\" data-end=\"4333\">8. Where Can I See If an Order Is on Protected Payouts?</strong></h2><p data-start=\"4334\" data-end=\"4398\">Protected Payout orders are clearly labeled in your payout view.</p><p data-start=\"4400\" data-end=\"4440\">You will see a payout breakdown such as:</p><p data-start=\"4442\" data-end=\"4519\"><strong data-start=\"4442\" data-end=\"4519\">50% on QC Approved • 50% after delivery + 7 days (no quality complaint)</strong></p><hr data-start=\"4521\" data-end=\"4524\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    Pakistan: 11:00 AM – 7:00 PM PKT |\n    India: 10:30 AM – 6:30 PM IST |\n    UK: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n  </p>\n</div>"},{"id":42618250910619,"title":"Seller Sign-up Journey: Become a Seller at Fleek","body":"<p class=\"guide-markup\" data-start=\"122\" data-end=\"259\"><span style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Ready to take your used clothing business global?</strong></span></span><strong class=\"guide-markup\"> </strong>You’re in the right place! Follow these simple steps to start selling on Fleek.</p><figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 6000/3375;\" src=\"https://support.joinfleek.com/hc/article_attachments/42618266612891\" alt=\"1.png\" width=\"6000\" height=\"3375\"></figure><figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 6000/3375;\" src=\"https://support.joinfleek.com/hc/article_attachments/42618250899739\" alt=\"2.png\" width=\"6000\" height=\"3375\"></figure><figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 6000/3375;\" src=\"https://support.joinfleek.com/hc/article_attachments/42618266615195\" alt=\"3.png\" width=\"6000\" height=\"3375\"></figure><figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 6000/3375;\" src=\"https://support.joinfleek.com/hc/article_attachments/42618266616859\" alt=\"4.png\" width=\"6000\" height=\"3375\"></figure><figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 6000/3375;\" src=\"https://support.joinfleek.com/hc/article_attachments/42618266619419\" alt=\"5.png\" width=\"6000\" height=\"3375\"></figure><figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 6000/3375;\" src=\"https://support.joinfleek.com/hc/article_attachments/42618266621467\" alt=\"6.png\" width=\"6000\" height=\"3375\"></figure><p class=\"guide-markup\" data-start=\"73\" data-end=\"171\"><strong class=\"guide-markup\">Congratulations! You’re now part of the world’s largest wholesale used clothing community. Click </strong><a class=\"guide-markup\" href=\"https://support.joinfleek.com/hc/en-us/articles/42542690484251\"><strong class=\"guide-markup\">here</strong></a><strong class=\"guide-markup\"> to complete your onboarding journey and explore our policies.</strong></p><hr><div style=\"text-align: center; margin: 30px 0;\" class=\"guide-markup\">\n  <p style=\"font-size: 18px; font-weight: bold; margin-bottom: 15px;\" class=\"guide-markup\">\n    Download the Fleek Seller App\n  </p>\n  <a target=\"_blank\" style=\"margin: 0 5px;\" class=\"guide-markup\">\n    <img src=\"https://upload.wikimedia.org/wikipedia/commons/7/78/Google_Play_Store_badge_EN.svg\" alt=\"Get it on Google Play\" style=\"height: 30px;\" class=\"guide-markup\">\n  </a><a target=\"_blank\" style=\"margin: 0 10px;\" class=\"guide-markup\">\n    <img src=\"https://developer.apple.com/assets/elements/badges/download-on-the-app-store.svg\" alt=\"Download on the App Store\" style=\"height: 30px;\" class=\"guide-markup\">\n  </a>\n</div><hr><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42618052047771,"title":"Stock Liquidation Policy","body":"<p class=\"guide-markup\"><strong class=\"guide-markup\" data-start=\"206\" data-end=\"234\">Stock Liquidation Policy</strong> ensures fair management of items <strong class=\"guide-markup\" data-start=\"268\" data-end=\"304\">returned to Fleek’s UK warehouse</strong> and <strong class=\"guide-markup\" data-start=\"309\" data-end=\"342\">stored for an extended period</strong>.</p><p class=\"guide-markup\">It helps Fleek <strong class=\"guide-markup\" data-start=\"361\" data-end=\"388\">free up warehouse space</strong>, <strong class=\"guide-markup\" data-start=\"390\" data-end=\"424\">recover operational efficiency</strong>, and <strong class=\"guide-markup\" data-start=\"430\" data-end=\"459\">maintain smooth logistics</strong>.</p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K860VTPWBEJJN8J1X1XN91JM\"><strong class=\"guide-markup\" data-start=\"239\" data-end=\"257\">Why It Matters</strong></h2><ul class=\"guide-markup\" data-start=\"259\" data-end=\"547\">\n<li class=\"guide-markup\" data-start=\"259\" data-end=\"337\" data-list-item-id=\"e3be2b49c352a4a4466b5dfaba40cb2db\"><p class=\"guide-markup\" data-start=\"261\" data-end=\"337\">Prevents long-term storage of returned items and reduces operational costs</p></li>\n<li class=\"guide-markup\" data-start=\"338\" data-end=\"405\" data-list-item-id=\"ef7473e56473d88f9e2e7ea83f2eb1912\"><p class=\"guide-markup\" data-start=\"340\" data-end=\"405\">Frees up valuable warehouse space for active and incoming stock</p></li>\n<li class=\"guide-markup\" data-start=\"406\" data-end=\"472\" data-list-item-id=\"ef84d06a7857dd727e5164948c8e27c7f\"><p class=\"guide-markup\" data-start=\"408\" data-end=\"472\">Helps Fleek maintain smooth and efficient warehouse operations</p></li>\n<li class=\"guide-markup\" data-start=\"473\" data-end=\"547\" data-list-item-id=\"e61e481b37e0b81b01eef4ba177e40527\"><p class=\"guide-markup\" data-start=\"475\" data-end=\"547\">Ensures better inventory management and overall marketplace efficiency</p></li>\n</ul><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K862SDAHA03YR4C71YB2MVJ9\"><strong class=\"guide-markup\" data-start=\"718\" data-end=\"734\">How It Works</strong></h2><p class=\"guide-markup\" data-start=\"736\" data-end=\"840\">Whenever a buyer returns an item and it reaches Fleek’s UK warehouse, the following process takes place:</p><ol class=\"guide-markup\" data-start=\"842\" data-end=\"1421\">\n<li class=\"guide-markup ck-list-marker-bold\" data-start=\"842\" data-end=\"1135\" data-list-item-id=\"e91980a2e185df1419626ae520f51b38d\">\n<p class=\"guide-markup\" data-start=\"845\" data-end=\"864\"><strong class=\"guide-markup\" data-start=\"845\" data-end=\"864\">Item Inbounding</strong></p>\n<ul class=\"guide-markup\" data-start=\"868\" data-end=\"1135\">\n<li class=\"guide-markup\" data-start=\"868\" data-end=\"1032\" data-list-item-id=\"ec994b5afa3564018fbfa9065a972d214\"><p class=\"guide-markup\" data-start=\"870\" data-end=\"1032\">Once the returned parcel is received and inbounded into the warehouse system, Fleek <strong class=\"guide-markup\" data-start=\"953\" data-end=\"978\">notifies the supplier</strong> via the <strong class=\"guide-markup\" data-start=\"987\" data-end=\"1029\">chat section in the Vendor Application</strong>.</p></li>\n<li class=\"guide-markup\" data-start=\"1036\" data-end=\"1135\" data-list-item-id=\"ee640ef518e7ad2775dd937a61b7cbad2\"><p class=\"guide-markup\" data-start=\"1038\" data-end=\"1135\">The notification informs the supplier that their returned item is now available in the warehouse.</p></li>\n</ul>\n</li>\n<li class=\"guide-markup ck-list-marker-bold\" data-start=\"1137\" data-end=\"1421\" data-list-item-id=\"ee3366104fa2e52c3828f323640ec3ad6\">\n<p class=\"guide-markup\" data-start=\"1140\" data-end=\"1160\"><strong class=\"guide-markup\" data-start=\"1140\" data-end=\"1160\">Liquidation Days</strong></p>\n<ul class=\"guide-markup\" data-start=\"1164\" data-end=\"1421\">\n<li class=\"guide-markup\" data-start=\"1164\" data-end=\"1333\" data-list-item-id=\"e86a47ab34c4a210a716f84afc968f73b\"><p class=\"guide-markup\" data-start=\"1166\" data-end=\"1333\">Each returned item is assigned a specific <strong class=\"guide-markup\" data-start=\"1208\" data-end=\"1230\">liquidation period</strong> — this refers to the <strong class=\"guide-markup\" data-start=\"1252\" data-end=\"1310\">time limit during which the item will remain available</strong> in the UK warehouse.</p></li>\n<li class=\"guide-markup\" data-start=\"1337\" data-end=\"1421\" data-list-item-id=\"ee44c4a7d55c97dda2cb0a8c841dedde2\"><p class=\"guide-markup\" data-start=\"1339\" data-end=\"1421\">Once this time limit expires, the item will be <strong class=\"guide-markup\" data-start=\"1386\" data-end=\"1399\">discarded</strong> from the warehouse.</p></li>\n</ul>\n</li>\n<li class=\"guide-markup ck-list-marker-bold\" data-start=\"1137\" data-end=\"1421\" data-list-item-id=\"e97f16618a14415d32b15b07a230ac578\">\n<p class=\"guide-markup\" data-start=\"1140\" data-end=\"1160\"><strong class=\"guide-markup\" data-start=\"1140\" data-end=\"1160\">Moving Items from the UK Warehouse</strong></p>\n<ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-start=\"1164\" data-end=\"1333\" data-list-item-id=\"e3e923e4efd82d5ed3e89b3e7a718c0d8\"><p class=\"guide-markup\" data-start=\"1166\" data-end=\"1333\"><strong class=\"guide-markup\" data-start=\"478\" data-end=\"499\">New Order Placed:</strong> The returned item can be included in a new customer order.</p></li>\n<li class=\"guide-markup\" data-start=\"1337\" data-end=\"1421\" data-list-item-id=\"ec14d6d87895cf3f4218fbf0d6bb685a0\"><p class=\"guide-markup\" data-start=\"1339\" data-end=\"1421\"><strong class=\"guide-markup\" data-start=\"563\" data-end=\"588\">Sent to Own Facility:</strong> The supplier can request to have the item shipped back to their own warehouse or location.</p></li>\n<li class=\"guide-markup\" data-start=\"1337\" data-end=\"1421\" data-list-item-id=\"e75afbb60a480b115d0004938b9285486\"><p class=\"guide-markup\" data-start=\"1339\" data-end=\"1421\"><strong class=\"guide-markup\" data-start=\"684\" data-end=\"713\">Sent to Offline Customer:</strong> The supplier may choose to send the item directly to one of their own customers outside the Fleek platform.</p></li>\n</ul>\n</li>\n</ol><p class=\"guide-markup\" data-start=\"1339\" data-end=\"1421\">These options allow suppliers to manage their returned stock proactively and prevent it from being discarded after the liquidation period.</p><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 796/1044;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42618067483163\" width=\"796\" height=\"1044\"></figure><hr class=\"guide-markup\" data-start=\"1423\" data-end=\"1426\"><h2 class=\"guide-markup\" id=\"h_01K862SDC6Y1NNZ5ZKJ88DXG4A\"><strong class=\"guide-markup\" data-start=\"1432\" data-end=\"1457\">Liquidation Timelines</strong></h2><p class=\"guide-markup\" data-start=\"1459\" data-end=\"1523\">The liquidation period depends on <strong class=\"guide-markup\" data-start=\"1493\" data-end=\"1522\">why the item was returned</strong>:</p><h4 class=\"guide-markup\" id=\"h_01K862SDCGEG91P1BDESTN5FY9\" data-start=\"1525\" data-end=\"1569\"><strong class=\"guide-markup\" data-start=\"1530\" data-end=\"1569\">1. Product Quality Campaign Returns</strong></h4><p class=\"guide-markup\" data-start=\"1570\" data-end=\"1721\">If the item was returned as part of a <strong class=\"guide-markup\" data-start=\"1608\" data-end=\"1636\">product quality campaign</strong>, the supplier has a total of <strong class=\"guide-markup\" data-start=\"1666\" data-end=\"1677\">45 days</strong> from the inbounding date to claim the item.</p><p class=\"guide-markup\" data-start=\"1723\" data-end=\"1749\"><strong class=\"guide-markup\" data-start=\"1723\" data-end=\"1749\">Notification Schedule:</strong></p><ul class=\"guide-markup\" data-start=\"1750\" data-end=\"1920\">\n<li class=\"guide-markup\" data-start=\"1750\" data-end=\"1804\" data-list-item-id=\"e5bff2dd6091ed7b535548ed5cfe5b2cd\"><p class=\"guide-markup\" data-start=\"1752\" data-end=\"1804\"><strong class=\"guide-markup\" data-start=\"1752\" data-end=\"1764\">45 Days:</strong> Initial notification (item available)</p></li>\n<li class=\"guide-markup\" data-start=\"1805\" data-end=\"1843\" data-list-item-id=\"e919bae88227d4f325e3b9466ec617f05\"><p class=\"guide-markup\" data-start=\"1807\" data-end=\"1843\"><strong class=\"guide-markup\" data-start=\"1807\" data-end=\"1819\">30 Days:</strong> Reminder notification</p></li>\n<li class=\"guide-markup\" data-start=\"1844\" data-end=\"1875\" data-list-item-id=\"e4b4202d7b6d6308aad3ad80ce6831925\"><p class=\"guide-markup\" data-start=\"1846\" data-end=\"1875\"><strong class=\"guide-markup\" data-start=\"1846\" data-end=\"1858\">15 Days:</strong> Final reminder</p></li>\n<li class=\"guide-markup\" data-start=\"1876\" data-end=\"1920\" data-list-item-id=\"eedfb18e7b8262601f8e37fbfd59c11d7\"><p class=\"guide-markup\" data-start=\"1878\" data-end=\"1920\"><strong class=\"guide-markup\" data-start=\"1878\" data-end=\"1888\">0 Day:</strong> Item discarded from warehouse</p></li>\n</ul><p class=\"guide-markup\" data-start=\"1922\" data-end=\"1977\">In total, <strong class=\"guide-markup\" data-start=\"1932\" data-end=\"1951\">4 notifications</strong> are sent to the supplier.</p><h4 class=\"guide-markup\" id=\"h_01K862SDDYPVPKC3KMDZ8MHJPE\" data-start=\"1984\" data-end=\"2016\"><strong class=\"guide-markup\" data-start=\"1989\" data-end=\"2016\">2. Authenticity Returns</strong></h4><p class=\"guide-markup\" data-start=\"2017\" data-end=\"2147\">If the item was returned due to <strong class=\"guide-markup\" data-start=\"2049\" data-end=\"2074\">authenticity concerns</strong>, the supplier has <strong class=\"guide-markup\" data-start=\"2093\" data-end=\"2103\">5 days</strong> from the inbounding date to claim the item.</p><p class=\"guide-markup\" data-start=\"2149\" data-end=\"2175\"><strong class=\"guide-markup\" data-start=\"2149\" data-end=\"2175\">Notification Schedule:</strong></p><ul class=\"guide-markup\" data-start=\"2176\" data-end=\"2312\">\n<li class=\"guide-markup\" data-start=\"2176\" data-end=\"2229\" data-list-item-id=\"e6ca5d728fd59a2cafbc7b52cc29c0eb1\"><p class=\"guide-markup\" data-start=\"2178\" data-end=\"2229\"><strong class=\"guide-markup\" data-start=\"2178\" data-end=\"2189\">5 Days:</strong> Initial notification (item available)</p></li>\n<li class=\"guide-markup\" data-start=\"2230\" data-end=\"2267\" data-list-item-id=\"eb465719397dbc0cc861e5dedc9097e3b\"><p class=\"guide-markup\" data-start=\"2232\" data-end=\"2267\"><strong class=\"guide-markup\" data-start=\"2232\" data-end=\"2243\">3 Days:</strong> Reminder notification</p></li>\n<li class=\"guide-markup\" data-start=\"2268\" data-end=\"2312\" data-list-item-id=\"ef33d6c818c9e3eff8e08f99b07b7e2ae\"><p class=\"guide-markup\" data-start=\"2270\" data-end=\"2312\"><strong class=\"guide-markup\" data-start=\"2270\" data-end=\"2280\">0 Day:</strong> Item discarded from warehouse</p></li>\n</ul><p class=\"guide-markup\" data-start=\"2314\" data-end=\"2369\">In total, <strong class=\"guide-markup\" data-start=\"2324\" data-end=\"2343\">3 notifications</strong> are sent to the supplier.</p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K86M2661ZDZ7TZ07JPHK55D1\"><strong class=\"guide-markup\" data-start=\"218\" data-end=\"277\">How will I receive notifications for my returned items?</strong></h2><p class=\"guide-markup\">Our team notify each seller after inbounding their items at warehouse.</p><p class=\"guide-markup\">Steps:</p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"eea5c38d20d6ffce4627c7664f76a2fb2\">Go to the Chat section in your Vendor App</li>\n<li class=\"guide-markup\" data-list-item-id=\"ebbaf5178e8d5cb09d1aef5e885bf81dd\">Open the “Liquidation Channel”</li>\n<li class=\"guide-markup\" data-list-item-id=\"e2922a08e5fac9e62303f18af0159294d\">or search with your order number</li>\n<li class=\"guide-markup\" data-list-item-id=\"e4a0aadb44773cf103be82a046435cc08\">You’ll find your order and days remaining in the message</li>\n</ul><figure class=\"wysiwyg-image wysiwyg-image-resized guide-markup\" style=\"width: 44.57%;\"><img style=\"aspect-ratio: 399/759;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42618052042139\" width=\"399\" height=\"759\"></figure><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K87V1MPDJ78DVAKRKKVESDC4\"><strong class=\"guide-markup\" data-start=\"1997\" data-end=\"2022\">Seller Responsibility</strong></h2><ul class=\"guide-markup\" data-start=\"2023\" data-end=\"2302\">\n<li class=\"guide-markup\" data-start=\"2023\" data-end=\"2116\" data-list-item-id=\"e0338c51b794eaf670c4d71bb9e84d8db\">\n<p class=\"guide-markup\" data-start=\"2025\" data-end=\"2116\">Sellers must inform the team and share details mentioned below after the order is placed.</p>\n<p class=\"guide-markup\" data-start=\"2025\" data-end=\"2116\">a) Returned Order's Number</p>\n<p class=\"guide-markup\" data-start=\"2025\" data-end=\"2116\">b) New Order Number </p>\n</li>\n<li class=\"guide-markup\" data-start=\"2117\" data-end=\"2240\" data-list-item-id=\"e0c5858ac922ebe26f7f6677321da026a\">\n<p class=\"guide-markup\" data-start=\"2119\" data-end=\"2240\">If you wish to send your parcel to your own facility or to your own customer. Please reach out to the Seller Support team or your Account Manager and share details mentioned below:</p>\n<p class=\"guide-markup\" data-start=\"2119\" data-end=\"2240\">a) Returned Order's Number</p>\n<p class=\"guide-markup\" data-start=\"2119\" data-end=\"2240\">b) Complete Address and Contact Number</p>\n</li>\n<li class=\"guide-markup\" data-start=\"2241\" data-end=\"2302\" data-list-item-id=\"e5ae877d8f07b81d069118c2247e7a6a3\"><p class=\"guide-markup\" data-start=\"2243\" data-end=\"2302\">If no response is received within the defined deadline, Fleek reserves the right to proceed with liquidation at its own choice.</p></li>\n<li class=\"guide-markup\" data-start=\"2241\" data-end=\"2302\" data-list-item-id=\"e8940dccad0d403718ef805ba117378af\"><p class=\"guide-markup\" data-start=\"2243\" data-end=\"2302\">Liquidated items cannot be withdrawn later.</p></li>\n</ul><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K87VSF2EY1Y198AHWRX6B4AN\"><strong class=\"guide-markup\" data-start=\"1997\" data-end=\"2022\">Frequently Asked Questions</strong></h2><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. How will I be notified about my returned items?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    All notifications are sent through the <strong class=\"guide-markup\">Chat section</strong> in the\n    Vendor Application.  \n    You’ll be informed as soon as your returned items are\n    <strong class=\"guide-markup\">inbounded into Fleek’s UK warehouse</strong> and throughout the\n    <strong class=\"guide-markup\">liquidation timeline</strong>.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. What does “Days in Liquidation” mean?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    “<strong class=\"guide-markup\">Days in Liquidation</strong>” refers to the time period your returned\n    items remain available in Fleek’s UK warehouse before being discarded.  \n    Once this period ends, the items are <strong class=\"guide-markup\">automatically removed</strong>\n    and cannot be retrieved.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. How long do I have to claim my items?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    The claim period depends on the <strong class=\"guide-markup\">reason for return</strong>:\n    <ul style=\"margin-top: 4px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">Product Quality Campaign:</strong> 45 days (notifications\n        at 45, 30, 15, and 0 days)\n      </li>\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">Authenticity Concerns:</strong> 5 days (notifications at\n        5, 3, and 0 days)\n      </li>\n    </ul>\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. What happens if I don’t take action within the liquidation period?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    If no action is taken before the liquidation period ends, Fleek will\n    <strong class=\"guide-markup\">discard the items</strong> from the warehouse.  \n    These items <strong class=\"guide-markup\">cannot be recovered </strong> after disposal.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. How can I move my items from the warehouse?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Suppliers can move their items from the UK warehouse in one of the following\n    ways:\n    <ul style=\"margin-top: 4px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">A new order</li>\n      <li class=\"guide-markup\">Request to send it to your own warehouse or facility</li>\n      <li class=\"guide-markup\">Ship it directly to your own customer</li>\n    </ul>\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">6. Will I be charged for moving my items?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    If a supplier requests shipment to their own facility or customer,\n    <strong class=\"guide-markup\">standard shipping costs</strong> may apply, depending on\n    <strong class=\"guide-markup\">weight and destination</strong>.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">7. Can I request an extension for my liquidation period?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Currently, <strong class=\"guide-markup\">no extensions</strong> are available.  \n    Suppliers are encouraged to take <strong class=\"guide-markup\">timely action</strong> before the\n    liquidation period ends to avoid item discard.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">8. Why are some items given only 5 days while others get 45 days?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    The timeline depends on the <strong class=\"guide-markup\">type of return</strong>:\n    <ul style=\"margin-top: 4px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">Authenticity Concerns:</strong> shorter period (5 days) due\n        to compliance and policy requirements\n      </li>\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">Product Quality Campaigns:</strong> longer period (45 days)\n        to allow fair review and decision-making\n      </li>\n    </ul>\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">9. How will I know when my items are discarded?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    A <strong class=\"guide-markup\">final notification</strong> is sent on <strong class=\"guide-markup\">Day 0</strong>,\n    confirming that the liquidation period has ended and the items have been\n    <strong class=\"guide-markup\">discarded</strong> from the warehouse.\n  </div>\n</details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42547688464155,"title":"Fleek Chat Feature – Connecting Buyers and Sellers","body":"<p class=\"guide-markup\" data-start=\"284\" data-end=\"585\">The Fleek Chat Feature allows direct communication between buyers and sellers — helping both parties connect, clarify, and build trust. </p><p class=\"guide-markup\" data-start=\"284\" data-end=\"585\">It’s designed to make the shopping experience smoother by enabling quick discussions about product details, order queries, and offers, all within the Fleek platform.</p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K83KVF4GTXCZ7J571Z3GQ34P\"><strong class=\"guide-markup\">How Chat Works on Fleek?</strong></h2><p class=\"guide-markup\" data-start=\"624\" data-end=\"944\">The Chat Feature enables real-time messaging between buyers and sellers. Once a buyer sends a message from the product page or an existing order, the seller receives it instantly in their Fleek Chat Inbox within the Seller App. Sellers can reply directly to address buyer questions, share details, or negotiate offers.</p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K84C3YC0N8NVVKC9JY4P7QGX\"><strong class=\"guide-markup\" data-start=\"2245\" data-end=\"2267\">Importance of Chat</strong></h2><p class=\"guide-markup\" data-start=\"2268\" data-end=\"2600\">In e-commerce, communication drives confidence. The Chat Feature bridges the gap between curiosity and purchase — making buyers more likely to order when their questions are answered quickly and professionally.</p><p class=\"guide-markup\" data-start=\"2268\" data-end=\"2600\">For sellers, chat is an opportunity to convert interest into sales, provide superior service, and increase repeat buyers.</p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K84C3W9QHCBWKC9RA6XH4CBE\"><strong class=\"guide-markup\">How to Access Chat?</strong></h2><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"279792c1-7848-47c8-b235-dc399751deba\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"166\" data-is-last-node=\"\" data-is-only-node=\"\">Accessing chat on Fleek is simple and effortless for sellers.</p>\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"166\" data-is-last-node=\"\" data-is-only-node=\"\">With just a few taps, you can connect with buyers instantly and manage all conversations in one place.</p>\n</div></div></div></div></div></div><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1221/812;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42547688444187\" width=\"1221\" height=\"812\"></figure><div class=\"guide-markup\"><span class=\"guide-markup\" data-canva-clipboard=\"\"></span></div><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K845M6K0AAF3DSJXXZ7CCEN8\"><strong class=\"guide-markup\">How a Customer can Message the Supplier?</strong></h2><p class=\"guide-markup\" data-start=\"1477\" data-end=\"1516\">A buyer can message a supplier through:</p><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1192/935;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42547704907803\" width=\"1192\" height=\"935\"></figure><p class=\"guide-markup\" data-start=\"1748\" data-end=\"1851\"><em class=\"guide-markup\"><em>Note: All chats are stored in the buyer’s <strong class=\"guide-markup\" data-start=\"1784\" data-end=\"1793\">Inbox</strong>, ensuring clear communication throughout the transaction.</em></em></p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K849YNYGH1WQ14ZYK1PZWPFV\"><strong class=\"guide-markup\" data-start=\"2611\" data-end=\"2646\">How to Manage Chats Effectively?</strong></h2><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"27a591ff-295f-4c06-af9e-3b12c905a3b5\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"232\">Stay organized and responsive by checking your chat inbox regularly. Use filters to manage conversations, reply quickly, and maintain clear, professional communication to build trust and drive more sales.</p>\n<ul class=\"guide-markup\" data-start=\"234\" data-end=\"683\" data-is-last-node=\"\" data-is-only-node=\"\">\n<li class=\"guide-markup\" data-start=\"234\" data-end=\"328\" data-list-item-id=\"e7603f4d956f53038fb4215608d9c2bca\"><p class=\"guide-markup\" data-start=\"236\" data-end=\"328\"><strong class=\"guide-markup\" data-start=\"236\" data-end=\"257\">Respond Promptly:</strong> Quick replies build buyer confidence and improve conversion chances.</p></li>\n<li class=\"guide-markup\" data-start=\"329\" data-end=\"412\" data-list-item-id=\"ec7a1991601b42700d9085f40682098fb\"><p class=\"guide-markup\" data-start=\"331\" data-end=\"412\"><strong class=\"guide-markup\" data-start=\"331\" data-end=\"353\">Stay Professional:</strong> Keep your tone polite, clear, and helpful in every chat.</p></li>\n<li class=\"guide-markup\" data-start=\"498\" data-end=\"592\" data-list-item-id=\"eabb2d0005e28d67ce81f664ce79247e0\"><p class=\"guide-markup\" data-start=\"500\" data-end=\"592\"><strong class=\"guide-markup\" data-start=\"500\" data-end=\"521\">Keep It on Fleek:</strong> Avoid sharing external links or personal contact details for safety.</p></li>\n<li class=\"guide-markup\" data-start=\"593\" data-end=\"683\" data-is-last-node=\"\" data-list-item-id=\"ef77825d892009dbb03aa705b7d3e0c7f\"><p class=\"guide-markup\" data-start=\"595\" data-end=\"683\" data-is-last-node=\"\"><strong class=\"guide-markup\" data-start=\"595\" data-end=\"609\">Follow Up:</strong> Reach out politely to buyers who showed interest but haven’t ordered yet.</p></li>\n</ul>\n<hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K84CTZ7JHTKRG0AGVT23TVNV\"><strong class=\"guide-markup\">What are Chat Filters?</strong></h2>\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"209\">Chat filters help you organize and manage your conversations more efficiently. They allow you to sort messages based on specific criteria — so you can focus on what matters most.</p>\n<p class=\"guide-markup\" data-start=\"211\" data-end=\"252\">On Fleek, you can filter your chats by:</p>\n<ul class=\"guide-markup\" data-start=\"253\" data-end=\"519\">\n<li class=\"guide-markup\" data-start=\"253\" data-end=\"324\" data-list-item-id=\"eba6cebcf2f307291948bca0c5e74011c\"><p class=\"guide-markup\" data-start=\"255\" data-end=\"324\"><strong class=\"guide-markup\" data-start=\"255\" data-end=\"266\">Unread:</strong> View messages you haven’t opened yet to respond faster.</p></li>\n<li class=\"guide-markup\" data-start=\"325\" data-end=\"425\" data-list-item-id=\"e2624eeaaa4c2d7cc057d6fc6d059306f\"><p class=\"guide-markup\" data-start=\"327\" data-end=\"425\"><strong class=\"guide-markup\" data-start=\"327\" data-end=\"343\">Custom Tags:</strong> Group chats by labels like <em class=\"guide-markup\" data-start=\"371\" data-end=\"386\"><em>Close to Order</em></em>, <em class=\"guide-markup\" data-start=\"388\" data-end=\"399\"><em>Fleek Marketing</em></em>, or <em class=\"guide-markup\"><em>make an </em></em><em class=\"guide-markup\" data-start=\"404\" data-end=\"423\" data-is-only-node=\"\"><em>Offer Discussion.</em></em></p></li>\n<li class=\"guide-markup\" data-start=\"426\" data-end=\"519\" data-list-item-id=\"e8f6d367408b30e5a6f58aad5f1835703\"><p class=\"guide-markup\" data-start=\"428\" data-end=\"519\"><strong class=\"guide-markup\" data-start=\"428\" data-end=\"447\">Fleek Channels:</strong> See updates or messages from Fleek’s official communication channels.</p></li>\n</ul>\n<p class=\"guide-markup\" data-start=\"521\" data-end=\"629\" data-is-last-node=\"\" data-is-only-node=\"\">Using filters ensures no important conversation gets missed and helps you stay on top of buyer interactions.</p>\n<hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K84CTZ7KBX4ENYM6MDWW5GPQ\"><strong class=\"guide-markup\">How to Translate a Message?</strong></h2>\n<p class=\"guide-markup\">You can easily translate any message by following these steps:</p>\n<ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"e1aa2d96f4fcec311df8d0b3631670119\"><p class=\"guide-markup\" data-start=\"2\" data-end=\"56\">Click the <strong class=\"guide-markup\" data-start=\"12\" data-end=\"29\">Language Icon</strong> on the top right corner.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"e0a431401f4ddbea40baeabf22fa7b6fe\"><p class=\"guide-markup\" data-start=\"59\" data-end=\"110\">Choose your <strong class=\"guide-markup\" data-start=\"71\" data-end=\"93\">preferred language</strong> from the list.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"e0109f5a1761fde2d70cd44b32bbb9b61\"><p class=\"guide-markup\" data-start=\"113\" data-end=\"188\" data-is-last-node=\"\">Select your language and click <strong class=\"guide-markup\" data-start=\"144\" data-end=\"152\">Done</strong> to translate the message instantly.</p></li>\n</ul>\n<figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 2062/1037;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42547688449691\" width=\"2062\" height=\"1037\"></figure><hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K84CTZ7KSM8PVM2B78G8JG6X\"><strong class=\"guide-markup\" data-start=\"0\" data-end=\"38\" data-is-only-node=\"\">How to Reply to a Specific Message?</strong></h2>\n<p class=\"guide-markup\">You can reply to a single message just like on WhatsApp — simply following these steps:</p>\n<figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1246/827;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42547688452635\" width=\"1246\" height=\"827\"></figure><hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K84C66R3M35AT8SZGQTRGK4H\"><strong class=\"guide-markup\" data-start=\"1862\" data-end=\"1894\">Benefits of the Chat Feature</strong></h2>\n<ul class=\"guide-markup\" data-start=\"1895\" data-end=\"2234\">\n<li class=\"guide-markup\" data-start=\"1895\" data-end=\"1987\" data-list-item-id=\"ee34929bb3cce9c1e877e07060f7bb73e\"><p class=\"guide-markup\" data-start=\"1897\" data-end=\"1987\"><strong class=\"guide-markup\" data-start=\"1897\" data-end=\"1920\">Faster Conversions:</strong> Direct communication often turns interest into confirmed orders.</p></li>\n<li class=\"guide-markup\" data-start=\"1988\" data-end=\"2075\" data-list-item-id=\"eee54f1dea51f9de4da41e2f701b22b83\"><p class=\"guide-markup\" data-start=\"1990\" data-end=\"2075\"><strong class=\"guide-markup\" data-start=\"1990\" data-end=\"2019\">Reduced Misunderstanding:</strong> Buyers can clarify product details before purchasing.</p></li>\n<li class=\"guide-markup\" data-start=\"2076\" data-end=\"2153\" data-list-item-id=\"ef24dc40365ccb6fdbb154cecca8974cd\"><p class=\"guide-markup\" data-start=\"2078\" data-end=\"2153\"><strong class=\"guide-markup\" data-start=\"2078\" data-end=\"2104\">Higher Customer Trust:</strong> Responsive sellers build stronger credibility.</p></li>\n<li class=\"guide-markup\" data-start=\"2154\" data-end=\"2234\" data-list-item-id=\"eac2d0de13ddcc2a0971f96f0573ecd41\"><p class=\"guide-markup\" data-start=\"2156\" data-end=\"2234\"><strong class=\"guide-markup\" data-start=\"2156\" data-end=\"2185\">Smooth Post-Sale Support:</strong> Sellers can handle buyer concerns efficiently.</p></li>\n<li class=\"guide-markup\" data-start=\"2154\" data-end=\"2234\" data-list-item-id=\"e057ab6145b99420feaf513d9f9754cf8\"><p class=\"guide-markup\" data-start=\"2156\" data-end=\"2234\"><strong class=\"guide-markup\" data-start=\"2\" data-end=\"12\" data-is-only-node=\"\">Media:</strong> Share your product images or videos directly in chat.</p></li>\n<li class=\"guide-markup\" data-start=\"2154\" data-end=\"2234\" data-list-item-id=\"e9981a5b665c01fcc142fe91e7d750e8d\"><p class=\"guide-markup\" data-start=\"2156\" data-end=\"2234\"><strong class=\"guide-markup\" data-start=\"71\" data-end=\"84\" data-is-only-node=\"\">Handpick:</strong> Customers can connect with you easily through a video call for live product viewing.</p></li>\n</ul>\n<hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K84CBZ0HZGWZWTW4QWNDNGA8\"><strong class=\"guide-markup\" data-start=\"3063\" data-end=\"3094\">How Fleek Utilizes the Chat</strong></h2>\n<p class=\"guide-markup\" data-start=\"3095\" data-end=\"3127\">Fleek uses chat interactions to:</p>\n<ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-start=\"70\" data-end=\"138\" data-list-item-id=\"e362e743aa561d4b08487ab7f49b67308\"><p class=\"guide-markup\" data-start=\"72\" data-end=\"138\">Ensure safe and respectful communication across the marketplace.</p></li>\n<li class=\"guide-markup\" data-start=\"139\" data-end=\"218\" data-list-item-id=\"ea9f138d35f702eddcfd5b273ce7fda0e\"><p class=\"guide-markup\" data-start=\"141\" data-end=\"218\">Analyze buyer–seller engagement to enhance platform experience and support.</p></li>\n<li class=\"guide-markup\" data-start=\"219\" data-end=\"299\" data-list-item-id=\"ea434cad677a5a0570ed6e2858d61cbcf\"><p class=\"guide-markup\" data-start=\"221\" data-end=\"299\">Facilitate dispute resolution by creating dedicated chat channels or groups.</p></li>\n<li class=\"guide-markup\" data-start=\"300\" data-end=\"385\" data-is-last-node=\"\" data-list-item-id=\"e4a92a0547f41ef5d8f8552cec2d92271\"><p class=\"guide-markup\" data-start=\"302\" data-end=\"385\" data-is-last-node=\"\">Enable sellers to promote products directly and build stronger buyer relationships.</p></li>\n<li class=\"guide-markup\" data-start=\"300\" data-end=\"385\" data-is-last-node=\"\" data-list-item-id=\"e102246b3db3f54267a3a621a8f4e36be\"><p class=\"guide-markup\" data-start=\"302\" data-end=\"385\" data-is-last-node=\"\"><strong class=\"guide-markup\" data-start=\"399\" data-end=\"462\">Send promotional messages to customers on behalf of sellers</strong> to help increase visibility and sales.</p></li>\n</ul>\n<hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K84CKH80KN045VBF25574N2P\"><strong class=\"guide-markup\" data-start=\"3376\" data-end=\"3392\">Key Takeaway</strong></h2>\n<p class=\"guide-markup\" data-start=\"3393\" data-end=\"3656\">The Fleek Chat Feature isn’t just a tool — it’s a bridge. It connects buyers and sellers in real-time, enabling smoother transactions, better understanding, and stronger relationships. Using it effectively can directly impact your sales and customer satisfaction.</p>\n<hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K84CN9VN7M8CWXBN4C5P2RGC\"><strong class=\"guide-markup\" data-start=\"0\" data-end=\"15\">Chat Don’ts</strong></h2>\n<p class=\"guide-markup\">Avoid these common mistakes to maintain professionalism and ensure a safe, trustworthy experience:</p>\n<ul class=\"guide-markup\" data-start=\"120\" data-end=\"759\" data-is-last-node=\"\" data-is-only-node=\"\">\n<li class=\"guide-markup\" data-start=\"120\" data-end=\"209\" data-list-item-id=\"edcb531e7ee6d25705a7febc493288e71\"><p class=\"guide-markup\" data-start=\"122\" data-end=\"209\">Don’t ignore messages — delayed replies can lead to missed sales and lower trust.</p></li>\n<li class=\"guide-markup\" data-start=\"210\" data-end=\"296\" data-list-item-id=\"ecdd6520b1d953aee07685c70d76a63b9\"><p class=\"guide-markup\" data-start=\"212\" data-end=\"296\">Don’t use rude or unprofessional language — always stay polite and respectful.</p></li>\n<li class=\"guide-markup\" data-start=\"297\" data-end=\"391\" data-list-item-id=\"ecbd6c1cdb6ced24f48fb8e0d246ea3c0\"><p class=\"guide-markup\" data-start=\"299\" data-end=\"391\">Don’t share personal contact details — keep all communication within Fleek for safety.</p></li>\n<li class=\"guide-markup\" data-start=\"392\" data-end=\"480\" data-list-item-id=\"ee538315eaa359a049f762a74c304fb77\"><p class=\"guide-markup\" data-start=\"394\" data-end=\"480\">Don’t send external links or payment requests — transactions must stay on Fleek.</p></li>\n<li class=\"guide-markup\" data-start=\"481\" data-end=\"582\" data-list-item-id=\"e1ad97b9a41b4c5bbb1aa5f2673ae1b8a\"><p class=\"guide-markup\" data-start=\"483\" data-end=\"582\">Don’t make false promises — only share accurate information about your products and delivery.</p></li>\n<li class=\"guide-markup\" data-start=\"583\" data-end=\"670\" data-list-item-id=\"ede29f477549df70771a642815036412e\"><p class=\"guide-markup\" data-start=\"585\" data-end=\"670\">Don’t spam buyers — keep your messages relevant and focused on their inquiries.</p></li>\n</ul>\n<hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K84CSA7A67R170317E04078F\"><strong class=\"guide-markup\">Frequently Asked Questions:</strong></h2>\n</div></div></div></div></div></div><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. What is the Fleek Chat Feature?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    The <strong class=\"guide-markup\">Fleek Chat Feature</strong> allows buyers and sellers to communicate directly within the Fleek platform — \n    to discuss product details, offers, and order-related questions in real time.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. How can a buyer message a seller?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    A buyer can message the seller by:  \n    <ul style=\"margin-top: 4px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">Clicking <strong class=\"guide-markup\">“Message the Seller”</strong> on the Product Detail Page (PDP)</li>\n      <li class=\"guide-markup\">Clicking <strong class=\"guide-markup\">“Message the Supplier”</strong> on the Store Page</li>\n    </ul>\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. Where can sellers access their chats?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Sellers can access all buyer conversations by tapping the <strong class=\"guide-markup\">Chat icon</strong> located in the Fleek Seller App’s bottom navigation bar.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. Can sellers filter their chats?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. Sellers can use filters to organize their chats by:  \n    <ul style=\"margin-top: 4px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">Unread messages</li>\n      <li class=\"guide-markup\">Custom Tags</li>\n      <li class=\"guide-markup\">Fleek Channels</li>\n    </ul>\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. Can I reply to a specific message?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. Simply <strong class=\"guide-markup\">drag the message to the right</strong> or <strong class=\"guide-markup\">long-press</strong> it to reply directly — similar to WhatsApp.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">6. Can I share media through chat?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. Sellers can share <strong class=\"guide-markup\">product images</strong> or <strong class=\"guide-markup\">videos</strong> to showcase their items more clearly and help buyers make informed decisions.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">7. What is the Handpick feature in chat?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    The <strong class=\"guide-markup\">Handpick feature</strong> allows customers to connect with sellers via <strong class=\"guide-markup\">video call</strong> for a live view of products — helping them inspect quality and details before purchase.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">8. How can I translate messages in chat?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Click the <strong class=\"guide-markup\">Language Icon</strong> on the top right corner, choose your preferred language, and tap <strong class=\"guide-markup\">Done</strong> to instantly translate the conversation.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">9. What should I avoid while chatting?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Avoid sharing <strong class=\"guide-markup\">personal contact details</strong>, <strong class=\"guide-markup\">external links</strong>, or using <strong class=\"guide-markup\">unprofessional language</strong>.  \n    Always keep your communication within Fleek for safety and compliance.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">10. How does Fleek use the chat feature?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Fleek monitors chat quality to ensure <strong class=\"guide-markup\">safety</strong>, assists in <strong class=\"guide-markup\">dispute resolution</strong>, and analyzes <strong class=\"guide-markup\">engagement trends</strong>.  \n    Fleek may also send <strong class=\"guide-markup\">promotional messages</strong> to customers on behalf of sellers to support platform-wide campaigns.\n  </div>\n</details><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"27a591ff-295f-4c06-af9e-3b12c905a3b5\" data-message-model-slug=\"gpt-5\"><hr class=\"guide-markup\"></div></div></div></div><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42547470574875,"title":"Campaign And Discounts - A complete understanding for Sellers","body":"<p class=\"guide-markup\" data-start=\"223\" data-end=\"649\">Discounts and campaigns are powerful tools to attract buyers, boost visibility, and increase sales. </p><p class=\"guide-markup\" data-start=\"223\" data-end=\"649\">They allow sellers to offer special pricing or limited-time deals that encourage customers to make faster purchase decisions. </p><p class=\"guide-markup\" data-start=\"223\" data-end=\"649\">By using campaigns strategically — Whether it’s a <strong class=\"guide-markup\" data-start=\"363\" data-end=\"446\">seasonal promotion, a platform-led campaign, or the seller’s own discount offer </strong>— sellers can build customer loyalty, move inventory faster, and stand out in a competitive marketplace.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K836AHW4WT81RJ9XQG2F8NRD\">How Discount work on Fleek?</h3><p class=\"guide-markup\" data-start=\"171\" data-end=\"346\">At Fleek, we encourage sellers to grow their business by using our promotional tools effectively. We offer multiple ways to attract buyers and boost sales through discounts:</p><ul class=\"guide-markup\" data-start=\"348\" data-end=\"655\">\n<li class=\"guide-markup\" data-start=\"348\" data-end=\"424\" data-list-item-id=\"ef001c30d198061ebe804d6cbb4d18e69\"><p class=\"guide-markup\" data-start=\"350\" data-end=\"424\"><strong class=\"guide-markup\" data-start=\"350\" data-end=\"368\">Make an Offer:</strong> Buyers can negotiate a better deal directly with you.</p></li>\n<li class=\"guide-markup\" data-start=\"425\" data-end=\"532\" data-list-item-id=\"e9f599dffcd2dda63bf798457e39b91a6\"><p class=\"guide-markup\" data-start=\"427\" data-end=\"532\"><strong class=\"guide-markup\" data-start=\"427\" data-end=\"467\">Platform Campaigns &amp; Seasonal Sales:</strong> Participate in Fleek-led promotions to reach a wider audience.</p></li>\n<li class=\"guide-markup\" data-start=\"533\" data-end=\"655\" data-list-item-id=\"e1ba54ec20b6c1d40e2461123b369730a\"><p class=\"guide-markup\" data-start=\"535\" data-end=\"655\"><strong class=\"guide-markup\" data-start=\"535\" data-end=\"561\">Seller’s Own Discount:</strong> Create and manage your own discount offers to attract more buyers and increase conversions.</p></li>\n</ul><p class=\"guide-markup\" data-start=\"535\" data-end=\"655\">These options help you stay competitive, drive more traffic to your listings, and maximize your sales potential.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K83704HZXX453WDGWJ4MHYBT\" data-start=\"138\" data-end=\"183\">How Can I Offer My Discount on Fleek?</h3><p class=\"guide-markup\">Sellers can easily create and manage their own discounts on Fleek to attract buyers and boost sales. Here’s how you can do it:</p><p class=\"guide-markup\">You can follow simple steps:</p><ol class=\"guide-markup\" data-start=\"312\" data-end=\"622\">\n<li class=\"guide-markup\" data-start=\"312\" data-end=\"340\" data-list-item-id=\"e23d1ff5ac2a49ab406ad2edfafb1e7cb\"><p class=\"guide-markup\" data-start=\"315\" data-end=\"340\">Open the Vendor App</p></li>\n<li class=\"guide-markup\" data-start=\"341\" data-end=\"369\" data-list-item-id=\"e73c807ce99e16b0050b9892430084fca\"><p class=\"guide-markup\" data-start=\"344\" data-end=\"369\">Tap “+” → Discounts</p></li>\n<li class=\"guide-markup\" data-start=\"370\" data-end=\"411\" data-list-item-id=\"ea3ae0201853ca56ddb2ba192d918b673\"><p class=\"guide-markup\" data-start=\"373\" data-end=\"411\">Click on “New Discount Campaign”</p></li>\n<li class=\"guide-markup\" data-start=\"412\" data-end=\"460\" data-list-item-id=\"ee2efb0dfbe39966cb06da6f97ebdf359\"><p class=\"guide-markup\" data-start=\"415\" data-end=\"460\">Select the Products you want to include</p></li>\n<li class=\"guide-markup\" data-start=\"461\" data-end=\"505\" data-list-item-id=\"e4f67f121a3c562ad42019fbddd0f5ee4\"><p class=\"guide-markup\" data-start=\"464\" data-end=\"505\">Click on “Set up Discount Campaign”</p></li>\n<li class=\"guide-markup\" data-start=\"506\" data-end=\"535\" data-list-item-id=\"eb50ecffb2e735a0b99db4656138872d9\"><p class=\"guide-markup\" data-start=\"509\" data-end=\"535\">Add a Campaign Title</p></li>\n<li class=\"guide-markup\" data-start=\"536\" data-end=\"572\" data-list-item-id=\"e83025e4b9b74945fab6c1cf64bc09e5f\"><p class=\"guide-markup\" data-start=\"539\" data-end=\"572\">Set the Discount Percentage</p></li>\n<li class=\"guide-markup\" data-start=\"573\" data-end=\"622\" data-list-item-id=\"eeb8c82887baa77756100ef5498c06a1e\"><p class=\"guide-markup\" data-start=\"576\" data-end=\"622\">Choose the Expiry Date for your campaign</p></li>\n</ol><p class=\"guide-markup\" data-start=\"624\" data-end=\"762\">Once saved, your discount will be live and visible to buyers — helping you boost visibility, attract more customers, and increase sales.</p><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 2124/1074;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42547470571803\" width=\"2124\" height=\"1074\"></figure><p class=\"guide-markup\">💡 <strong class=\"guide-markup\" data-start=\"767\" data-end=\"775\">Tip:</strong> Use clear campaign titles (like <em class=\"guide-markup\" data-start=\"808\" data-end=\"828\"><em>Weekend Flash Sale</em></em> or <em class=\"guide-markup\" data-start=\"832\" data-end=\"853\"><em>End of Season Offer</em></em>) to make your promotions stand out.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K83CVTCKJYR9JM680J3BDBS4\" data-start=\"138\" data-end=\"183\">How can a buyer see my Discount on Fleek?</h3><p class=\"guide-markup\" data-start=\"142\" data-end=\"278\">Once you set up a discount, buyers will see it directly on your Product Detail Page (PDP) — clearly highlighted to grab attention.</p><p class=\"guide-markup\" data-start=\"280\" data-end=\"314\">Here’s how it appears to buyers:</p><ul class=\"guide-markup\" data-start=\"316\" data-end=\"629\">\n<li class=\"guide-markup\" data-start=\"316\" data-end=\"397\" data-list-item-id=\"efc5cc531d0fcba0a6d4f62db5a2a87fd\"><p class=\"guide-markup\" data-start=\"318\" data-end=\"397\">A red discount badge (e.g., <em class=\"guide-markup\" data-start=\"350\" data-end=\"364\"><em>31% Discount</em></em>) is displayed above the price.</p></li>\n<li class=\"guide-markup\" data-start=\"398\" data-end=\"474\" data-list-item-id=\"ec31b425026e17ff61daacee4a4fc7a6f\"><p class=\"guide-markup\" data-start=\"400\" data-end=\"474\">The discounted price per piece (e.g., £9.55/pc) appears in bold.</p></li>\n<li class=\"guide-markup\" data-start=\"475\" data-end=\"547\" data-list-item-id=\"e16bedae6d242babe3616d92d69639950\"><p class=\"guide-markup\" data-start=\"477\" data-end=\"547\">The total discounted price (e.g., £95.5) is shown beside it.</p></li>\n<li class=\"guide-markup\" data-start=\"548\" data-end=\"629\" data-list-item-id=\"e42600351564006a6e0d2312c90366345\"><p class=\"guide-markup\" data-start=\"550\" data-end=\"629\">The original price (e.g., <em class=\"guide-markup\" data-start=\"580\" data-end=\"586\"><em>£139</em></em>) is crossed out, showing the price drop.</p></li>\n</ul><p class=\"guide-markup\" data-start=\"631\" data-end=\"759\">This clear price breakdown helps buyers instantly recognize the value of your offer — increasing their likelihood to purchase.</p><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1271/757;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42547470572315\" width=\"1271\" height=\"757\"></figure><p class=\"guide-markup\">💡 <strong class=\"guide-markup\" data-start=\"764\" data-end=\"772\">Tip:</strong> The more attractive your discount and campaign title, the higher the chances your product catches buyer attention.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K83CVTCKKW9JF1MY1P4A0NHA\" data-start=\"138\" data-end=\"183\">How can I Join Platform Discount on Fleek?</h3><p class=\"guide-markup\" data-start=\"154\" data-end=\"380\">Fleek regularly runs <strong class=\"guide-markup\" data-start=\"175\" data-end=\"220\">seasonal sales and platform-led campaigns</strong> to help sellers boost visibility and attract more buyers. Joining these campaigns is simple and can significantly increase your chances of making more sales.</p><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"f53c3358-53bb-4c3a-bd28-08e7822f6a99\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"103\" data-is-last-node=\"\" data-is-only-node=\"\">Fleek will share the campaign link with you through <strong class=\"guide-markup\" data-start=\"52\" data-end=\"63\">banners</strong> or <strong class=\"guide-markup\" data-start=\"67\" data-end=\"84\">notifications</strong> in the Vendor App.</p>\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"103\" data-is-last-node=\"\" data-is-only-node=\"\">Stay updated through your Vendor App notifications or seller communication channels — Fleek announces upcoming campaigns in advance.</p>\n<hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K83CVTCKP1ACV8RSKEGMBARN\" data-start=\"138\" data-end=\"183\">What is Make an Offer?</h3>\n<p class=\"guide-markup\">The <strong class=\"guide-markup\" data-start=\"170\" data-end=\"187\">Make an Offer</strong> feature on Fleek empowers sellers to directly <strong class=\"guide-markup\" data-start=\"234\" data-end=\"266\">negotiate prices with buyers</strong> in a simple, transparent, and efficient way.</p>\n<div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"97445038-380a-47fc-bc0a-54e5628f6fab\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"44\" data-is-last-node=\"\" data-is-only-node=\"\">Let’s click <a class=\"guide-markup\">here</a> to explore the <strong class=\"guide-markup\" data-start=\"18\" data-end=\"35\">Make an Offer</strong> feature.</p>\n<hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K83ARPR1WHFXPKX0ZWRM81JY\" data-start=\"833\" data-end=\"900\">Discount Tips &amp; Best Practices</h3>\n<p class=\"guide-markup\" data-start=\"901\" data-end=\"963\">This short section helps sellers make the most of discounts:</p>\n<p class=\"guide-markup\" data-start=\"965\" data-end=\"995\"><strong class=\"guide-markup\" data-start=\"965\" data-end=\"993\">Tips for Better Results:</strong></p>\n<ul class=\"guide-markup\" data-start=\"996\" data-end=\"1272\">\n<li class=\"guide-markup\" data-list-item-id=\"ee4347a9372fb792291b4f044f35c62ae\"><p class=\"guide-markup\" data-start=\"0\" data-end=\"64\">Offer <strong class=\"guide-markup\" data-start=\"6\" data-end=\"32\">limited-time discounts</strong> to create urgency.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"e11630c323bae719917f25d81f881add0\"><p class=\"guide-markup\" data-start=\"66\" data-end=\"160\">Respond <strong class=\"guide-markup\" data-start=\"74\" data-end=\"105\">promptly to “Make an Offer”</strong> requests for quicker negotiations and deal closures.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"ec012895ea50eb7709517497071a4765e\"><p class=\"guide-markup\" data-start=\"162\" data-end=\"230\" data-is-last-node=\"\" data-is-only-node=\"\">Always <strong class=\"guide-markup\" data-start=\"169\" data-end=\"202\">review your pricing carefully</strong> before applying a discount.</p></li>\n</ul>\n<hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K83BTYJKTTYHEYGVEDEPC4NW\">Frequently Asked Questions:</h3>\n</div></div></div></div></div></div>\n</div></div></div></div></div></div><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. Can I offer discounts on all my products?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes, you can apply discounts to <strong class=\"guide-markup\">selected products</strong> or <strong class=\"guide-markup\">bundles</strong> of your choice.  \n    This helps promote specific items and manage your inventory more effectively.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. How long can my discount campaign run?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    You can set a <strong class=\"guide-markup\">custom expiry date</strong> when creating your discount campaign.  \n    We recommend keeping it <strong class=\"guide-markup\">time-limited</strong> to create urgency and drive faster sales.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. How will buyers know about my discount?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Your discount will be <strong class=\"guide-markup\">clearly displayed</strong> on the <strong class=\"guide-markup\">Product Detail Page</strong> with a red discount badge,  \n    showing both the <strong class=\"guide-markup\">original</strong> and <strong class=\"guide-markup\">discounted</strong> prices.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. Will discounts affect my payout?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. Discounts lower your <strong class=\"guide-markup\">selling price</strong>, so your payout will be calculated based on the <strong class=\"guide-markup\">discounted amount</strong>  \n    instead of the original price.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. How can I join a Fleek platform campaign?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Fleek will notify you through <strong class=\"guide-markup\">banners</strong> or <strong class=\"guide-markup\">app notifications</strong> with a campaign link.  \n    Simply click <strong class=\"guide-markup\">“Join Campaign”</strong>, review the details, and select eligible products to participate.\n  </div>\n</details><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"f53c3358-53bb-4c3a-bd28-08e7822f6a99\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\"><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"97445038-380a-47fc-bc0a-54e5628f6fab\" data-message-model-slug=\"gpt-5\"><hr class=\"guide-markup\"></div></div></div></div></div></div></div></div></div></div><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42547229080475,"title":"Make an Offer – Seller-Buyer Negotiation Tool","body":"<p class=\"guide-markup\" data-start=\"166\" data-end=\"481\">The <strong class=\"guide-markup\" data-start=\"170\" data-end=\"187\">Make an Offer</strong> feature on Fleek empowers sellers to directly <strong class=\"guide-markup\" data-start=\"234\" data-end=\"266\">negotiate prices with buyers</strong> in a simple, transparent, and efficient way.</p><p class=\"guide-markup\" data-start=\"166\" data-end=\"481\">It helps you convert more inquiries into sales by giving flexibility to respond to buyer quotes — either by <strong class=\"guide-markup\" data-start=\"422\" data-end=\"435\">accepting</strong> or <strong class=\"guide-markup\" data-start=\"437\" data-end=\"451\">countering</strong> an offer.</p><p class=\"guide-markup\" data-start=\"483\" data-end=\"669\">This feature ensures both parties reach a <strong class=\"guide-markup\" data-start=\"525\" data-end=\"553\">mutually beneficial deal</strong>, improving conversion rates and helping sellers <strong class=\"guide-markup\" data-start=\"602\" data-end=\"627\">move inventory faster</strong> while maintaining control over pricing.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K81PGHHKWHQG5EFVY3ZH7GE0\" data-start=\"148\" data-end=\"168\"><strong class=\"guide-markup\" data-start=\"152\" data-end=\"168\">How It Works:</strong></h3><p class=\"guide-markup\">Discover how the Make an Offer tool simplifies price negotiation and helps sellers convert more deals.</p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"ed8136ec4efb923a0dfd7478a46000c35\"><p class=\"guide-markup\" data-start=\"173\" data-end=\"243\">A buyer visits your product page and clicks “Make an Offer.”</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"e634e313c13e4100dbde3efe0c7be7d5a\"><p class=\"guide-markup\" data-start=\"247\" data-end=\"315\">The buyer submits their quoted price for the selected product.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"e02c54d196e6c3668c6dfae2ce63e5cf8\"><p class=\"guide-markup\" data-start=\"319\" data-end=\"396\">The offer appears in your Vendor App under “Offers” → “To Respond.”</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"e35ee82e2ead9beb2f6140006cf283b46\"><p class=\"guide-markup\" data-start=\"400\" data-end=\"475\">You can review the details and accept, counter, or decline the offer.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"efd343cd1bc19c8f3deb89f44721f94bd\"><p class=\"guide-markup\" data-start=\"479\" data-end=\"557\">Once you accept the offer, a unique code is automatically generated.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"eec0a61718e07e69ee00a7d7611def2a5\"><p class=\"guide-markup\" data-start=\"561\" data-end=\"664\">The buyer can then redeem this code at checkout to complete the purchase at the agreed price.</p></li>\n</ul><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K81PQP8E11FD59PT4ZANKSQB\" data-start=\"288\" data-end=\"323\"><strong class=\"guide-markup\" data-start=\"292\" data-end=\"321\">1. Where to View Pending Offers</strong></h3><p class=\"guide-markup\">Stay on top of buyer negotiations by checking your pending offers in the Vendor App. Here’s where you can find and manage pending offers awaiting your response.</p><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1562/813;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42547229072795\" width=\"1562\" height=\"813\"></figure><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K81PWM70AXR5M1EADG0AGYPH\" data-start=\"288\" data-end=\"323\"><strong class=\"guide-markup\" data-start=\"292\" data-end=\"321\">2. How to Accept an Offer</strong></h3><p class=\"guide-markup\">Let’s understand how to accept an Offer. Follow these steps:</p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"eab25db4b0fb69e36eb73713f23227b88\">Open Vendor App</li>\n<li class=\"guide-markup\" data-list-item-id=\"e765064e08943babff72d18250faf3ce3\">Tap “+” → Offers</li>\n<li class=\"guide-markup\" data-list-item-id=\"ed9ae0fcff89abea8c38170168d4802a9\">Go to “To Respond” tab</li>\n<li class=\"guide-markup\" data-list-item-id=\"e53c7029a30f79f1b853263e4d2f7492f\">Open the offer to view product &amp; buyer quote</li>\n<li class=\"guide-markup\" data-list-item-id=\"e6f7f24222190d4005819ba4407efb5f3\">Review the details</li>\n<li class=\"guide-markup\" data-list-item-id=\"eef34d828e45db33537dad9b40e9ee5c6\">Click “Accept Buyer’s Offer” to confirm</li>\n<li class=\"guide-markup\" data-list-item-id=\"e5239b538fa381f3a48e1108cde134df6\">Or choose “Counter Offer” to quote your own price</li>\n</ul><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1572/795;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42547245711771\" width=\"1572\" height=\"795\"></figure><p class=\"guide-markup\"><em class=\"guide-markup\"><em><strong class=\"guide-markup\">Important: </strong>Please cross checked the prices before you quote anything to the buyer.</em></em></p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K81Q6NYJK0D9X2WWR814J8XE\" data-start=\"288\" data-end=\"323\"><strong class=\"guide-markup\" data-start=\"292\" data-end=\"321\">3. Understanding the Offer Breakdown</strong></h3><p class=\"guide-markup\" data-start=\"950\" data-end=\"990\">When you receive an offer, you’ll see:</p><p class=\"guide-markup\" data-start=\"220\" data-end=\"304\">Easily understand how buyer quotes affect your pricing and what remains unchanged.</p><p class=\"guide-markup\" data-start=\"306\" data-end=\"355\">When you receive an offer, the system displays:</p><ul class=\"guide-markup\" data-start=\"356\" data-end=\"432\">\n<li class=\"guide-markup ck-list-marker-bold\" data-start=\"356\" data-end=\"379\" data-list-item-id=\"efb6b12e623d372db5e127546d1a84bf2\"><p class=\"guide-markup\" data-start=\"358\" data-end=\"379\"><strong class=\"guide-markup\" data-start=\"358\" data-end=\"377\">Product details</strong></p></li>\n<li class=\"guide-markup ck-list-marker-bold\" data-start=\"380\" data-end=\"408\" data-list-item-id=\"e2b76503604fceaf3b6668e85d6fd4368\"><p class=\"guide-markup\" data-start=\"382\" data-end=\"408\"><strong class=\"guide-markup\" data-start=\"382\" data-end=\"406\">Buyer’s quoted price</strong></p></li>\n<li class=\"guide-markup ck-list-marker-bold\" data-start=\"409\" data-end=\"432\" data-list-item-id=\"e7971a117efb420ef9ae3597704f1f3ec\"><p class=\"guide-markup\" data-start=\"411\" data-end=\"432\"><strong class=\"guide-markup\" data-start=\"411\" data-end=\"430\">Price breakdown</strong></p></li>\n</ul><p class=\"guide-markup\" data-start=\"434\" data-end=\"465\"><strong class=\"guide-markup\" data-start=\"434\" data-end=\"463\">Price Breakdown Includes:</strong></p><ul class=\"guide-markup\" data-start=\"466\" data-end=\"629\">\n<li class=\"guide-markup\" data-start=\"466\" data-end=\"549\" data-list-item-id=\"ede3a2db8f76a83053a2473a44525a885\"><p class=\"guide-markup\" data-start=\"468\" data-end=\"549\"><strong class=\"guide-markup\" data-start=\"468\" data-end=\"483\">Base Price:</strong> Your product’s original price (the part that can be negotiated)</p></li>\n<li class=\"guide-markup\" data-start=\"550\" data-end=\"629\" data-list-item-id=\"e980938d1e02a8cd748314d07629c683b\"><p class=\"guide-markup\" data-start=\"552\" data-end=\"629\"><strong class=\"guide-markup\" data-start=\"552\" data-end=\"565\">Shipping:</strong> The standard shipping cost (remains fixed and not negotiable)</p></li>\n</ul><p class=\"guide-markup\" data-start=\"631\" data-end=\"761\">💡 <em class=\"guide-markup\" data-start=\"634\" data-end=\"759\"><em>The difference between the original and negotiated price applies only to your base price. Shipping charges remain the same.</em></em></p><p class=\"guide-markup\" data-start=\"768\" data-end=\"782\"><strong class=\"guide-markup\" data-start=\"768\" data-end=\"780\">Example:</strong></p><ul class=\"guide-markup\" data-start=\"783\" data-end=\"868\">\n<li class=\"guide-markup\" data-start=\"783\" data-end=\"815\" data-list-item-id=\"efd25d763091ff23a8ac90af73032e8a7\"><p class=\"guide-markup\" data-start=\"785\" data-end=\"815\">Original Base Price: £20</p></li>\n<li class=\"guide-markup\" data-start=\"816\" data-end=\"836\" data-list-item-id=\"e33bbe49d9bce4cbf5c79ebefaf6bdcee\"><p class=\"guide-markup\" data-start=\"818\" data-end=\"836\">Shipping: £5</p></li>\n<li class=\"guide-markup\" data-start=\"837\" data-end=\"868\" data-list-item-id=\"e14f64dcdf39e83f57b5b857d6fb78d93\"><p class=\"guide-markup\" data-start=\"839\" data-end=\"868\">Total Listed Price: £25</p></li>\n</ul><p class=\"guide-markup\" data-start=\"870\" data-end=\"1029\">The buyer offers £20 for the bundle.</p><p class=\"guide-markup\" data-start=\"870\" data-end=\"1029\">→ The system applies the £5 discount to your base price, making it £15 base + £5 shipping = £20 total.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K81Q3QH1PPG3AN63P2ZBQ24P\" data-start=\"1325\" data-end=\"1365\"><strong class=\"guide-markup\" data-start=\"1329\" data-end=\"1363\">4. Timeline to Accept an Offer</strong></h3><ul class=\"guide-markup\" data-start=\"1366\" data-end=\"1554\">\n<li class=\"guide-markup\" data-start=\"1366\" data-end=\"1422\" data-list-item-id=\"e70339a659908445bf7157d5565a26bdf\"><p class=\"guide-markup\" data-start=\"1368\" data-end=\"1422\">You have <strong class=\"guide-markup\" data-start=\"1377\" data-end=\"1389\">48 hours</strong> to respond to a buyer’s offer.</p></li>\n<li class=\"guide-markup\" data-start=\"1423\" data-end=\"1483\" data-list-item-id=\"e9a907426815cd8dbc7a21798fa7d82a1\"><p class=\"guide-markup\" data-start=\"1425\" data-end=\"1483\">After <strong class=\"guide-markup\" data-start=\"1431\" data-end=\"1443\">48 hours</strong>, the offer <strong class=\"guide-markup\" data-start=\"1455\" data-end=\"1481\">automatically expires.</strong></p></li>\n<li class=\"guide-markup\" data-start=\"1484\" data-end=\"1554\" data-list-item-id=\"e5a38ddb0f634bd1586815ca1185b99c0\"><p class=\"guide-markup\" data-start=\"1486\" data-end=\"1554\">Respond quickly to <strong class=\"guide-markup\" data-start=\"1505\" data-end=\"1524\">secure the sale</strong> or <strong class=\"guide-markup\" data-start=\"1528\" data-end=\"1551\">send a counteroffer</strong>.</p></li>\n</ul><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K81Q6NYJ4H57WCRWCQ2183K9\" data-start=\"1325\" data-end=\"1365\"><strong class=\"guide-markup\" data-start=\"1329\" data-end=\"1363\">4. How a Customer can Offer a Price</strong></h3><p class=\"guide-markup\" data-start=\"193\" data-end=\"369\">Here’s how buyers can send you their offer price through the <strong class=\"guide-markup\" data-start=\"255\" data-end=\"272\">Make an Offer</strong> feature. Understanding this flow helps you know how and when offers appear in your Vendor App.</p><p class=\"guide-markup\" data-start=\"371\" data-end=\"398\"><strong class=\"guide-markup\" data-start=\"371\" data-end=\"396\">Step-by-Step Process:</strong></p><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 2012/724;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42547245712667\" width=\"2012\" height=\"724\"></figure><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K82YEH2DGT8KHHWH7RDKBF7S\"><strong class=\"guide-markup\">Frequently Asked Questions:</strong></h3><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. Where can I see buyer offers?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    You can view all active buyer offers in your <strong class=\"guide-markup\">Vendor App</strong> under <strong class=\"guide-markup\">“Offers” → “To Respond”</strong> tab or directly from your app’s homepage.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. How long do I have to respond to an offer?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    You have <strong class=\"guide-markup\">48 hours</strong> to respond. After that, the offer will automatically expire.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. Can I counter a buyer’s offer?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. If the offered price isn’t suitable, click <strong class=\"guide-markup\">“Counter Offer”</strong> and enter your desired price.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. What happens when I accept an offer?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Once accepted, a <strong class=\"guide-markup\">unique code</strong> is generated for the buyer to redeem at checkout and complete the purchase at the agreed price.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. Does the negotiated price affect shipping charges?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    No. Shipping charges remain the same — only the <strong class=\"guide-markup\">base product price</strong> is adjusted based on the negotiation.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">6. Can buyers make multiple offers on the same product?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. Buyers can send a new offer if their previous one was <strong class=\"guide-markup\">declined</strong> or <strong class=\"guide-markup\">expired</strong>.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">7. What happens if I don’t respond to an offer?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    If no action is taken within <strong class=\"guide-markup\">48 hours</strong>, the offer will automatically expire and be removed from your pending list.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">8. Is the Make an Offer feature available for all products?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    No. The <strong class=\"guide-markup\">Make an Offer</strong> feature is available only for <strong class=\"guide-markup\">eligible products</strong> that support price negotiation.\n  </div>\n</details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42547096235803,"title":"Grading Guidelines and Policy","body":"<p>Fleek uses a clear grading system so you know the condition of items before you buy. Grading describes expected wear and helps set accurate expectations.</p><h2 id=\"h_01KWBVC54J4CA9RS83NV4F3Y5V\">Grade definitions</h2><p><strong>Grade A — Almost new</strong></p><p>Items are in excellent condition with little to no visible signs of wear.</p><p><strong>Grade B — Moderately worn</strong></p><p>Items show moderate signs of use. May include:</p><ul>\n<li data-list-item-id=\"e3b5721e3a7e4f064e2b6cdc32d010333\">Small stains or holes <strong>under 1cm</strong>\n</li>\n<li data-list-item-id=\"eb174dd02bd71a9c885589a44ae987148\">Missing buttons</li>\n<li data-list-item-id=\"e50d45814b1ce3c08c214db7fbb63640a\">Broken zippers</li>\n</ul><p><strong>Grade C — Clearly worn</strong></p><p>Items show clear, noticeable signs of wear and use.</p><h2 id=\"h_01KWBVC54MW1WYHKF6Q4D7DH76\">Mixed-grade bundles</h2><p>When a bundle contains a mix of grades, the ratios are approximately:</p><figure class=\"wysiwyg-table wysiwyg-table-align-left\"><table>\n<thead><tr>\n<th>Mixed Grade</th>\n<th>Composition</th>\n</tr></thead>\n<tbody>\n<tr>\n<td>AB</td>\n<td>70% Grade A + 30% Grade B</td>\n</tr>\n<tr>\n<td>BC</td>\n<td>60% Grade B + 40% Grade C</td>\n</tr>\n<tr>\n<td>ABC</td>\n<td>30% Grade A + 40% Grade B + 30% Grade C</td>\n</tr>\n</tbody>\n</table></figure><p><strong>Margin of error:</strong> There is a <strong>10% margin of error</strong> on grading across a bundle.</p><h2 id=\"h_01KWBVC54SN5HW4MY848GB1CY2\">Important notes</h2><ul>\n<li data-list-item-id=\"ed1483dc92e5f7137dd9a23c3c29ac0d7\">\n<strong>Workwear &amp; vintage denim:</strong> Rips and distressing may exceed 1cm, as this is characteristic of the category.</li>\n<li data-list-item-id=\"e898a8b5374fbffe2685e8fec61cdde3e\">\n<strong>Minor stains:</strong> Up to <strong>2–3 non-removable stains under 0.3cm</strong> are classified as <strong>Grade B</strong>.</li>\n<li data-list-item-id=\"e593940535449981d37a37461323f1127\">\n<strong>Branded items:</strong> Branded pieces missing their labels are classified as <strong>Grade B</strong>.</li>\n</ul><h2 id=\"h_01KWBVC54T3VN7T2PKDKXKZCF4\">Listing types</h2><ul>\n<li data-list-item-id=\"e38895c29ccfcf48ac9ab6ae2346bd60c\">\n<strong>Representative listings:</strong> Photos represent the type of items you'll receive; exact pieces may vary.</li>\n<li data-list-item-id=\"e5814ced2e241d6a893d3acd26bbe1a6d\">\n<strong>Exact listings:</strong> What you see is exactly what you'll receive.</li>\n<li data-list-item-id=\"e49e274decc2301cbf6205adfc6df8af1\">\n<strong>Custom handpick:</strong> Items selected specifically for you (often via a video handpick call).</li>\n</ul><p><strong>Need help?</strong></p><p>In-app chat: <a href=\"https://clicks.joinfleek.com/support\">clicks.joinfleek.com/support</a></p><p>Webform: <a href=\"https://support.joinfleek.com/hc/en-us/requests/new\">support.joinfleek.com</a></p><p>Email: <a href=\"mailto:support@joinfleek.com\">support@joinfleek.com</a></p>"},{"id":42546929059995,"title":"QC Hold Resolution - Understanding and Process","body":"<div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"d52e05df-a5a7-42ae-901b-d2d2531ac4f4\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\"><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\">\n<div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"aa3534c7-d8f1-431e-9747-760bbf2047b0\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<p class=\"guide-markup\" data-start=\"65\" data-end=\"351\" data-is-last-node=\"\" data-is-only-node=\"\">The <strong class=\"guide-markup\">Quality Check Hold Resolution</strong> process ensures that any product placed on QC hold is reviewed and resolved fairly. It helps seller to understand the reason for the hold and taking necessary actions to provide timely solution to the QC held orders by Fleek.</p>\n<hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K80E372BHWCA3XGJMNGSZPCB\"><strong class=\"guide-markup\">What does QC Hold refer to?</strong></h3>\n<p class=\"guide-markup\" data-start=\"35\" data-end=\"342\">A <strong class=\"guide-markup\" data-start=\"37\" data-end=\"48\">QC Hold</strong> refers to a product that has <strong class=\"guide-markup\" data-start=\"78\" data-end=\"122\">failed to meet Fleek’s quality standards</strong> during the inspection process and has therefore been <strong class=\"guide-markup\" data-start=\"123\" data-end=\"141\">placed on hold</strong> for further review or action. This means the item has one or more issues— such as incorrect sizing, visible damage, stains, missing tags, grade mismatch or mismatched listing details — that prevent it from being approved for sale.</p>\n<p class=\"guide-markup\" data-start=\"344\" data-end=\"526\" data-is-last-node=\"\" data-is-only-node=\"\">When an order is placed on QC Hold, it is temporarily paused from moving forward in the process until the seller reviews the issue and takes corrective action as per Fleek’s guidance.</p>\n</div></div></div></div>\n<h3 class=\"guide-markup\" id=\"h_01K80EFQCCWF0QYK1B2W67F8GP\"><strong class=\"guide-markup\">QC Hold Process:</strong></h3>\n<p class=\"guide-markup\">If any problem is detected during QC inspection, the order is <strong class=\"guide-markup\" data-start=\"1832\" data-end=\"1853\">placed on QC Hold</strong> and tagged for review.</p>\n<p class=\"guide-markup\">Our team will send you a report for flagged items and you will be asked to provide resolution under Fleek's policy. </p>\n<figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 2057/640;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42546929049371\" width=\"2057\" height=\"640\"></figure><p class=\"guide-markup\"> </p>\n<div class=\"guide-markup\">\n<div class=\"guide-markup\">Lets understand the how does each suggested resolution works;</div>\n<div class=\"guide-markup\"> </div>\n<ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"eff57272fc3bd7be08c426a2437d30943\"><p class=\"guide-markup\" data-start=\"110\" data-end=\"197\"><strong class=\"guide-markup\" data-start=\"110\" data-end=\"132\">Offer Discount: </strong>You can offer a discount to the buyer for the flagged items.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"ea87b5e93c9dc1324e22f5f16761f2665\"><p class=\"guide-markup\" data-start=\"199\" data-end=\"327\"><strong class=\"guide-markup\" data-start=\"199\" data-end=\"223\">Partial Dispatch: </strong>You can request to recall all flagged items while the approved items are sent to the buyer.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"ebfa473338fb7e425053d14da89a6d9ca\"><p class=\"guide-markup\" data-start=\"329\" data-end=\"437\"><strong class=\"guide-markup\" data-start=\"329\" data-end=\"350\">Replace Items: </strong>You can send replacement items from your stock to substitute the flagged ones.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"ef356b2b0965b9a69ead7622144e31c34\"><p class=\"guide-markup\" data-start=\"439\" data-end=\"551\"><strong class=\"guide-markup\" data-start=\"439\" data-end=\"468\">Seller Responsibility: </strong>You can request the team to dispatch all items at your own responsibility.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"ed0662b799929ca75c8a0ad13c523a360\"><p class=\"guide-markup\" data-start=\"553\" data-end=\"690\"><strong class=\"guide-markup\" data-start=\"553\" data-end=\"576\">Buyer Alignment: </strong>If your buyer agrees to receive the flagged items, you can proceed with dispatch based on that alignment.</p></li>\n</ul>\n<p class=\"guide-markup\" data-start=\"553\" data-end=\"690\"><strong class=\"guide-markup\">Order Cancellation: </strong>If the resolution is not agreed within the defined timeline, the order will be cancelled and a buyer will be refunded. Click <a class=\"guide-markup\">here</a> to learn about Order Cancellation Policy.</p>\n<div class=\"guide-markup\"><em class=\"guide-markup\"><em><strong class=\"guide-markup\">Important: </strong>Please note that the customer will be onboarded (if necesssary) before closing the loop with you.</em></em></div>\n<div class=\"guide-markup\"> </div>\n<hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K80NCGS525FM6G1VYBZDWDG4\"><strong class=\"guide-markup\">Where can I see my hold orders?</strong></h3>\n<p class=\"guide-markup\">To view your held orders, simply follow the steps below:</p>\n<figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1446/769;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42546929052187\" width=\"1446\" height=\"769\"></figure><hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K80NDHVA9KHTVQPJTC5SR96M\"><strong class=\"guide-markup\">How will I receive Fleek QC Report?</strong></h3>\n<p class=\"guide-markup\">After your order held in QC, you will receive a report in your Fleek Vendor Application.</p>\n<figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1552/817;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42546935987227\" width=\"1552\" height=\"817\"></figure><hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K80T76DNS1ZJW8G0BXJFN1NC\"><strong class=\"guide-markup\">Frequently Asked Questions:</strong></h2>\n</div>\n</div></div></div></div></div></div></div></div><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. What does it mean if my items are flagged during QC?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Flagged items are products that did not fully meet <strong class=\"guide-markup\">Fleek’s QC standards</strong> — for example, due to minor defects, listing mismatches, or presentation issues.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. How will I be notified about flagged items?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    You’ll receive a notification in your <strong class=\"guide-markup\">Vendor Application Chat</strong> with details of the flagged items.  \n    <br class=\"guide-markup\"><br class=\"guide-markup\">\n    If your total quantity is below <strong class=\"guide-markup\">50 units</strong>, a <strong class=\"guide-markup\">QC report link with images</strong> will also be shared.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. What happens if I don’t respond to the QC update?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    If no response is received within the defined timeline, the order may be <strong class=\"guide-markup\">held or delayed</strong> until instructions are received from your side.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. Will flagged items affect my payout?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. Only <strong class=\"guide-markup\">QC Approved</strong> items are eligible for payout.  \n    <br class=\"guide-markup\"><br class=\"guide-markup\">\n    Flagged items are placed <strong class=\"guide-markup\">on hold</strong> until they are resolved or rechecked by the QC team.\n  </div>\n</details><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"d52e05df-a5a7-42ae-901b-d2d2531ac4f4\" data-message-model-slug=\"gpt-5\"><hr class=\"guide-markup\"></div></div></div></div><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42546589245211,"title":"Quality Check Process and Policy","body":"<p class=\"guide-markup\" data-start=\"344\" data-end=\"578\">The <strong class=\"guide-markup\" data-start=\"348\" data-end=\"378\">Quality Check (QC) process</strong> at Fleek is an additional verification layer designed to ensure that every product moving through Fleek’s fulfillment meets our <strong class=\"guide-markup\" data-start=\"516\" data-end=\"575\">quality, grading, packaging, and listing standards</strong>.</p><p class=\"guide-markup\" data-start=\"580\" data-end=\"614\">The purpose of this process is to:</p><ul class=\"guide-markup\" data-start=\"615\" data-end=\"1050\">\n<li class=\"guide-markup\" data-start=\"615\" data-end=\"735\" data-list-item-id=\"e568d62e39de43c3a83fbcde43a4baf76\"><p class=\"guide-markup\" data-start=\"617\" data-end=\"735\"><strong class=\"guide-markup\" data-start=\"617\" data-end=\"627\">Verify</strong> that products received from sellers are consistent with their listed descriptions, sizes, and conditions.</p></li>\n<li class=\"guide-markup\" data-start=\"736\" data-end=\"833\" data-list-item-id=\"e712ecb9b7559d3217f4d7fedab7f7a45\"><p class=\"guide-markup\" data-start=\"738\" data-end=\"833\"><strong class=\"guide-markup\" data-start=\"738\" data-end=\"753\">Standardize</strong> product presentation, ensuring uniform quality and packaging before dispatch.</p></li>\n<li class=\"guide-markup\" data-start=\"834\" data-end=\"939\" data-list-item-id=\"e19ecbff7f933b9c0653376a7bf6bf4ac\"><p class=\"guide-markup\" data-start=\"836\" data-end=\"939\"><strong class=\"guide-markup\" data-start=\"836\" data-end=\"847\">Enhance</strong> buyer experience by maintaining visual and functional consistency across the marketplace.</p></li>\n<li class=\"guide-markup\" data-start=\"940\" data-end=\"1050\" data-list-item-id=\"e834a7b63176f90e7c3b0e426a3756750\"><p class=\"guide-markup\" data-start=\"942\" data-end=\"1050\"><strong class=\"guide-markup\" data-start=\"942\" data-end=\"978\">Enable faster payout eligibility</strong> by minimizing order disputes, grading errors, and listing mismatches.</p></li>\n</ul><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K8091T2WNPEEXFDEBH4TH0H2\"><strong class=\"guide-markup\">Quality Check Process:</strong></h3><p class=\"guide-markup\" data-start=\"0\" data-end=\"171\">Once products are picked up from the seller and delivered to <strong class=\"guide-markup\" data-start=\"61\" data-end=\"82\">Fleek’s warehouse</strong>, they go through a simple and standardized <strong class=\"guide-markup\" data-start=\"126\" data-end=\"160\">Inbound and Quality Check (QC)</strong> process.</p><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1253/810;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42546589244059\" width=\"1253\" height=\"810\"></figure><p class=\"guide-markup\" data-start=\"173\" data-end=\"239\" data-is-last-node=\"\" data-is-only-node=\"\">Let’s break down how the <strong class=\"guide-markup\" data-start=\"198\" data-end=\"239\" data-is-last-node=\"\">QC process works in a few easy steps.</strong></p><p class=\"guide-markup\">Step 1: Items Inbounded to the Fleek's WareHouse</p><p class=\"guide-markup\">Step 2: Sent to QC center</p><p class=\"guide-markup\">Step 3: Quality Check Started</p><p class=\"guide-markup\" data-start=\"1254\" data-end=\"1407\">Once inbounding is complete, the QC team begins inspection to ensure the items align with Fleek’s<strong class=\"guide-markup\" data-start=\"1352\" data-end=\"1381\"> quality standards</strong><strong class=\"guide-markup\" data-start=\"1386\" data-end=\"1407\">.</strong></p><p class=\"guide-markup\" data-start=\"1409\" data-end=\"1444\">Each product is evaluated based on:</p><ul class=\"guide-markup\" data-start=\"1445\" data-end=\"1669\">\n<li class=\"guide-markup\" data-start=\"1445\" data-end=\"1506\" data-list-item-id=\"e32ba4e6e6296f191cb2dcf45754611ea\"><p class=\"guide-markup\" data-start=\"1447\" data-end=\"1506\"><strong class=\"guide-markup\" data-start=\"1447\" data-end=\"1470\">Condition &amp; Grading</strong> (e.g., New, Like New, Good, Fair)</p></li>\n<li class=\"guide-markup ck-list-marker-bold\" data-start=\"1507\" data-end=\"1536\" data-list-item-id=\"ed4d3f8810c83043c93d98fe5769395a9\"><p class=\"guide-markup\" data-start=\"1509\" data-end=\"1536\"><strong class=\"guide-markup\" data-start=\"1509\" data-end=\"1534\">Authenticity</strong></p></li>\n<li class=\"guide-markup\" data-start=\"1537\" data-end=\"1598\" data-list-item-id=\"e04abe5489e50444917747a89c1d8224c\"><p class=\"guide-markup\" data-start=\"1539\" data-end=\"1598\"><strong class=\"guide-markup\" data-start=\"1539\" data-end=\"1550\">Defects</strong> (e.g., stains, holes, tears, missing buttons)</p></li>\n<li class=\"guide-markup\" data-start=\"1599\" data-end=\"1641\" data-list-item-id=\"e08b5fb02dac0d17a75a66a38394a5b2c\"><p class=\"guide-markup\" data-start=\"1601\" data-end=\"1641\"><strong class=\"guide-markup\" data-start=\"1601\" data-end=\"1618\">Listing Match</strong> (size, color, style)</p></li>\n<li class=\"guide-markup ck-list-marker-bold\" data-start=\"1599\" data-end=\"1641\" data-list-item-id=\"ea3b1118588d1eeade7fa12aaaa785b70\"><p class=\"guide-markup\" data-start=\"1601\" data-end=\"1641\"><strong class=\"guide-markup\">Product Matches Listing</strong></p></li>\n</ul><p class=\"guide-markup\" data-start=\"1671\" data-end=\"1733\">After inspection, the item will move into one of two outcomes:</p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"ef5151da3664f79962781874c0b644f4f\"><p class=\"guide-markup\" data-start=\"1671\" data-end=\"1733\">QC Approved</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"e36974b01ca987e7e496dcf72d367f735\"><p class=\"guide-markup\" data-start=\"1671\" data-end=\"1733\">QC Hold</p></li>\n</ul><p class=\"guide-markup\"><strong class=\"guide-markup\" data-start=\"2500\" data-end=\"2535\">a. QC Approved (No Issue Found)</strong></p><p class=\"guide-markup\" data-start=\"2536\" data-end=\"2571\">If the item meets all QC standards:</p><ul class=\"guide-markup\" data-start=\"2572\" data-end=\"2773\"><li class=\"guide-markup\" data-start=\"2572\" data-end=\"2618\" data-list-item-id=\"e857a9198de39a5782bb08baee1ec2854\"><p class=\"guide-markup\" data-start=\"2574\" data-end=\"2618\">It is marked <strong class=\"guide-markup\" data-start=\"2587\" data-end=\"2602\">QC Approved</strong> in the system. Item moves to the <strong class=\"guide-markup\" data-start=\"2722\" data-end=\"2740\">Packaging Area</strong> for final packing and labeling</p></li></ul><p class=\"guide-markup\" data-start=\"2775\" data-end=\"2809\"><strong class=\"guide-markup\" data-start=\"2775\" data-end=\"2793\">System Status:</strong> <em class=\"guide-markup\" data-start=\"2794\" data-end=\"2807\"><em>QC Approved</em></em></p><p class=\"guide-markup\"><strong class=\"guide-markup\" data-start=\"2500\" data-end=\"2535\">b. </strong><strong class=\"guide-markup\" data-start=\"1744\" data-end=\"1772\">QC Hold (Issue Found)</strong></p><p class=\"guide-markup\" data-start=\"1773\" data-end=\"1908\">If any issue is detected during inspection, the product is <strong class=\"guide-markup\" data-start=\"1832\" data-end=\"1853\">placed on QC Hold</strong> and tagged for review.<br>Possible reasons for QC Hold:</p><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\">\n<div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\">\n<div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"cea61f96-cc71-4bc7-884c-92fb5bb07c1a\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\"><p class=\"guide-markup\" data-start=\"0\" data-end=\"87\" data-is-last-node=\"\" data-is-only-node=\"\">Click <a class=\"guide-markup\">here</a> to learn how to resolve issues for orders that are currently on <strong class=\"guide-markup\" data-start=\"75\" data-end=\"86\">QC Hold</strong>.</p></div></div></div></div>\n<hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K80WNTQVB88HDQXCQW52Z828\" data-start=\"0\" data-end=\"37\"><strong class=\"guide-markup\" data-start=\"4\" data-end=\"37\">What is QC Hold? How It Works?</strong></h3>\n<p class=\"guide-markup\" data-start=\"39\" data-end=\"271\"><strong class=\"guide-markup\" data-start=\"39\" data-end=\"50\">QC Hold</strong> means that one or more of your items did not fully meet Fleek’s Quality Check (QC) standards during inspection.</p>\n<p class=\"guide-markup\" data-start=\"39\" data-end=\"271\">This status is used when an item requires your attention before it can be approved for dispatch or payout.</p>\n</div></div>\n<div class=\"guide-markup\">\n<div class=\"guide-markup\">Click <a class=\"guide-markup\">here</a> to understand the QC hold process and understanding.</div>\n<div class=\"guide-markup\"> </div>\n<hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K810AZ35HTZ4CY1XZXGQC73M\" data-start=\"0\" data-end=\"27\">\n<strong class=\"guide-markup\" data-start=\"4\" data-end=\"25\">How Grading Works</strong><strong class=\"guide-markup\" data-start=\"4\" data-end=\"37\">:</strong>\n</h3>\n<p class=\"guide-markup\">Grading helps define the <strong class=\"guide-markup\" data-start=\"54\" data-end=\"85\">condition and quality level</strong> of each vintage item so buyers know exactly what to expect.</p>\n<div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"4f736ca3-d387-470b-bed6-8886113557b8\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"62\" data-is-last-node=\"\" data-is-only-node=\"\">Click <a class=\"guide-markup\">here</a> to learn more about <strong class=\"guide-markup\" data-start=\"31\" data-end=\"52\">how grading works</strong> on Fleek.</p>\n<hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K811AQCW7P9GWCYNV477W69S\" data-start=\"83\" data-end=\"119\"><strong class=\"guide-markup\" data-start=\"87\" data-end=\"119\">Fleek’s Responsibility in Quality Check</strong></h3>\n<p class=\"guide-markup\" data-start=\"121\" data-end=\"325\">Fleek’s Quality Check (QC) process is to designed to minimize the potential issues and ensure that all inbound items meet the <strong class=\"guide-markup\" data-start=\"213\" data-end=\"276\">platform’s operational, grading, and presentation standards</strong> before they are approved for sale or dispatch.</p>\n<ul class=\"guide-markup\" data-start=\"355\" data-end=\"742\">\n<li class=\"guide-markup\" data-start=\"355\" data-end=\"428\" data-list-item-id=\"ed48505463a64f83dbbb55b39e27f9710\"><p class=\"guide-markup\" data-start=\"357\" data-end=\"428\">Inspecting items for <strong class=\"guide-markup\" data-start=\"378\" data-end=\"426\">condition, cleanliness, and accurate grading</strong></p></li>\n<li class=\"guide-markup\" data-start=\"429\" data-end=\"511\" data-list-item-id=\"e07a2ce2051975b639211eab82f5a5734\"><p class=\"guide-markup\" data-start=\"431\" data-end=\"511\">Ensuring that <strong class=\"guide-markup\" data-start=\"445\" data-end=\"478\">products match their listings</strong> (size, color, and description)</p></li>\n<li class=\"guide-markup\" data-start=\"512\" data-end=\"585\" data-list-item-id=\"e2f93eaa00c84c662a548cdf4135208b1\"><p class=\"guide-markup\" data-start=\"514\" data-end=\"585\">Verifying that items are <strong class=\"guide-markup\" data-start=\"539\" data-end=\"583\">properly packaged and ready for shipment</strong></p></li>\n<li class=\"guide-markup\" data-start=\"586\" data-end=\"659\" data-list-item-id=\"e12ff5d54dcb6c9e9ea1f8caf073c4cfb\"><p class=\"guide-markup\" data-start=\"588\" data-end=\"659\">Tagging any issues and placing items on <strong class=\"guide-markup\" data-start=\"628\" data-end=\"639\">QC Hold</strong> for seller review</p></li>\n<li class=\"guide-markup\" data-start=\"660\" data-end=\"742\" data-list-item-id=\"eff47fd6a5a2e089433035a1d628bd5ac\"><p class=\"guide-markup\" data-start=\"662\" data-end=\"742\">Providing sellers with <strong class=\"guide-markup\" data-start=\"685\" data-end=\"722\">clear feedback and visual reports</strong> <em class=\"guide-markup\"><em>(based on the items count)</em></em> for flagged items</p></li>\n</ul>\n<blockquote class=\"guide-markup\" data-start=\"744\" data-end=\"1023\"><p class=\"guide-markup\" data-start=\"746\" data-end=\"1023\"><strong class=\"guide-markup\" data-start=\"746\" data-end=\"760\">Important:</strong> Fleek’s QC process is a <strong class=\"guide-markup\" data-start=\"785\" data-end=\"807\">verification layer</strong>, not a quality or authenticity guarantee.<br>Fleek is <strong class=\"guide-markup\" data-start=\"861\" data-end=\"880\">not responsible</strong> for product authenticity, quality, or refund-related decisions — these are handled under the <strong class=\"guide-markup\" data-start=\"996\" data-end=\"1022\">Refund &amp; Claims Policy </strong>and<strong class=\"guide-markup\" data-start=\"996\" data-end=\"1022\"> Seller is responsible </strong>for the refunds.</p></blockquote>\n</div></div></div></div></div></div>\n<hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K8155H736ZB9NA5253MT3W5Q\"><strong class=\"guide-markup\" data-start=\"506\" data-end=\"541\">Why Your Items Might Be Flagged</strong></h3>\n<figure class=\"wysiwyg-table wysiwyg-table-align-left guide-markup\"><table style=\"margin-left: 0px; margin-right: auto;\" class=\"guide-markup\" data-start=\"164\" data-end=\"1757\">\n<thead class=\"guide-markup\" data-start=\"164\" data-end=\"236\"><tr class=\"guide-markup\" data-start=\"164\" data-end=\"236\">\n<th style=\"text-align: center;\" class=\"guide-markup\" data-start=\"164\" data-end=\"179\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"166\" data-end=\"178\">Category</strong></th>\n<th style=\"text-align: center;\" class=\"guide-markup\" data-start=\"179\" data-end=\"199\" data-col-size=\"md\"><strong class=\"guide-markup\" data-start=\"181\" data-end=\"198\">What It Means</strong></th>\n<th style=\"text-align: center;\" class=\"guide-markup\" data-start=\"199\" data-end=\"214\" data-col-size=\"md\"><strong class=\"guide-markup\" data-start=\"201\" data-end=\"213\">Examples</strong></th>\n<th style=\"text-align: center;\" class=\"guide-markup\" data-start=\"214\" data-end=\"236\" data-col-size=\"md\"><strong class=\"guide-markup\" data-start=\"216\" data-end=\"234\">Why It Matters</strong></th>\n</tr></thead>\n<tbody class=\"guide-markup\" data-start=\"312\" data-end=\"1757\">\n<tr class=\"guide-markup\" data-start=\"312\" data-end=\"493\">\n<td class=\"guide-markup\" data-start=\"312\" data-end=\"343\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"314\" data-end=\"342\">1. Authenticity Concerns</strong></td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"343\" data-end=\"370\">Item may not be genuine.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"370\" data-end=\"439\">Counterfeit branding, incorrect labels, missing authenticity tags.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"439\" data-end=\"493\">Damages trust and can lead to disputes or refunds.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"494\" data-end=\"655\">\n<td class=\"guide-markup\" data-start=\"494\" data-end=\"517\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"496\" data-end=\"516\">2. Sizing Issues</strong></td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"517\" data-end=\"552\">Item size doesn’t match listing.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"552\" data-end=\"610\">Medium labeled as Large, children’s size sent as adult.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"610\" data-end=\"655\">Causes poor buyer experience and returns.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"656\" data-end=\"803\">\n<td class=\"guide-markup\" data-start=\"656\" data-end=\"688\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"658\" data-end=\"687\">3. Fading / Discoloration</strong></td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"688\" data-end=\"722\">Visible fading or uneven color.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"722\" data-end=\"765\">Washed-out colors, sun or bleach damage.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"765\" data-end=\"803\">Lowers item value and wearability.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"804\" data-end=\"984\">\n<td class=\"guide-markup\" data-start=\"804\" data-end=\"839\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"806\" data-end=\"838\">4. Grading / Incorrect Ratio</strong></td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"839\" data-end=\"883\">Shipment doesn’t follow agreed grade mix.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"883\" data-end=\"934\">Promised 70% A / 30% B but contains more B or C.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"934\" data-end=\"984\">Creates mismatch between promise and delivery.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"985\" data-end=\"1154\">\n<td class=\"guide-markup\" data-start=\"985\" data-end=\"1024\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"987\" data-end=\"1023\">5. Button / Zip / Elastic Issues</strong></td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1024\" data-end=\"1056\">Faulty or missing fastenings.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1056\" data-end=\"1107\">Broken zippers, missing buttons, loose elastics.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1107\" data-end=\"1154\">Reduces functionality and resale potential.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"1155\" data-end=\"1302\">\n<td class=\"guide-markup\" data-start=\"1155\" data-end=\"1177\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"1157\" data-end=\"1176\">6. Holes / Rips</strong></td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1177\" data-end=\"1213\">Visible tears or holes in fabric.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1213\" data-end=\"1256\">Ripped seams, torn pockets, small holes.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1256\" data-end=\"1302\">Damaged items can’t be listed as wearable.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"1303\" data-end=\"1456\">\n<td class=\"guide-markup\" data-start=\"1303\" data-end=\"1327\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"1305\" data-end=\"1326\">7. Marks / Stains</strong></td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1327\" data-end=\"1364\">Noticeable stains or dirt patches.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1364\" data-end=\"1404\">Oil, ink, or food stains, rust marks.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1404\" data-end=\"1456\">Reduces presentation quality and buyer interest.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"1457\" data-end=\"1604\">\n<td class=\"guide-markup\" data-start=\"1457\" data-end=\"1485\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"1459\" data-end=\"1484\">8. Mold / Odor Issues</strong></td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1485\" data-end=\"1519\">Mold, mildew, or strong smells.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1519\" data-end=\"1557\">Damp or musty odor, visible fungus.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1557\" data-end=\"1604\">Health concern and unacceptable for resale.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"1605\" data-end=\"1757\">\n<td class=\"guide-markup\" data-start=\"1605\" data-end=\"1637\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"1607\" data-end=\"1636\">9. Pilling / Surface Wear</strong></td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1637\" data-end=\"1667\">Heavy surface fuzz or wear.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1667\" data-end=\"1713\">Worn-out sweaters or leggings with pilling.</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1713\" data-end=\"1757\">Indicates overuse and lowers item grade.</td>\n</tr>\n</tbody>\n</table></figure><hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K81043RSY8VC4BXC7MN494CP\" data-start=\"3276\" data-end=\"3294\"><strong class=\"guide-markup\" data-start=\"3280\" data-end=\"3294\">Key Points:</strong></h3>\n<ul class=\"guide-markup\" data-start=\"3295\" data-end=\"3611\">\n<li class=\"guide-markup\" data-start=\"3295\" data-end=\"3354\" data-list-item-id=\"e9db185f07f8886fcb6902fd3f6155669\"><p class=\"guide-markup\" data-start=\"3297\" data-end=\"3354\">QC is a <strong class=\"guide-markup\" data-start=\"3305\" data-end=\"3327\">verification layer</strong>, not a refund authority.</p></li>\n<li class=\"guide-markup\" data-start=\"3355\" data-end=\"3436\" data-list-item-id=\"ef17b6bb2b0bafda606e707641b9d53ee\"><p class=\"guide-markup\" data-start=\"3357\" data-end=\"3436\">Authenticity and refund claims are governed under <strong class=\"guide-markup\" data-start=\"3407\" data-end=\"3434\">Refund &amp; Claims Policy.</strong></p></li>\n<li class=\"guide-markup\" data-start=\"3437\" data-end=\"3507\" data-list-item-id=\"eb9ca4a456643e17eb610e3084ee093e3\"><p class=\"guide-markup\" data-start=\"3439\" data-end=\"3507\">QC approval ensures operational readiness — not product guarantee.</p></li>\n<li class=\"guide-markup\" data-start=\"3508\" data-end=\"3611\" data-list-item-id=\"efccd84c0cf1d9129a7f293207c34d360\"><p class=\"guide-markup\" data-start=\"3510\" data-end=\"3611\">The process aims to <strong class=\"guide-markup\" data-start=\"3530\" data-end=\"3611\">reduce buyer complaints, maintain consistency, and accelerate seller payouts.</strong></p></li>\n</ul>\n<hr class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K811ARS02EVHC1R7J8TJWVV5\" data-start=\"0\" data-end=\"24\"><strong class=\"guide-markup\" data-start=\"4\" data-end=\"22\">Benefits of QC</strong></h3>\n<ul class=\"guide-markup\" data-start=\"25\" data-end=\"317\" data-is-last-node=\"\" data-is-only-node=\"\">\n<li class=\"guide-markup\" data-start=\"25\" data-end=\"57\" data-list-item-id=\"e7cd64b440a33b9b1b8076609300c5963\"><p class=\"guide-markup\" data-start=\"27\" data-end=\"57\">It help reduces returns and disputes</p></li>\n<li class=\"guide-markup\" data-start=\"58\" data-end=\"97\" data-list-item-id=\"ebeafd505a605321d0994068c38993f60\"><p class=\"guide-markup\" data-start=\"60\" data-end=\"97\">Builds buyer trust and satisfaction</p></li>\n<li class=\"guide-markup\" data-start=\"98\" data-end=\"130\" data-list-item-id=\"ea65ae14eaf9c19da319c5232633a9561\"><p class=\"guide-markup\" data-start=\"100\" data-end=\"130\">Speeds up payout eligibility</p></li>\n<li class=\"guide-markup\" data-start=\"173\" data-end=\"220\" data-list-item-id=\"e0b137a3a090178175c1afe469dcffe05\"><p class=\"guide-markup\" data-start=\"175\" data-end=\"220\">Improves product presentation and packaging</p></li>\n<li class=\"guide-markup\" data-start=\"221\" data-end=\"272\" data-list-item-id=\"e36ce7715afa9ddc018e558937d9b3ed4\"><p class=\"guide-markup\" data-start=\"223\" data-end=\"272\">Helps sellers identify and fix recurring issues</p></li>\n<li class=\"guide-markup\" data-start=\"273\" data-end=\"317\" data-is-last-node=\"\" data-list-item-id=\"e9598919a0475afea30dda94fb4f73b93\"><p class=\"guide-markup\" data-start=\"275\" data-end=\"317\" data-is-last-node=\"\">Maintains consistent marketplace standards</p></li>\n</ul>\n<hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K81184Z07QEBHMZV6CRKRM45\"><strong class=\"guide-markup\">Frequently Asked Questions:</strong></h2>\n</div>\n</div></div><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. What is QC?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    <strong class=\"guide-markup\">QC (Quality Check)</strong> is the inspection process where Fleek reviews each item to ensure it meets our <strong class=\"guide-markup\">grading</strong>, <strong class=\"guide-markup\">packaging</strong>, and <strong class=\"guide-markup\">listing standards</strong> before it’s approved for sale or dispatch.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. Why is QC important?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    QC helps maintain <strong class=\"guide-markup\">consistency</strong> and <strong class=\"guide-markup\">buyer trust</strong> by ensuring that only properly graded and accurately listed items are shipped.  \n    <br class=\"guide-markup\"><br class=\"guide-markup\">\n    It also helps reduce <strong class=\"guide-markup\">returns</strong> and <strong class=\"guide-markup\">disputes</strong> by verifying each item before dispatch.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. What happens during QC?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Each item is checked for:  \n    <ul style=\"margin-top: 4px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">Condition and cleanliness</li>\n      <li class=\"guide-markup\">Accurate grading and description</li>\n      <li class=\"guide-markup\">Listing and image match</li>\n    </ul>\n    Based on the inspection, the item is either <strong class=\"guide-markup\">QC Approved</strong> or placed on <strong class=\"guide-markup\">QC Hold</strong> if an issue is found.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. What does QC Hold mean?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    <strong class=\"guide-markup\">QC Hold</strong> means that one or more items didn’t fully meet Fleek’s QC standards and need your action before they can be approved for dispatch or payout.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. How will I know if my items are on QC Hold?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    You’ll receive a notification in your <strong class=\"guide-markup\">Vendor Application Chat</strong> where you can view and respond directly to the QC team.  \n    <br class=\"guide-markup\"><br class=\"guide-markup\">\n    A detailed <strong class=\"guide-markup\">QC report or summary</strong> will also be shared for your reference.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">6. Can I get images of my QC Hold items?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes.  \n    <br class=\"guide-markup\"><br class=\"guide-markup\">\n    If your shipment has fewer than <strong class=\"guide-markup\">50 items</strong>, you’ll receive a <strong class=\"guide-markup\">QC report link with product images</strong>.  \n    For larger shipments, a <strong class=\"guide-markup\">text summary</strong> will be shared in chat.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">7. How can I resolve a QC Hold?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    You can choose to:  \n    <ul style=\"margin-top: 4px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">Offer a discount</li>\n      <li class=\"guide-markup\">Replace flagged items</li>\n      <li class=\"guide-markup\">Recall flagged items and dispatch approved ones</li>\n      <li class=\"guide-markup\">Proceed on your own responsibility</li>\n      <li class=\"guide-markup\">Dispatch if the buyer is aligned</li>\n    </ul>\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">8. Does QC affect my payout?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. Only <strong class=\"guide-markup\">QC Approved</strong> items are eligible for payout.  \n    <br class=\"guide-markup\"><br class=\"guide-markup\">\n    Items on <strong class=\"guide-markup\">QC Hold</strong> or pending action will be excluded until they are resolved.\n  </div>\n</details>\n\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">9. Is QC responsible for refunds or authenticity issues?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    No. QC serves as a <strong class=\"guide-markup\">verification layer</strong> to ensure presentation and grading consistency.  \n    <br class=\"guide-markup\"><br class=\"guide-markup\">\n    <strong class=\"guide-markup\">Refunds</strong> and <strong class=\"guide-markup\">authenticity claims</strong> are managed separately under Fleek’s <strong class=\"guide-markup\">Refund &amp; Claims Policy</strong>.\n  </div>\n</details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42546479618331,"title":"Commission & Fees Overview","body":"<div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"e5cfa8a6-8d69-492c-9861-b9e56aeb47cc\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<p class=\"guide-markup\" data-start=\"49\" data-end=\"394\" data-is-last-node=\"\" data-is-only-node=\"\">Understanding Fleek’s commission, fees, and penalties is essential for managing your earnings and maintaining account compliance. This section provides a clear breakdown of all applicable charges — including commission rates, transaction fees, and penalties for policy violations — to ensure full transparency in how your payouts are calculated.</p>\n<hr class=\"guide-markup\">\n<p class=\"guide-markup\"><span class=\"guide-markup\" data-canva-clipboard=\"\"></span></p>\n<div class=\"guide-markup\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<h3 class=\"guide-markup\" id=\"h_01K7Q8WXRX4HAKQ4NK68KKZZX0\" data-start=\"275\" data-end=\"324\"><strong class=\"guide-markup\" data-start=\"279\" data-end=\"324\">Commission:</strong></h3>\n<p class=\"guide-markup\">Fleek charges a service fee on each order to cover platform and operational costs. Lets understand how the commission is applied, deducted, and shown in your payout summary.</p>\n<ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"ea4af5227784ee72e755bdb4990d8b485\">Fleek applies a standard <strong>15% commission</strong> on the base price of each eligible order.</li>\n<li class=\"guide-markup\" data-list-item-id=\"e8cbb4c7abb22f765cb18920f9b207ded\">This commission is automatically deducted from your payout, and the remaining net amount is transferred to your verified bank account.</li>\n</ul>\n<p>Here is the commission structure,</p>\n<figure class=\"wysiwyg-table\" style=\"width: 81.29%;\"><table class=\"wysiwyg-table-resized\" style=\"border-style: solid; border-width: 1px;\">\n<colgroup>\n<col style=\"width: 72.22%;\">\n<col style=\"width: 27.78%;\">\n</colgroup>\n<tbody>\n<tr>\n<td style=\"border-style: solid; border-width: 1px;\"><strong>Seller Type</strong></td>\n<td style=\"border-style: solid; border-width: 1px;\"><strong>Commission</strong></td>\n</tr>\n<tr>\n<td style=\"border-style: solid; border-width: 1px;\">Existing Rework Style Sellers <em>(except true reworks)</em>\n</td>\n<td style=\"border-style: solid; border-width: 1px; text-align: center;\">25%</td>\n</tr>\n<tr>\n<td style=\"border-style: solid; border-width: 1px;\">Patagonia Rework Style Sellers</td>\n<td style=\"border-style: solid; border-width: 1px; text-align: center;\">20%</td>\n</tr>\n<tr>\n<td style=\"border-style: solid; border-width: 1px;\">Burberry Scarves Sellers</td>\n<td style=\"border-style: solid; border-width: 1px; text-align: center;\">20%</td>\n</tr>\n<tr>\n<td style=\"border-style: solid; border-width: 1px;\">Ed Hardy Deadstock Sellers</td>\n<td style=\"border-style: solid; border-width: 1px; text-align: center;\">20%</td>\n</tr>\n</tbody>\n</table></figure><p class=\"guide-markup\">Please note, commissions are non-refundable in cases of refunds or returns.</p>\n</div></div></div>\n</div></div></div></div></div></div><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7SNS7CR2WCX7M3EBFNFJ29T\" data-start=\"275\" data-end=\"324\"><strong class=\"guide-markup\">Additional Fees &amp; Charges:</strong></h3><p class=\"guide-markup\" data-start=\"228\" data-end=\"460\">In addition to the standard commission, Fleek may apply certain fees and charges based on specific scenarios. These fees help maintain smooth operations, cover administrative costs, and encourage compliance with platform policies.</p><figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 1920/1080;\" src=\"https://support.joinfleek.com/hc/article_attachments/42546463241115\" alt=\"Commission, Fees &amp; Penalties (1).jpg\" width=\"1920\" height=\"1080\"></figure><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7SQGCZAD5S45RTBCQV1FVG7\" data-start=\"275\" data-end=\"324\"><strong class=\"guide-markup\">Best Practices to Avoid Deductions:</strong></h3><p class=\"guide-markup\" data-start=\"0\" data-end=\"91\">By following these best practices, you can avoid additional fees and financial penalties:</p><ul class=\"guide-markup\" data-start=\"93\" data-end=\"420\" data-is-last-node=\"\" data-is-only-node=\"\">\n<li class=\"guide-markup\" data-start=\"93\" data-end=\"177\" data-list-item-id=\"e2b12ecd019cd7baca4d5af89c8a54257\"><p class=\"guide-markup\" data-start=\"95\" data-end=\"177\">Fulfill orders promptly to ensure smooth delivery and customer satisfaction.</p></li>\n<li class=\"guide-markup\" data-start=\"178\" data-end=\"253\" data-list-item-id=\"ebf164bae839ab94764327a20813498c9\"><p class=\"guide-markup\" data-start=\"180\" data-end=\"253\">Maintain accurate product listings with correct details and images.</p></li>\n<li class=\"guide-markup\" data-start=\"254\" data-end=\"332\" data-list-item-id=\"e9791dcff771da8624bc7b5ca8264af8c\"><p class=\"guide-markup\" data-start=\"256\" data-end=\"332\">Minimize cancellations and refunds through proactive order management.</p></li>\n<li class=\"guide-markup\" data-start=\"333\" data-end=\"420\" data-is-last-node=\"\" data-list-item-id=\"ea45cded81c90fa6738d1e2973d6d5cbe\"><p class=\"guide-markup\" data-start=\"335\" data-end=\"420\" data-is-last-node=\"\">Comply with Fleek’s selling policies to maintain a good standing on the platform.</p></li>\n</ul><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7SQGCZAJF9NN1AGVEVWPK5B\" data-start=\"275\" data-end=\"324\">\n<strong class=\"guide-markup\" data-start=\"147\" data-end=\"188\">Frequently Asked Questions</strong><strong class=\"guide-markup\">:</strong>\n</h3><details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. Why does Fleek charge a commission?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    The commission covers\n    <strong class=\"guide-markup\">operational, marketing, and platform costs</strong> that help sellers\n    reach international buyers and ensure smooth transactions. It’s a standard\n    practice across online marketplaces.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. When is the commission deducted — before or after payout?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    The commission is automatically <strong class=\"guide-markup\">deducted before payout</strong>.\n    You’ll always receive the <strong class=\"guide-markup\">net amount</strong> after all applicable\n    fees and deductions have been processed.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. I offered a refund to a buyer — will my commission be returned?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    <strong class=\"guide-markup\">No.</strong> The commission\n    remains <strong class=\"guide-markup\">non-refundable</strong>, even if the order is later refunded.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. Why was I charged an extra amount apart from the commission?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Extra charges may appear due to\n    <strong class=\"guide-markup\">transaction fees, cancellation fees, refund penalties,</strong> or\n    <strong class=\"guide-markup\">RTV (return shipping) costs</strong>. You can view detailed breakdowns\n    for each order in your <strong class=\"guide-markup\">Payout Summary</strong>.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. What is the 15 USD transaction fee for?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    The <strong class=\"guide-markup\">USD 15 transaction fee</strong> is a fixed processing charge\n    applied to <strong class=\"guide-markup\">business account payouts</strong> by Fleek’s banking partner.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">6. What happens if I cancel an order myself?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    A <strong class=\"guide-markup\">2.5% cancellation fee</strong> is applied to any seller-initiated\n    cancellation, as it impacts the buyer experience and order fulfillment standards.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">7. What if the buyer cancels the order?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    If the buyer cancels the order <strong class=\"guide-markup\">before shipment</strong>, no commission\n    or cancellation fee is applied. However, if a fee was deducted in error for\n    a buyer-initiated cancellation, please contact\n    <strong class=\"guide-markup\">Seller Support</strong> for review and correction.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">8. What are “Vintage-Inspired Product” fees?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    These fees apply to listings that\n    <strong class=\"guide-markup\">imitate branded or original vintage designs</strong>. To maintain\n    authenticity on the platform, an <strong class=\"guide-markup\">additional 5% commission</strong>\n    is charged for such products.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">9. What is the Legit App Fee and when is it charged?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    If a dispute is raised through the <strong class=\"guide-markup\">Legit App</strong> and the case\n    is resolved in the buyer’s favor, the supplier bears the\n    <strong class=\"guide-markup\">cost of that case</strong> as part of the Legit App Fee.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">10. Can I appeal or dispute a fee deduction?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. You can contact <strong class=\"guide-markup\">Seller Support</strong> within\n    <strong class=\"guide-markup\">7 business days</strong> of the deduction by sharing your\n    <strong class=\"guide-markup\">order ID</strong> and <strong class=\"guide-markup\">payout details</strong>. The team will\n    review your case and respond accordingly.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">11. How can I prevent future deductions or penalties?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Follow these best practices:<br class=\"guide-markup\">\n    <br class=\"guide-markup\">\n    • Ship all orders within the handling time.<br class=\"guide-markup\">\n    • Keep listings accurate and up to date.<br class=\"guide-markup\">\n    • Avoid order cancellations.<br class=\"guide-markup\">\n    • Follow Fleek’s listing and selling policies.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">12. Where can I check all my deductions in detail?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    You can view all <strong class=\"guide-markup\">commissions, fees, and penalties</strong> under\n    the <strong class=\"guide-markup\">Payout Summary</strong> in your\n    <strong class=\"guide-markup\">Fleek Vendor App</strong> — each transaction clearly lists the deduction\n    type and amount.\n  </div>\n\n</details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42546215034395,"title":"Bank Account Setup & Verification","body":"<p class=\"guide-markup\" data-start=\"215\" data-end=\"368\">Ensuring timely and secure payments is essential for running a successful business on Fleek. </p><p class=\"guide-markup\" data-start=\"215\" data-end=\"368\">This guide will help you accurately add or update your bank account details and link them to your store, so all future payments are processed smoothly.</p><p class=\"guide-markup\" data-start=\"215\" data-end=\"368\">Please review the instructions below carefully based on your location.</p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" style=\"color: #ffcc00;\" id=\"h_01K607B2SE9WJ082EYJB23EG9Z\" data-start=\"1289\" data-end=\"1325\"><span style=\"color: hsl(0,0%,0%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">For Pakistan Based Supplier</strong></span></span></h2><p class=\"guide-markup\" data-start=\"408\" data-end=\"458\">To update your bank account, follow these steps:</p><ol class=\"guide-markup\" data-start=\"460\" data-end=\"707\">\n<li class=\"guide-markup\" data-start=\"460\" data-end=\"530\" data-list-item-id=\"e4c34da6804a6c11cf509c8a2f145347f\"><p class=\"guide-markup\" data-start=\"463\" data-end=\"530\"><strong class=\"guide-markup\" data-start=\"463\" data-end=\"495\">Use your registered email ID</strong> when updating your bank account.</p></li>\n<li class=\"guide-markup\" data-start=\"531\" data-end=\"707\" data-list-item-id=\"ed380955443852f7c36d870f42ccc2414\"><p class=\"guide-markup\" data-start=\"534\" data-end=\"707\"><strong class=\"guide-markup\" data-start=\"534\" data-end=\"561\">Fill out the form here:</strong><br>👉 <a class=\"guide-markup\" data-start=\"567\" data-end=\"705\" target=\"_new\" rel=\"noopener\" href=\"https://docs.google.com/forms/d/e/1FAIpQLSfGGLIy5VtkKwmLkxK4IbAlwESWQ8spNlpQ48IT-9GQd-KukQ/viewform\">Bank Account Update Form (Pakistan)</a><span class=\"guide-markup\" aria-hidden=\"true\"><a class=\"guide-markup\"></a></span><a class=\"guide-markup\" data-start=\"567\" data-end=\"705\" target=\"_new\" rel=\"noopener\"></a></p></li>\n</ol><p class=\"guide-markup\" data-start=\"934\" data-end=\"1016\">Your IBAN must be exactly <strong class=\"guide-markup\" data-start=\"960\" data-end=\"973\">24 digits</strong> – please double-check before submitting.</p><hr class=\"guide-markup\" data-start=\"1284\" data-end=\"1287\"><h2 class=\"guide-markup\" style=\"color: #ffcc00;\" id=\"h_01K7QD2J0WPYA8X9A2KWGP4B2W\" data-start=\"1289\" data-end=\"1325\"><span style=\"color: hsl(0,0%,0%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">For Sellers Outside Pakistan</strong></span></span></h2><p class=\"guide-markup\" data-start=\"1327\" data-end=\"1377\">To update your bank account, follow these steps:</p><ol class=\"guide-markup\" data-start=\"1379\" data-end=\"1634\">\n<li class=\"guide-markup\" data-start=\"1379\" data-end=\"1449\" data-list-item-id=\"ee9065c036ece7d28362f6a85a860c113\"><p class=\"guide-markup\" data-start=\"1382\" data-end=\"1449\"><strong class=\"guide-markup\" data-start=\"1382\" data-end=\"1414\">Use your registered email ID</strong> when updating your bank account.</p></li>\n<li class=\"guide-markup\" data-start=\"1450\" data-end=\"1634\" data-list-item-id=\"e8349d095341235a74c8ea0f0b455f04e\"><p class=\"guide-markup\" data-start=\"1453\" data-end=\"1634\"><strong class=\"guide-markup\" data-start=\"1453\" data-end=\"1480\">Fill out the form here:</strong><br>👉 <a class=\"guide-markup\" data-start=\"1486\" data-end=\"1632\" target=\"_new\" rel=\"noopener\" href=\"https://docs.google.com/forms/d/e/1FAIpQLSc9YiQ4H6JqRwt0bPAekdRlbFXxa8mVoZeTb0dD59cQJTpMsw/viewform\">Bank Account Update Form (Outside Pakistan)</a><span class=\"guide-markup\" aria-hidden=\"true\"><a class=\"guide-markup\"></a></span><a class=\"guide-markup\" data-start=\"1486\" data-end=\"1632\" target=\"_new\" rel=\"noopener\"></a></p></li>\n</ol><h3 class=\"guide-markup\" id=\"h_01K607B2SH32AC4JP5TXHQXDEQ\" data-start=\"1636\" data-end=\"1662\">Required Information</h3><p class=\"guide-markup\" data-start=\"1663\" data-end=\"1707\">When filling out the form, please provide:</p><ul class=\"guide-markup\" data-start=\"1708\" data-end=\"1854\">\n<li class=\"guide-markup\" data-start=\"1708\" data-end=\"1724\" data-list-item-id=\"ef4b5ebac34c1dfd91cbf89b9ac046b28\"><p class=\"guide-markup\" data-start=\"1710\" data-end=\"1724\">Account Name</p></li>\n<li class=\"guide-markup\" data-start=\"1725\" data-end=\"1745\" data-list-item-id=\"e19eb7fee8eeb894c17ed91b0ab3c4ffe\"><p class=\"guide-markup\" data-start=\"1727\" data-end=\"1745\">Account Currency</p></li>\n<li class=\"guide-markup\" data-start=\"1746\" data-end=\"1778\" data-list-item-id=\"e0a7ad0e97b9c078d51d08d0744c9b0f7\"><p class=\"guide-markup\" data-start=\"1748\" data-end=\"1778\">Business or Personal Account</p></li>\n<li class=\"guide-markup\" data-start=\"1779\" data-end=\"1797\" data-list-item-id=\"eddda95de8dda30e99ab22db053e10e91\"><p class=\"guide-markup\" data-start=\"1781\" data-end=\"1797\">Account Number</p></li>\n<li class=\"guide-markup\" data-start=\"1798\" data-end=\"1811\" data-list-item-id=\"e2064c0ca30559d15ef9f2d0c5647f802\"><p class=\"guide-markup\" data-start=\"1800\" data-end=\"1811\">IFSC Code/ ACHR/ Swift</p></li>\n<li class=\"guide-markup\" data-start=\"1812\" data-end=\"1823\" data-list-item-id=\"ed906dfb6d53d6593a6b3b95cf24e04ba\"><p class=\"guide-markup\" data-start=\"1814\" data-end=\"1823\">Address</p></li>\n<li class=\"guide-markup\" data-start=\"1824\" data-end=\"1835\" data-list-item-id=\"e82439f48769163f25f15da41e5aec094\"><p class=\"guide-markup\" data-start=\"1826\" data-end=\"1835\">Pincode</p></li>\n<li class=\"guide-markup\" data-start=\"1836\" data-end=\"1844\" data-list-item-id=\"e88786d631920f55a98d13f1c31d5862d\"><p class=\"guide-markup\" data-start=\"1838\" data-end=\"1844\">City</p></li>\n<li class=\"guide-markup\" data-start=\"1845\" data-end=\"1854\" data-list-item-id=\"e7242cfedaf402a39ca8003dd557bbc2d\"><p class=\"guide-markup\" data-start=\"1847\" data-end=\"1854\">State</p></li>\n</ul><hr class=\"guide-markup\"><h2 class=\"guide-markup\" style=\"color: #ffcc00;\" id=\"h_01K607B2SYCHA4DN074S3BQYEW\" data-start=\"2084\" data-end=\"2119\"><span style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">How to Update or change you Bank Account Details?</strong></span></span></h2><p class=\"guide-markup\" data-start=\"2121\" data-end=\"2183\">If you need to update your bank account again in the future:</p><ul class=\"guide-markup\" data-start=\"2184\" data-end=\"2441\">\n<li class=\"guide-markup\" data-start=\"2184\" data-end=\"2239\" data-list-item-id=\"e9770b7559a33ea9f776c97e371ba4c8a\"><p class=\"guide-markup\" data-start=\"2186\" data-end=\"2239\">Send us an email from your <strong class=\"guide-markup\" data-start=\"2213\" data-end=\"2236\">registered email ID</strong>.</p></li>\n<li class=\"guide-markup\" data-start=\"2240\" data-end=\"2364\" data-list-item-id=\"e89f2b014571fce0ebe3b6bef9e767061\">\n<p class=\"guide-markup\" data-start=\"2242\" data-end=\"2274\">Include the following details:</p>\n<ul class=\"guide-markup\" data-start=\"2277\" data-end=\"2364\">\n<li class=\"guide-markup\" data-start=\"2277\" data-end=\"2302\" data-list-item-id=\"ef50a1cb8c3c7c80d6b6b599bf68a424c\"><p class=\"guide-markup\" data-start=\"2279\" data-end=\"2302\">Reason for the update</p></li>\n<li class=\"guide-markup\" data-start=\"2305\" data-end=\"2333\" data-list-item-id=\"e3fb406105dd40b968fcf3a9688b6aa9a\"><p class=\"guide-markup\" data-start=\"2307\" data-end=\"2333\">Old bank account details</p></li>\n<li class=\"guide-markup\" data-start=\"2336\" data-end=\"2364\" data-list-item-id=\"e9a458efff3a67cafcba913c094f1652e\"><p class=\"guide-markup\" data-start=\"2338\" data-end=\"2364\">New bank account details</p></li>\n</ul>\n</li>\n<li class=\"guide-markup\" data-start=\"2365\" data-end=\"2441\" data-list-item-id=\"e1d518e2a27473c60c6484a1a14be6993\"><p class=\"guide-markup\" data-start=\"2367\" data-end=\"2441\">Our team will review and approve the request within <strong class=\"guide-markup\" data-start=\"2419\" data-end=\"2438\">2 business days.</strong></p></li>\n</ul><hr class=\"guide-markup\" data-start=\"2079\" data-end=\"2082\"><h3 class=\"guide-markup\" id=\"h_01K607B2STQT6QPY3WG3RCHSAJ\" data-start=\"1856\" data-end=\"1877\"><span class=\"wysiwyg-font-size-x-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Important Notes:</strong></span></span></h3><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"e50a8bdcc4352966edac3e16c58a82f48\"><p class=\"guide-markup\" data-start=\"60\" data-end=\"121\">Wallets or microfinance bank accounts are not accepted.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"ec547325e6959e53deff1ade4353ea49a\"><p class=\"guide-markup\" data-start=\"803\" data-end=\"848\">Business accounts of PKR currency are <strong class=\"guide-markup\" data-start=\"829\" data-end=\"845\">not accepted</strong>.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"e575559e98f46f7e8cf0158d65e3de8f3\"><p class=\"guide-markup\" data-start=\"851\" data-end=\"931\">Business accounts in GBP or USD will incur a <strong class=\"guide-markup\" data-start=\"896\" data-end=\"928\">$15 bank fee per transaction</strong>.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"e10a5da14a7e4ceb7a7c863dc033cec90\"><p class=\"guide-markup\" data-start=\"124\" data-end=\"258\"><strong class=\"guide-markup\" data-start=\"124\" data-end=\"196\">Once submitted, your bank account will be updated within 24–48 hours</strong>, and all future payments will be processed to that account.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"e5ea1a44fb3366f1f14ca2a742a6e63dc\"><p class=\"guide-markup\" data-start=\"261\" data-end=\"367\"><strong class=\"guide-markup\" data-start=\"261\" data-end=\"312\">A bank account can only be linked to one store.</strong> The same account cannot be used for multiple stores.</p></li>\n<li class=\"guide-markup\" data-list-item-id=\"ea21a91576bfd1aeda0a9da42ab7bfbd5\"><p class=\"guide-markup\" data-start=\"370\" data-end=\"514\"><strong class=\"guide-markup\" data-start=\"370\" data-end=\"451\">For privacy and security, submissions must be sent via your registered email.</strong> Any submissions from an unregistered email will be rejected.</p></li>\n</ul><hr class=\"guide-markup\"><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-x-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Frequently Asked Questions</strong></span></span></p><details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">1. What do I need before starting the onboarding process?</span>\n    </summary>\n    <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">A unique phone number &amp; email</li>\n      <li class=\"guide-markup\">CNIC (government-issued ID)</li>\n      <li class=\"guide-markup\">Bank account details (IBAN)</li>\n      <li class=\"guide-markup\">Product photos with correct size tags</li>\n    </ul>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">2. Can I use the same email/phone number for multiple shops?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      No. Each shop must have a unique phone number and email address.\n    </p>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">3. How do I sign up as a seller?</span>\n    </summary>\n    <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">Download the Fleek Seller App or visit joinfleek.com</li>\n      <li class=\"guide-markup\">Register using your unique phone number or email</li>\n    </ul>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">4. How do I create my seller profile?</span>\n    </summary>\n    <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">Add your store name and short description (BIO)</li>\n      <li class=\"guide-markup\">\n        Upload a profile photo or logo<br class=\"guide-markup\">\n        <em class=\"guide-markup\">(For updates later, contact Seller Support via WhatsApp: +447435853808)</em>\n      </li>\n    </ul>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">5. What happens if I enter incorrect bank details?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      Incorrect bank details may cause payout delays. Always double-check your\n      IBAN and account information before submission.\n    </p>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">6. When can I upload my first products?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      After creating your profile and submitting bank details, you can upload\n      your first products following the Product Listing Guidelines.\n    </p>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">7. How long does it take for my products to go live?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      Your profile and products undergo Fleek’s review and QC check.<br class=\"guide-markup\">\n      Once approved, your products will go live (usually within\n      <strong class=\"guide-markup\">24–72 hours</strong>, excluding weekends/holidays).\n    </p>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">8. Who should I contact if I face issues during onboarding?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      Reach out to Seller Support via WhatsApp: +447435853808 for help with\n      your profile, KYC, or product listings.\n    </p>\n  </details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42545986632091,"title":"Seller Payout Overview and Understanding","body":"<p class=\"guide-markup\" data-start=\"210\" data-end=\"452\">This guide is designed to help suppliers clearly understand how their payouts work on the Fleek platform. It walks you through everything you need to know — from where to access your payout details to how to read and interpret each section.</p><p class=\"guide-markup\" data-start=\"454\" data-end=\"475\">You’ll learn about:</p><ul class=\"guide-markup\" data-start=\"476\" data-end=\"891\">\n<li class=\"guide-markup\" data-start=\"476\" data-end=\"567\" data-list-item-id=\"eb561110f3e1ed37797e3d45cb50be9c3\"><p class=\"guide-markup\" data-start=\"478\" data-end=\"567\"><strong class=\"guide-markup\" data-start=\"478\" data-end=\"498\">Payout Overview:</strong> Understand the payout cycle and how Fleek processes your earnings.</p></li>\n<li class=\"guide-markup\" data-start=\"568\" data-end=\"686\" data-list-item-id=\"e4ccc4661da95b3b5b9f182e279cc3656\"><p class=\"guide-markup\" data-start=\"570\" data-end=\"686\"><strong class=\"guide-markup\" data-start=\"570\" data-end=\"598\">How to Read Your Payout:</strong> Learn how each component — such as base price, shipping, and commissions — is displayed.</p></li>\n<li class=\"guide-markup\" data-start=\"687\" data-end=\"780\" data-list-item-id=\"e1ac5b6db6df0e75b1504f88c495dd8fa\"><p class=\"guide-markup\" data-start=\"689\" data-end=\"780\"><strong class=\"guide-markup\" data-start=\"689\" data-end=\"714\">Order-wise Breakdown:</strong> See how every completed order contributes to your total payout.</p></li>\n<li class=\"guide-markup\" data-start=\"781\" data-end=\"891\" data-list-item-id=\"edeb7fee99bf0212d7ebf5a0bc578916e\"><p class=\"guide-markup\" data-start=\"783\" data-end=\"891\"><strong class=\"guide-markup\" data-start=\"783\" data-end=\"809\">Where to View Payouts:</strong> Know exactly where and how to access your payout details within the Vendor App.</p></li>\n</ul><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K8091T2WNPEEXFDEBH4TH0H2\"><strong class=\"guide-markup\">Understand the Payout<span class=\"guide-markup\" data-canva-clipboard=\"\"></span>:</strong></h2><p class=\"guide-markup\">On this page, you’ll find an easy-to-read summary of your payout. It shows your total payout balance and the amounts at the order level, helping you quickly understand how much you’ve earned in this cycle.</p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"e746d4ccb0ee742cb8e7ccbae70f112b2\">Supplier: Your registered vendor handle</li>\n<li class=\"guide-markup\" data-list-item-id=\"edf865873660febcad5df8f7e20441900\">Payout Date: Scheduled payout cycle date</li>\n<li class=\"guide-markup\" data-list-item-id=\"eb513f7a0f6ec91c2b0b11cf768661e13\">Payout Balance: Total balance included in your weekly payout</li>\n<li class=\"guide-markup\" data-list-item-id=\"ecfe85dfba20d47c1ffba70720d842dc1\">Summary: Overview of all orders included in your payout</li>\n</ul><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 858/1023;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42545986617755\" width=\"858\" height=\"1023\"></figure><hr><h2 class=\"guide-markup\" id=\"h_01K85VENKA67F57ZPNMGCPPV78\"><strong class=\"guide-markup\">Order Level Details:</strong></h2><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 702/825;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42545986619163\" width=\"702\" height=\"825\"></figure><hr><h2 class=\"guide-markup\" id=\"h_01K85RK7FHM3AST9PCC2JTFMQ3\"><strong class=\"guide-markup\">Order Wise Breakdown:</strong></h2><p class=\"guide-markup\">Lets understand how payout breakdown works,</p><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-list-item-id=\"e12b26e38eb8588f53903e59b83ad0807\">Vendor Base Price: Price set by the supplier before discounts</li>\n<li class=\"guide-markup\" data-list-item-id=\"e10bcae74da52eb8702460131a993b72f\">Discount: Reduction offered to the buyer</li>\n<li class=\"guide-markup\" data-list-item-id=\"e23a6e4a27a775a93c6f26c18de34d934\">Total Base Price: Final price after discount</li>\n<li class=\"guide-markup\" data-list-item-id=\"e89dccd28a427b8029568e0098290c856\">Fleek Commission: Fleek’s fee for the sale</li>\n<li class=\"guide-markup\" data-list-item-id=\"e35e4ad03e991e9ff68f0f78e7bb760ce\">Refund: Returned amount for cancelled orders</li>\n<li class=\"guide-markup\" data-list-item-id=\"e7d6751756e7961dd387a00cdb66b77b3\">Inclusive Shipping: Shipping included in product price</li>\n<li class=\"guide-markup\" data-list-item-id=\"e28f3cb64d85ad6533a33cf7a6ceab46d\">Shipping Charges: Delivery fee based on location</li>\n</ul><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1056/338;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42545986623131\" width=\"1056\" height=\"338\"></figure><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K85VKTNVA0QRACS1D1517N98\"><strong class=\"guide-markup\">Where can I see my payout?</strong></h2><p class=\"guide-markup\">Payouts are shared with you on a weekly basis through the Vendor App. You can view your payout details directly in the chat.</p><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1208/804;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42545996112667\" width=\"1208\" height=\"804\"></figure><hr class=\"guide-markup\"><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-x-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Frequently Asked Questions</strong></span></span></p><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">1. What is a Payout in Fleek?</span>\n  </summary>\n  <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    A payout in Fleek is your weekly earnings summary for all eligible orders.<br class=\"guide-markup\">\n    It shows the total amount you’ve earned after deducting Fleek’s commission,\n    transaction fees, and any penalties or refunds.<br class=\"guide-markup\">\n    In simple terms, it’s your final weekly payment — showing exactly what you’ve\n    earned and what will be transferred to your registered bank account.\n  </ul>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">2. Why might my payout be delayed?</span>\n  </summary>\n  <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    Payouts are typically processed every Monday. However, delays can occur\n    due to gazetted holidays, bank verification checks, or system-related\n    issues.<br class=\"guide-markup\">\n    If your payout hasn’t been received within the expected timeline,\n    please reach out to Seller Support for assistance.\n\n  </ul>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">3. How is my payout amount calculated?</span>\n  </summary>\n  <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      Your payout is calculated based on your completed orders, minus any applicable deductions.<br class=\"guide-markup\">\n      You can refer to the attached file to see exactly how Fleek calculates payouts step by step.\n  </ul>\n</details>\n<details style=\"style;\" class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">4. How can I see a detailed breakdown of my payout?</span>\n  </summary>\n  <div style=\"color: #333; margin-top: 8px; margin-left: 22px;\" class=\"guide-markup\">\n    <p class=\"guide-markup\">\n      Your payout statement includes a complete order-wise breakdown —\n      showing:\n    </p>\n    <ul style=\"margin-top: 4px; margin-bottom: 8px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">Item prices</li>\n      <li class=\"guide-markup\">Commission deductions</li>\n      <li class=\"guide-markup\">Shipping charges</li>\n      <li class=\"guide-markup\">Any other adjustments</li>\n    </ul>\n    <p class=\"guide-markup\">\n      This helps you understand exactly how your total payout was calculated.\n    </p>\n  </div>\n</details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42545323162139,"title":"Product Weight - Understanding and Calculation","body":"<p class=\"guide-markup\" data-start=\"195\" data-end=\"418\">Shipping charges are directly influenced by a product’s <strong class=\"guide-markup\" data-start=\"251\" data-end=\"261\">weight</strong>. Correctly determining the weight ensures accurate shipping calculation, prevents overcharging or undercharging buyers, and avoids order fulfillment issues.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7TENN76D5EM8MX52YRC7G0W\" data-start=\"425\" data-end=\"459\"><strong class=\"guide-markup\" data-start=\"429\" data-end=\"459\">1. What is Product Weight?</strong></h3><p class=\"guide-markup\" data-start=\"101\" data-end=\"280\">Product weight refers to the measurement of a product used to determine shipping charges. It is a key factor in calculating the cost of delivery and can be measured in two ways:</p><ul class=\"guide-markup\" data-start=\"282\" data-end=\"523\">\n<li class=\"guide-markup ck-list-marker-bold\" data-start=\"282\" data-end=\"376\" data-list-item-id=\"e023d7015d1389dfaa67cb6f3ec34836c\"><p class=\"guide-markup\" data-start=\"284\" data-end=\"376\"><strong class=\"guide-markup\" data-start=\"284\" data-end=\"299\">Actual Weight</strong></p></li>\n<li class=\"guide-markup ck-list-marker-bold\" data-start=\"377\" data-end=\"523\" data-list-item-id=\"e11014254f442635f8dd8cd9258fed570\"><p class=\"guide-markup\" data-start=\"379\" data-end=\"523\"><strong class=\"guide-markup\" data-start=\"379\" data-end=\"417\">Dimensional Weight</strong></p></li>\n</ul><p class=\"guide-markup\" data-start=\"525\" data-end=\"635\" data-is-last-node=\"\" data-is-only-node=\"\">Accurate weight ensures buyers are charged correctly and helps prevent shipping discrepancies or order delays.</p><p class=\"guide-markup\" data-start=\"798\" data-end=\"885\">Shipping carriers charge based on the <strong class=\"guide-markup\" data-start=\"836\" data-end=\"882\">higher of Actual Weight or Dimensional Weight</strong>.</p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7V177KWKQPJFPW9EVJHP8J9\"><strong class=\"guide-markup\" data-start=\"97\" data-end=\"156\">2. Understanding Actual Weight and Dimensional Weight:</strong></h2><h3 class=\"guide-markup\" id=\"h_01K7V18YECQ108WKJ9WNJWFKKB\">\n<strong class=\"guide-markup\">Actual Weight</strong>:</h3><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 6000/1922;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42545323159323\" width=\"6000\" height=\"1922\"></figure><h3 class=\"guide-markup\" id=\"h_01K7V1BW8Z385AKH055TGZDE35\">\n<strong class=\"guide-markup\">Dimensional Weight</strong>:</h3><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1920/800;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42545323159963\" alt=\"Net Weight The actual weight of the product alone, measured using a weighing machine. (4).jpg\" width=\"1920\" height=\"800\"></figure><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7VCRDJ6TNYPWQ847SSNR0QJ\" data-start=\"1572\" data-end=\"1610\"><strong class=\"guide-markup\" data-start=\"1576\" data-end=\"1610\">3. Why Accurate Weight Matters</strong></h3><ul class=\"guide-markup\" data-start=\"1612\" data-end=\"1896\">\n<li class=\"guide-markup\" data-start=\"1612\" data-end=\"1669\" data-list-item-id=\"ec669876ea4f75b104e00a17ceac28e78\"><p class=\"guide-markup\" data-start=\"1614\" data-end=\"1669\">Ensures <strong class=\"guide-markup\" data-start=\"1622\" data-end=\"1654\">buyers are charged correctly</strong> at checkout.</p></li>\n<li class=\"guide-markup\" data-start=\"1670\" data-end=\"1739\" data-list-item-id=\"e453129fdcb2c1b9fc739ec8a8f85871e\"><p class=\"guide-markup\" data-start=\"1672\" data-end=\"1739\">Prevents <strong class=\"guide-markup\" data-start=\"1681\" data-end=\"1712\">discrepancies with couriers</strong> and extra charges from your payout later.</p></li>\n<li class=\"guide-markup\" data-start=\"1740\" data-end=\"1807\" data-list-item-id=\"e3124b610ab3c799c409279d3368d454a\"><p class=\"guide-markup\" data-start=\"1742\" data-end=\"1807\">Helps Fleek or sellers provide <strong class=\"guide-markup\" data-start=\"1773\" data-end=\"1804\">accurate shipping estimates</strong>.</p></li>\n</ul><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7VCTN442J0W5VQKZJ48HAY3\" data-start=\"1903\" data-end=\"1950\"><strong class=\"guide-markup\" data-start=\"1907\" data-end=\"1950\">4. Tips for Managing Weight Efficiently</strong></h3><ul class=\"guide-markup\" data-start=\"1952\" data-end=\"2276\">\n<li class=\"guide-markup\" data-start=\"1952\" data-end=\"2033\" data-list-item-id=\"e05c76a15edcecef98f5cc961671ad9c6\"><p class=\"guide-markup\" data-start=\"1954\" data-end=\"2033\">Maintain a <strong class=\"guide-markup\" data-start=\"1965\" data-end=\"1985\">weighing station</strong> for all products to standardize measurements.</p></li>\n<li class=\"guide-markup\" data-start=\"2034\" data-end=\"2105\" data-list-item-id=\"e9ca6454a2829991a613c919aff6cc67a\"><p class=\"guide-markup\" data-start=\"2036\" data-end=\"2105\">Keep a <strong class=\"guide-markup\" data-start=\"2043\" data-end=\"2069\">weight reference sheet</strong> for common products to save time.</p></li>\n<li class=\"guide-markup\" data-start=\"2034\" data-end=\"2105\" data-list-item-id=\"e25ad4af213f849cd3900491bfa4968b3\"><p class=\"guide-markup\" data-start=\"2036\" data-end=\"2105\">Follow the <a class=\"guide-markup\"><strong class=\"guide-markup\">Packaging Guidelines</strong></a> to reduce dimensional weight without compromising product safety</p></li>\n</ul><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7VDCVEMK4CRD1W0WX0J0JMD\"><strong class=\"guide-markup\" data-start=\"1907\" data-end=\"1950\">Frequently Asked Questions</strong></h2><details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. What is the difference between Net Weight and Dimensional Weight?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> <strong class=\"guide-markup\">Net Weight</strong> is the actual weight of the product measured on a scale. <br class=\"guide-markup\"><br class=\"guide-markup\"> <strong class=\"guide-markup\">Dimensional Weight (Gross Weight)</strong> considers the product’s size and packaging volume. Couriers charge based on whichever weight — actual or dimensional — is higher. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. Which weight should I enter for shipping calculation?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> If you are a <strong class=\"guide-markup\">Self-Shipped Seller</strong>, calculate both <strong class=\"guide-markup\">Net</strong> and <strong class=\"guide-markup\">Dimensional Weight</strong> and enter the higher one, as courier charges are based on the greater of the two. <br class=\"guide-markup\"><br class=\"guide-markup\"> For <strong class=\"guide-markup\">Fleek-Managed Shipping</strong>, you only need to enter the <strong class=\"guide-markup\">actual (Net) Weight</strong> of your products. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. Why is accurate weight important?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> Accurate weight helps ensure: <ul style=\"margin-top: 4px;\" class=\"guide-markup\"> <li class=\"guide-markup\">Correct shipping charges</li> <li class=\"guide-markup\">No additional courier fees</li> <li class=\"guide-markup\">Faster order processing and fewer delays</li> <li class=\"guide-markup\">A smoother and more reliable buyer experience</li> </ul> </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. How can I reduce dimensional weight?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> Use compact and well-fitted packaging, fold items neatly, and minimize empty space inside boxes. Proper packing reduces the overall package size, helping lower the dimensional weight. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. Can incorrect weight affect my order or payout?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> Yes. Entering incorrect weight can lead to: <ul style=\"margin-top: 4px;\" class=\"guide-markup\"> <li class=\"guide-markup\">Extra courier charges</li> <li class=\"guide-markup\">Order delays or disputes</li> <li class=\"guide-markup\">Impact on your <strong class=\"guide-markup\">Seller Performance Score</strong>\n</li> </ul> Always double-check your measurements before finalizing listings. </div> </details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42545133218075,"title":"Order Cancellation Policy","body":"<p class=\"guide-markup\" data-start=\"222\" data-end=\"504\">At <strong class=\"guide-markup\" data-start=\"225\" data-end=\"234\">Fleek</strong>, we aim to provide a smooth and reliable experience for both sellers and buyers. However, situations may arise where an order needs to be cancelled. This policy defines the conditions, reasons, and impacts of order cancellations on your performance metrics and payouts.</p><hr class=\"guide-markup\" data-start=\"506\" data-end=\"509\"><h3 class=\"guide-markup\" id=\"h_01K7T3YVDAB31J3T0CJ5V2JDH0\" data-start=\"511\" data-end=\"552\"><strong class=\"guide-markup\" data-start=\"515\" data-end=\"552\">1. What is an Order Cancellation?</strong></h3><p class=\"guide-markup\" data-start=\"554\" data-end=\"809\">An order cancellation occurs when an order is stopped during its journey. Cancellations can be initiated either by the <strong class=\"guide-markup\" data-start=\"702\" data-end=\"712\">seller</strong>, <strong class=\"guide-markup\" data-start=\"714\" data-end=\"723\">buyer</strong>, or <strong class=\"guide-markup\" data-start=\"728\" data-end=\"737\">Fleek</strong> (in specific cases, such as policy violations or stock unavailability).</p><hr class=\"guide-markup\" data-start=\"811\" data-end=\"814\"><h3 class=\"guide-markup\" id=\"h_01K7T3YVDCPXK679V6GPEZQS88\" data-start=\"816\" data-end=\"849\"><strong class=\"guide-markup\" data-start=\"820\" data-end=\"849\">2. Types of Cancellations</strong></h3><figure style=\"width: 100%;\" class=\"wysiwyg-table guide-markup\"><table style=\"border-style: solid; border-width: 1px; margin-left: 0px; margin-right: auto;\" class=\"guide-markup wysiwyg-table-resized\">\n<colgroup class=\"guide-markup\">\n<col style=\"width: 26%;\" class=\"guide-markup\">\n<col style=\"width: 11%;\" class=\"guide-markup\">\n<col style=\"width: 63%;\" class=\"guide-markup\">\n</colgroup>\n<tbody class=\"guide-markup\">\n<tr class=\"guide-markup\">\n<td style=\"text-align: left;\" class=\"guide-markup\" data-start=\"851\" data-end=\"862\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"853\" data-end=\"861\">Type</strong></td>\n<td style=\"text-align: left;\" class=\"guide-markup\" data-start=\"862\" data-end=\"880\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"864\" data-end=\"879\">Party</strong></td>\n<td style=\"text-align: left;\" class=\"guide-markup\" data-start=\"880\" data-end=\"902\" data-col-size=\"md\"><strong class=\"guide-markup\" data-start=\"882\" data-end=\"900\">Common Reasons</strong></td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\" data-start=\"957\" data-end=\"979\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"959\" data-end=\"978\">Buyer-Initiated</strong></td>\n<td class=\"guide-markup\" data-col-size=\"sm\" data-start=\"979\" data-end=\"987\">Buyer</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"987\" data-end=\"1035\">Changes mind, Incorrect Address, etc</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\" data-start=\"1036\" data-end=\"1059\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"1038\" data-end=\"1058\">Seller-Initiated</strong></td>\n<td class=\"guide-markup\" data-col-size=\"sm\" data-start=\"1059\" data-end=\"1068\">Seller</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1068\" data-end=\"1142\">Out of stock, damaged item, incorrect pricing, or Quality Check Issue</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\" data-start=\"1143\" data-end=\"1176\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"1145\" data-end=\"1175\">Platform-Initiated (Fleek)</strong></td>\n<td class=\"guide-markup\" data-col-size=\"sm\" data-start=\"1176\" data-end=\"1184\">Fleek</td>\n<td class=\"guide-markup\" data-col-size=\"md\" data-start=\"1184\" data-end=\"1247\">Policy Issues, Risk and Platform Security</td>\n</tr>\n</tbody>\n</table></figure><hr class=\"guide-markup\" data-start=\"1525\" data-end=\"1528\"><h3 class=\"guide-markup\" id=\"h_01K7T3YVDPE3D31RZTTGAB499M\" data-start=\"1530\" data-end=\"1569\"><strong class=\"guide-markup\" data-start=\"1534\" data-end=\"1569\">3. Impact on Seller Performance</strong></h3><p class=\"guide-markup\" data-start=\"1571\" data-end=\"1789\">Seller-initiated and Quality Issues related cancellations may affect your <strong class=\"guide-markup\" data-start=\"1625\" data-end=\"1645\">Fulfillment Rate</strong>, <strong class=\"guide-markup\" data-start=\"1647\" data-end=\"1663\">Seller Score</strong>, and <strong class=\"guide-markup\" data-start=\"1669\" data-end=\"1691\">overall visibility</strong> on Fleek. Repeated cancellations may lead to penalties or temporary restrictions on your account.</p><blockquote class=\"guide-markup\" data-start=\"1791\" data-end=\"1889\"><p class=\"guide-markup\" data-start=\"1793\" data-end=\"1889\"><strong class=\"guide-markup\" data-start=\"1793\" data-end=\"1801\">Tip:</strong> Always keep your inventory updated to avoid cancellations due to out-of-stock products.</p></blockquote><hr class=\"guide-markup\" data-start=\"1891\" data-end=\"1894\"><h3 class=\"guide-markup\" id=\"h_01K7T3YVDRT4CWQ2KP5ZVYZMAR\" data-start=\"1896\" data-end=\"1926\"><strong class=\"guide-markup\" data-start=\"1900\" data-end=\"1926\">4. Fees and Deductions</strong></h3><ul class=\"guide-markup\" data-start=\"1928\" data-end=\"2263\">\n<li class=\"guide-markup\" data-start=\"1928\" data-end=\"2013\" data-list-item-id=\"ef06f485fb2f329ec71a283329c9f550b\"><p class=\"guide-markup\" data-start=\"1930\" data-end=\"2013\"><strong class=\"guide-markup\" data-start=\"1930\" data-end=\"1964\">Buyer-Initiated Cancellations:</strong> No commission or fee is charged to the seller</p></li>\n<li class=\"guide-markup\" data-start=\"2014\" data-end=\"2139\" data-list-item-id=\"ebb4e52e25bfbc9362c6ffad1555b7198\"><p class=\"guide-markup\" data-start=\"2016\" data-end=\"2139\"><strong class=\"guide-markup\" data-start=\"2016\" data-end=\"2051\">Seller-Initiated Cancellations:</strong> A <strong class=\"guide-markup\" data-start=\"2091\" data-end=\"2111\">cancellation fee</strong> of 2.5% on your order base price will be applied</p></li>\n<li class=\"guide-markup\" data-start=\"2014\" data-end=\"2139\" data-list-item-id=\"ea04d0932aacc3bc5241782ad859ee522\"><p class=\"guide-markup\" data-start=\"2016\" data-end=\"2139\"><strong class=\"guide-markup\">Quality Check Cancellation: </strong>Order cancelled during QC will be consider for cancellation fee.</p></li>\n<li class=\"guide-markup\" data-start=\"2140\" data-end=\"2263\" data-list-item-id=\"e77c000c09a93e1b8080e8bbd10d8af4f\"><p class=\"guide-markup\" data-start=\"2142\" data-end=\"2263\"><strong class=\"guide-markup\" data-start=\"2142\" data-end=\"2179\">Platform-Initiated Cancellations:</strong> No commission of fee is charged to the seller</p></li>\n</ul><hr class=\"guide-markup\" data-start=\"2265\" data-end=\"2268\"><h3 class=\"guide-markup\" id=\"h_01K7T3YVDTRRF7ZFSN27JX723F\" data-start=\"2270\" data-end=\"2312\"><strong class=\"guide-markup\" data-start=\"2274\" data-end=\"2312\">5. How to Cancel an Order (Seller Initiated)</strong></h3><p class=\"guide-markup\" data-start=\"2314\" data-end=\"2344\">If you must cancel an order:</p><ol class=\"guide-markup\" data-start=\"2345\" data-end=\"2517\">\n<li class=\"guide-markup\" data-start=\"2345\" data-end=\"2402\" data-list-item-id=\"e29888579ed654a3102faa24ca3008754\"><p class=\"guide-markup\" data-start=\"2348\" data-end=\"2402\">Go to the <strong class=\"guide-markup\" data-start=\"2358\" data-end=\"2368\">Orders</strong> section in your <strong class=\"guide-markup\" data-start=\"2385\" data-end=\"2399\">Vendor App</strong>.</p></li>\n<li class=\"guide-markup\" data-start=\"2403\" data-end=\"2434\" data-list-item-id=\"e3377e30a8210df61d0e543ee88b049cc\"><p class=\"guide-markup\" data-start=\"2406\" data-end=\"2434\">Select the relevant order.</p></li>\n<li class=\"guide-markup\" data-start=\"2435\" data-end=\"2487\" data-list-item-id=\"e8e28198a8caf78b0d41f10229ec90d13\"><p class=\"guide-markup\" data-start=\"2438\" data-end=\"2487\">Tap <strong class=\"guide-markup\" data-start=\"2442\" data-end=\"2458\">Cancel Order</strong>.</p></li>\n<li class=\"guide-markup\" data-start=\"2488\" data-end=\"2517\" data-list-item-id=\"e5a3286bfe26f06df78fd79553d103341\"><p class=\"guide-markup\" data-start=\"2491\" data-end=\"2517\">Confirm your cancellation.</p></li>\n</ol><hr class=\"guide-markup\" data-start=\"2644\" data-end=\"2647\"><h3 class=\"guide-markup\" id=\"h_01K7T3YVDXJJHCHTTJN02938MX\" data-start=\"2649\" data-end=\"2688\"><strong class=\"guide-markup\" data-start=\"2653\" data-end=\"2688\">6. Avoiding Order Cancellations</strong></h3><ul class=\"guide-markup\" data-start=\"2690\" data-end=\"2882\">\n<li class=\"guide-markup\" data-start=\"2690\" data-end=\"2732\" data-list-item-id=\"e496bf6df5ae76531c100777c030db49a\"><p class=\"guide-markup\" data-start=\"2692\" data-end=\"2732\">Keep your stock and prices up to date.</p></li>\n<li class=\"guide-markup\" data-start=\"2733\" data-end=\"2770\" data-list-item-id=\"ed810ecbe7ff4fe425ecf3715c08e91a6\"><p class=\"guide-markup\" data-start=\"2735\" data-end=\"2770\">Regularly monitor your inventory.</p></li>\n<li class=\"guide-markup\" data-start=\"2828\" data-end=\"2882\" data-list-item-id=\"ec3064ec67c92ab4c3f1d3b3ffe5367a4\"><p class=\"guide-markup\" data-start=\"2830\" data-end=\"2882\">Maintain quality and accuracy in product listings to avoid QC hold cancellations.</p></li>\n</ul><hr class=\"guide-markup\" data-start=\"2884\" data-end=\"2887\"><h3 class=\"guide-markup\" id=\"h_01K7T3YVDZW28WNJ8EEJFPBM4K\" data-start=\"2889\" data-end=\"2910\"><strong class=\"guide-markup\" data-start=\"2893\" data-end=\"2910\">7. Need Help?</strong></h3><p class=\"guide-markup\" data-start=\"2912\" data-end=\"3065\">If you believe an order was cancelled incorrectly or a penalty was applied in error, please contact <strong class=\"guide-markup\" data-start=\"3012\" data-end=\"3030\">Seller Support</strong> through your <strong class=\"guide-markup\" data-start=\"3044\" data-end=\"3064\">Fleek Vendor App</strong>.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7T56XMGD0426GPNMDXX57JE\" data-start=\"2649\" data-end=\"2688\"><strong class=\"guide-markup\" data-start=\"147\" data-end=\"188\">Frequently Asked Questions:</strong></h3><details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. What should I do if I can’t fulfill an order due to stock issues?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> If you’re unable to fulfill an order due to stock issues, contact the buyer through <strong class=\"guide-markup\">Fleek Chat</strong> and offer possible resolutions such as: <ul style=\"margin-top: 4px;\" class=\"guide-markup\"> <li class=\"guide-markup\">Offering an alternate product (replacement)</li> <li class=\"guide-markup\">Providing a discount</li> </ul> Please note that <strong class=\"guide-markup\">buyer alignment is mandatory</strong> before proceeding with any alternate arrangement. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. How can I prevent cancellations in the future?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> To reduce cancellations, always keep your listings accurate. Regularly update stock availability, pricing, and product images to reflect the actual product you are offering. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. What if I was charged a cancellation fee by mistake?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> If you believe a cancellation fee was applied incorrectly, contact <strong class=\"guide-markup\">Seller Support</strong> via your <strong class=\"guide-markup\">Fleek Vendor App</strong> and share the relevant order details. The team will review and resolve the issue. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. What happens if I mistakenly cancelled the order?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> If you cancelled an order by mistake, reach out to <strong class=\"guide-markup\">Seller Support</strong> through your <strong class=\"guide-markup\">Fleek Vendor App</strong> with the order details. The support team will review and assist in resolving the issue. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. Can I cancel an order if the buyer’s address seems invalid?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> If the buyer’s address appears incomplete or incorrect, contact the buyer through <strong class=\"guide-markup\">Fleek Chat</strong> to confirm the correct details. If the issue remains unresolved, <strong class=\"guide-markup\">escalate the case to Seller Support</strong> instead of cancelling the order directly. </div> </details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42544762846107,"title":"Shipping Policy & Calculation Guide","body":"<p class=\"guide-markup\" data-start=\"234\" data-end=\"412\">Shipping cost is an important factor in order management. This guide explains how shipping charges are calculated, what affects them, and how sellers can manage them effectively. </p><p class=\"guide-markup\" data-start=\"234\" data-end=\"412\">Fleek manages shipping in specific regions, and suppliers from all other regions manage their own packaging and shipping. </p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7TCSY5HK1PVNEKXVY3N4801\"><strong class=\"guide-markup\" data-start=\"423\" data-end=\"465\">Understanding Shipping Charges</strong></h2><p class=\"guide-markup\" data-start=\"469\" data-end=\"561\">Shipping charges depend on <strong class=\"guide-markup\" data-start=\"496\" data-end=\"558\">weight, dimensions, delivery location, and shipping method</strong></p><h3 class=\"guide-markup\" id=\"h_01K7TDDJ8T6BP6754G1XSMZAMM\" data-start=\"436\" data-end=\"478\"><strong class=\"guide-markup\" data-start=\"440\" data-end=\"478\">1. Shipping for Exact/Representative Products</strong></h3><ul class=\"guide-markup\" data-start=\"480\" data-end=\"807\">\n<li class=\"guide-markup\" data-start=\"480\" data-end=\"592\" data-list-item-id=\"ed36c8053c7e9abfe58c9a3db537fbcb8\"><p class=\"guide-markup\" data-start=\"482\" data-end=\"592\">For Exact/Rep products, Fleek automatically calculates the shipping charges based on our estimation.</p></li>\n<li class=\"guide-markup\" data-start=\"593\" data-end=\"674\" data-list-item-id=\"eda0bd22a51b635d587857dc7579cb578\"><p class=\"guide-markup\" data-start=\"595\" data-end=\"674\">The calculated shipping is directly collected from the buyer at checkout.</p></li>\n<li class=\"guide-markup\" data-start=\"593\" data-end=\"674\" data-list-item-id=\"e2be91f6726330c859c57cf0320b4d516\"><p class=\"guide-markup\" data-start=\"595\" data-end=\"674\">You need to choose the right category of your products.</p></li>\n<li class=\"guide-markup\" data-start=\"675\" data-end=\"807\" data-list-item-id=\"e5f12373cb776b7d79f87ad45f51ac788\"><p class=\"guide-markup\" data-start=\"677\" data-end=\"807\">No impact on the seller’s account or performance — sellers do not need to worry about shipping calculation for these products.</p></li>\n</ul><h4 class=\"guide-markup\" id=\"h_01K7TDKTP9AZAWJMQB4S9SKAZZ\"><strong class=\"guide-markup\" data-start=\"454\" data-end=\"486\">Note for Self-Shipped Model:</strong></h4><ul class=\"guide-markup\" data-start=\"489\" data-end=\"625\">\n<li class=\"guide-markup\" data-start=\"489\" data-end=\"625\" data-list-item-id=\"eacf83a2a58b63c38071bfb8cf1a19ae4\"><p class=\"guide-markup\" data-start=\"491\" data-end=\"625\">Sellers need to add the estimated shipping cost to the product’s base price when listing, so buyers see the total price upfront.</p></li>\n<li class=\"guide-markup\" data-start=\"489\" data-end=\"625\" data-list-item-id=\"e35566254f1dad1e651cf26ed9ae69842\"><p class=\"guide-markup\" data-start=\"491\" data-end=\"625\">Incorrect estimation may impact their overall product price and net payment.</p></li>\n</ul><h3 class=\"guide-markup\" id=\"h_01K7TDDJ91AXFJNXQKDWTNGM47\" data-start=\"814\" data-end=\"862\"><strong class=\"guide-markup\" data-start=\"818\" data-end=\"862\">2. Shipping for Custom/Handpick Products</strong></h3><p class=\"guide-markup\" data-start=\"864\" data-end=\"992\">For Custom/Handpick products, the seller is responsible for calculating the shipping charges. You can do this in two ways:</p><p class=\"guide-markup\" data-start=\"994\" data-end=\"1022\"><strong class=\"guide-markup\" data-start=\"994\" data-end=\"1020\">a) Manual Calculation: Your own estimation</strong></p><ul class=\"guide-markup\" data-start=\"1023\" data-end=\"1195\">\n<li class=\"guide-markup\" data-start=\"1023\" data-end=\"1111\" data-list-item-id=\"ec3781958021ba80daf3a395ca7920200\"><p class=\"guide-markup\" data-start=\"1025\" data-end=\"1111\">Calculate shipping costs based on courier charges, packaging, and delivery location.</p></li>\n<li class=\"guide-markup\" data-start=\"1112\" data-end=\"1195\" data-list-item-id=\"e0a64e28e14dc863f3357989f7d2494f4\"><p class=\"guide-markup\" data-start=\"1114\" data-end=\"1195\">Include these charges along with your product’s base price when listing the item.</p></li>\n</ul><p class=\"guide-markup\" data-start=\"1197\" data-end=\"1232\"><strong class=\"guide-markup\" data-start=\"1197\" data-end=\"1230\">b) Fleek Shipping Calculator:</strong></p><ul class=\"guide-markup\" data-start=\"1233\" data-end=\"1402\">\n<li class=\"guide-markup\" data-start=\"1233\" data-end=\"1289\" data-list-item-id=\"e394c61785926f26030174fba852eee10\"><p class=\"guide-markup\" data-start=\"1235\" data-end=\"1289\">Use Fleek’s calculator to estimate shipping charges.</p></li>\n<li class=\"guide-markup\" data-start=\"1290\" data-end=\"1402\" data-list-item-id=\"efa13aec6d2bd3437f05569ca6b0b6c30\"><p class=\"guide-markup\" data-start=\"1292\" data-end=\"1402\">Ensure the correct product category, weight, and dimensions are selected to get an accurate calculation.</p></li>\n</ul><blockquote class=\"guide-markup\" data-start=\"1404\" data-end=\"1506\"><p class=\"guide-markup\" data-start=\"1406\" data-end=\"1506\"><strong class=\"guide-markup\" data-start=\"1406\" data-end=\"1414\">Tip:</strong> Accurate shipping charges help prevent losses and provide a seamless experience for buyers.</p></blockquote><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7TDX3X27QYQX1T5HG92F6CQ\" data-start=\"73\" data-end=\"113\"><strong class=\"guide-markup\" data-start=\"76\" data-end=\"113\">How to Calculate Shipping Charges:</strong></h2><p class=\"guide-markup\" data-start=\"115\" data-end=\"268\">Accurate shipping calculation ensures buyers are charged correctly and helps prevent losses for sellers. Follow these steps based on your product type.</p><p class=\"guide-markup\" data-start=\"115\" data-end=\"268\">Fleek provides you two solutions to calculate the shipping charges for products.</p><h4 class=\"guide-markup\" id=\"h_01K7YMSS62EVH24M2B402VM1GF\"><strong class=\"guide-markup\">Shipping Calculator: </strong></h4><p class=\"guide-markup\" data-start=\"94\" data-end=\"325\">If you’d like to estimate shipping costs before listing a product or finalizing a deal, you can easily access the <strong class=\"guide-markup\" data-start=\"238\" data-end=\"261\">Shipping Calculator</strong> in your <strong class=\"guide-markup\" data-start=\"270\" data-end=\"292\">Vendor Application</strong> under the <strong class=\"guide-markup\" data-start=\"303\" data-end=\"314\" data-is-only-node=\"\">Profile</strong> section.</p><figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 1920/1080;\" src=\"https://support.joinfleek.com/hc/article_attachments/42544762829723\" width=\"1920\" height=\"1080\"></figure><h4 class=\"guide-markup\" id=\"h_01K7WNVZ18HD9YTZYW48NEPT2C\"><strong class=\"guide-markup\">Custom Handpick Shipping Calculator: </strong></h4><p class=\"guide-markup\" data-start=\"51\" data-end=\"272\">Suppliers can easily estimate shipping costs for <strong class=\"guide-markup\" data-start=\"130\" data-end=\"158\">Custom Handpick products</strong> using the built-in calculator available in the <strong class=\"guide-markup\" data-start=\"206\" data-end=\"238\">Custom Handpick listing flow</strong> — just follow two simple steps.</p><figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 1920/1080;\" src=\"https://support.joinfleek.com/hc/article_attachments/42544762832283\" width=\"1920\" height=\"1080\"></figure><figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 1920/1080;\" src=\"https://support.joinfleek.com/hc/article_attachments/42544762835995\" width=\"1920\" height=\"1080\"></figure><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"da3b90b0-79ef-4131-b3ef-a3b6c444769f\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"132\" data-is-last-node=\"\" data-is-only-node=\"\">If you are a ROW supplier (operating under the Self-Shipped Model), you must include the shipping cost in your product’s base price.</p>\n<p class=\"guide-markup\" data-start=\"274\" data-end=\"478\">To learn more about how custom handpick listing flow works, please click <a class=\"guide-markup\">here</a></p>\n</div></div></div></div></div></div><hr class=\"guide-markup\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"318d904e-6976-4e83-b8ec-5266e27587d5\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K7YHJTMDNC8CKVPZZWJ7EH62\" data-start=\"110\" data-end=\"135\"><strong class=\"guide-markup\" data-start=\"113\" data-end=\"135\">Self-Shipped Model</strong></h2>\n<p class=\"guide-markup\" data-start=\"137\" data-end=\"256\">The <strong class=\"guide-markup\" data-start=\"141\" data-end=\"163\">Self-Shipped Model</strong> is available <strong class=\"guide-markup\" data-start=\"177\" data-end=\"254\">only in regions where Fleek does not provide or manage shipping services.</strong></p>\n<p class=\"guide-markup\" data-start=\"258\" data-end=\"429\">In this model, sellers handle their <strong class=\"guide-markup\" data-start=\"294\" data-end=\"335\">own packaging, shipping, and delivery</strong> through a courier service of their choice. Sellers are fully responsible for ensuring that:</p>\n<ul class=\"guide-markup\" data-start=\"431\" data-end=\"587\">\n<li class=\"guide-markup\" data-start=\"431\" data-end=\"468\" data-list-item-id=\"ea83cde33642929dcba4ee2f8cca0f79b\"><p class=\"guide-markup\" data-start=\"433\" data-end=\"468\">Orders are <strong class=\"guide-markup\" data-start=\"444\" data-end=\"466\">dispatched on time</strong></p></li>\n<li class=\"guide-markup\" data-start=\"469\" data-end=\"506\" data-list-item-id=\"e4c9718031dbd273aea3d3a74268e2c14\"><p class=\"guide-markup\" data-start=\"471\" data-end=\"506\">Packages are <strong class=\"guide-markup\" data-start=\"484\" data-end=\"504\">delivered safely</strong></p></li>\n<li class=\"guide-markup\" data-start=\"507\" data-end=\"587\" data-list-item-id=\"e8a1d5ed694a708feb612513ee100abf0\"><p class=\"guide-markup\" data-start=\"509\" data-end=\"587\">All shipments <strong class=\"guide-markup\" data-start=\"523\" data-end=\"585\">meet Fleek’s packaging, tracking, and quality requirements</strong></p></li>\n</ul>\n<p class=\"guide-markup\" data-start=\"589\" data-end=\"711\">This model gives sellers <strong class=\"guide-markup\" data-start=\"614\" data-end=\"637\">greater flexibility</strong> but also places <strong class=\"guide-markup\" data-start=\"654\" data-end=\"677\">full responsibility</strong> for the shipping process on them.</p>\n<h3 class=\"guide-markup\" id=\"h_01K7YMSD95DH6GBC3YS5S7ZZ4R\" data-start=\"718\" data-end=\"749\"><strong class=\"guide-markup\" data-start=\"722\" data-end=\"749\">Seller Responsibilities</strong></h3>\n<p class=\"guide-markup\" data-start=\"751\" data-end=\"868\">As the seller, you are liable for the complete shipping process and any potential issues during transit, including:</p>\n<ul class=\"guide-markup\" data-start=\"870\" data-end=\"1172\">\n<li class=\"guide-markup\" data-start=\"870\" data-end=\"940\" data-list-item-id=\"eacecf071035df8405833c10b640564ce\"><p class=\"guide-markup\" data-start=\"872\" data-end=\"940\"><strong class=\"guide-markup\" data-start=\"872\" data-end=\"891\">Loss in transit</strong> – The order is lost before reaching the buyer.</p></li>\n<li class=\"guide-markup\" data-start=\"941\" data-end=\"1012\" data-list-item-id=\"ed8e18228b0d2f1929de34c5e200658eb\"><p class=\"guide-markup\" data-start=\"943\" data-end=\"1012\"><strong class=\"guide-markup\" data-start=\"943\" data-end=\"964\">Damage in transit</strong> – The product is damaged while being shipped.</p></li>\n<li class=\"guide-markup\" data-start=\"1013\" data-end=\"1088\" data-list-item-id=\"ef2158f4b6eb4cbba78882c8aa0342072\"><p class=\"guide-markup\" data-start=\"1015\" data-end=\"1088\"><strong class=\"guide-markup\" data-start=\"1015\" data-end=\"1043\">Customs clearance issues</strong> – Orders held at customs for verification.</p></li>\n<li class=\"guide-markup\" data-start=\"1089\" data-end=\"1172\" data-list-item-id=\"ea7c18a2d82a1a681e8f757be4e350e1a\"><p class=\"guide-markup\" data-start=\"1091\" data-end=\"1172\"><strong class=\"guide-markup\" data-start=\"1091\" data-end=\"1112\">Failed deliveries</strong> – Orders returned due to incomplete or incorrect addresses.</p></li>\n</ul>\n<h3 class=\"guide-markup\" id=\"h_01K7YMSFERP6RK3PXPSS4WMETB\" data-start=\"1179\" data-end=\"1227\"><strong class=\"guide-markup\" data-start=\"1183\" data-end=\"1227\">Postage / Shipping Charges Reimbursement</strong></h3>\n<p class=\"guide-markup\" data-start=\"1229\" data-end=\"1287\">Shipping charges can be reimbursed, provided you submit:</p>\n<ul class=\"guide-markup\" data-start=\"1289\" data-end=\"1412\">\n<li class=\"guide-markup\" data-start=\"1289\" data-end=\"1316\" data-list-item-id=\"ec1388a872db79e3f38d5df741e88eae3\"><p class=\"guide-markup\" data-start=\"1291\" data-end=\"1316\">A valid <strong class=\"guide-markup\" data-start=\"1299\" data-end=\"1314\">Tracking ID</strong></p></li>\n<li class=\"guide-markup\" data-start=\"1317\" data-end=\"1412\" data-list-item-id=\"ee6b5c515bfd376cb6e895867384bf327\"><p class=\"guide-markup\" data-start=\"1319\" data-end=\"1412\"><strong class=\"guide-markup\" data-start=\"1319\" data-end=\"1350\">Postage or shipping invoice</strong>, or any other <strong class=\"guide-markup\" data-start=\"1365\" data-end=\"1382\">payment proof</strong> from the logistics provider</p></li>\n</ul>\n<blockquote class=\"guide-markup\" data-start=\"1414\" data-end=\"1618\"><p class=\"guide-markup\" data-start=\"1416\" data-end=\"1618\"><strong class=\"guide-markup\" data-start=\"1416\" data-end=\"1425\">Note:</strong> If you operate in a region where Fleek <strong class=\"guide-markup\" data-start=\"1465\" data-end=\"1494\">provides managed shipping</strong>, you <strong class=\"guide-markup\" data-start=\"1500\" data-end=\"1526\">will not be reimbursed</strong> for any amount exceeding Fleek’s <strong class=\"guide-markup\" data-start=\"1560\" data-end=\"1617\">system-estimated or calculator-based shipping charges</strong>.</p></blockquote>\n<hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K7SRCN8Z5J28QD3BNXE4G932\"><strong class=\"guide-markup\" data-start=\"133\" data-end=\"159\">Fleek-Managed Shipping</strong></h2>\n<p class=\"guide-markup\" data-start=\"162\" data-end=\"537\">Fleek-Managed Shipping allows sellers to fulfill orders through Fleek’s trusted logistics partners. Once an order is ready, a Fleek-assigned driver collects the package and ensures safe, timely delivery to the buyer. This model simplifies the shipping process, offers end-to-end tracking, and provides sellers with reliable delivery support under Fleek’s logistics network.</p>\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"77\"><strong class=\"guide-markup\" data-start=\"0\" data-end=\"26\">Fleek-Managed Shipping</strong> is currently available in the following regions:</p>\n<ul class=\"guide-markup\" data-start=\"79\" data-end=\"156\">\n<li class=\"guide-markup\" data-start=\"79\" data-end=\"91\" data-list-item-id=\"e1f7bd5e68c68e4b9f18452479131da52\"><p class=\"guide-markup\" data-start=\"81\" data-end=\"91\">Pakistan</p></li>\n<li class=\"guide-markup\" data-start=\"92\" data-end=\"101\" data-list-item-id=\"ec2b64b2d840c83af0fab2a793b7823c4\"><p class=\"guide-markup\" data-start=\"94\" data-end=\"101\">India</p></li>\n<li class=\"guide-markup\" data-start=\"102\" data-end=\"125\" data-list-item-id=\"ef671e30f1cd65ada23c1b49e3c2e0fb7\"><p class=\"guide-markup\" data-start=\"104\" data-end=\"125\">United Kingdom (UK)</p></li>\n<li class=\"guide-markup\" data-start=\"126\" data-end=\"156\" data-list-item-id=\"e63cf2a199533085cff86fb2c8fc64671\"><p class=\"guide-markup\" data-start=\"128\" data-end=\"156\">United Arab Emirates (UAE)</p></li>\n</ul>\n<p class=\"guide-markup\" data-start=\"158\" data-end=\"233\" data-is-last-node=\"\" data-is-only-node=\"\">Let’s walk you through the simple steps to process your order effortlessly.</p>\n<hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01KW9C4Q1RM9NCF1TQVMZ4R4S0\"><strong class=\"guide-markup\" data-start=\"133\" data-end=\"159\">Sea Shipping</strong></h2>\n<p>Sea Shipping is a new, lower-cost freight option on Fleek. The same products from the same suppliers travel by sea freight instead of air, cutting the shipping cost by up to <strong>70%</strong>. This makes your bulk and heavy lots significantly more affordable for buyers and helps you close more orders.</p>\n<p>Click <a href=\"https://support.joinfleek.com/hc/en-us/articles/52305309189659\">here</a> to read more about sea shipping.</p>\n<hr>\n<h2 class=\"guide-markup\" id=\"h_01KW9C4Q1RHADBW9KT74RGYCPF\"><strong class=\"guide-markup\" data-start=\"133\" data-end=\"159\">Best Practices</strong></h2>\n<ul class=\"guide-markup\" data-start=\"1952\" data-end=\"2278\">\n<li class=\"guide-markup\" data-start=\"1952\" data-end=\"2041\" data-list-item-id=\"ef5bc90845e56b46e40e9b1566e0883c5\"><p class=\"guide-markup\" data-start=\"1954\" data-end=\"2041\">Always <strong class=\"guide-markup\" data-start=\"1961\" data-end=\"2010\">double-check weight, dimensions, and category</strong> before calculating shipping.</p></li>\n<li class=\"guide-markup\" data-start=\"2042\" data-end=\"2103\" data-list-item-id=\"efcc17ed09dcbeee34ee2c30b62e5a9f0\"><p class=\"guide-markup\" data-start=\"2044\" data-end=\"2103\">Avoid underestimating shipping charges to increase sales — it can lead to losses in your final payout.</p></li>\n<li class=\"guide-markup\" data-start=\"2185\" data-end=\"2278\" data-list-item-id=\"e4e91a0f4b6cf172ff65ef816a9d1ff06\"><p class=\"guide-markup\" data-start=\"2187\" data-end=\"2278\">For multiple products, maintain a <strong class=\"guide-markup\" data-start=\"2221\" data-end=\"2254\">shipping cost reference sheet</strong> for easy calculation.</p></li>\n<li class=\"guide-markup\" data-start=\"2185\" data-end=\"2278\" data-list-item-id=\"e999555d8422d3dbeb5376a0b5b3a32ff\"><p class=\"guide-markup\" data-start=\"2187\" data-end=\"2278\">Fleek encourages suppliers to use the <strong class=\"guide-markup\" data-start=\"47\" data-end=\"76\">Fleek Shipping Calculator</strong> to accurately estimate shipping costs and avoid miscalculations.</p></li>\n</ul>\n<hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K7YJF5M8F430V6Q3QQZ7078N\" data-start=\"4507\" data-end=\"4549\"><strong>Quick Reference: Who Calculates What</strong></h2>\n<figure class=\"wysiwyg-image guide-markup\"><img class=\"guide-markup\" style=\"aspect-ratio: 1682/434;\" src=\"https://support.joinfleek.com/hc/article_attachments/42544770788251\" width=\"1682\" height=\"434\"></figure><hr class=\"guide-markup\">\n<h2 class=\"guide-markup\" id=\"h_01K7YPZ1ANBVTZPG8HME8QNBA9\"><strong class=\"guide-markup\">Frequently Asked Questions</strong></h2>\n</div></div></div></div><details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. How does Fleek calculate shipping charges?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> Shipping costs depend on factors like <strong class=\"guide-markup\">weight</strong>, <strong class=\"guide-markup\">dimensions</strong>, <strong class=\"guide-markup\">delivery location</strong>, and <strong class=\"guide-markup\">courier rates</strong>. <br class=\"guide-markup\"><br class=\"guide-markup\"> For <strong class=\"guide-markup\">Exact</strong> or <strong class=\"guide-markup\">Representative</strong> products, Fleek automatically calculates the shipping. <br class=\"guide-markup\"><br class=\"guide-markup\"> For <strong class=\"guide-markup\">Custom</strong>, <strong class=\"guide-markup\">Handpick</strong>, or <strong class=\"guide-markup\">Self-Shipped</strong> products, you (the seller) must calculate and include the shipping cost in your product price. </div> </details>\n<details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. Do I need to calculate shipping for Exact or Representative products?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> No. Fleek automatically calculates and collects shipping from the buyer. You don’t need to add it to your product price or worry about payout deductions. </div> </details>\n<details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. What if I’m selling Custom or Handpick products — who calculates shipping?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> For <strong class=\"guide-markup\">Custom</strong> or <strong class=\"guide-markup\">Handpick</strong> products, the seller calculates the shipping cost. You can estimate manually or use Fleek’s <strong class=\"guide-markup\">Shipping Calculator</strong>. <br class=\"guide-markup\"><br class=\"guide-markup\"> If you are a <strong class=\"guide-markup\">ROW Supplier (Self-Shipped Model)</strong>, you must include the shipping cost in your product’s base price before listing. </div> </details>\n<details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. What is the Self-Shipped Model?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> The <strong class=\"guide-markup\">Self-Shipped Model</strong> applies in regions where Fleek does not manage logistics. You are fully responsible for: <ul style=\"margin-top: 4px;\" class=\"guide-markup\"> <li class=\"guide-markup\">Packaging and dispatching orders on time</li> <li class=\"guide-markup\">Delivering through your preferred courier</li> <li class=\"guide-markup\">Providing valid tracking and proof of delivery</li> </ul> </div> </details>\n<details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. What are my responsibilities under the Self-Shipped Model?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> As a Self-Shipped seller, you must: <ul style=\"margin-top: 4px;\" class=\"guide-markup\"> <li class=\"guide-markup\">Dispatch all orders on time</li> <li class=\"guide-markup\">Ensure safe and complete delivery</li> <li class=\"guide-markup\">Handle customs clearance if required</li> <li class=\"guide-markup\">Cover losses from damage or failed delivery</li> </ul> </div> </details>\n<details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">6. Can I get reimbursed for shipping charges?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> Yes — if you provide a <strong class=\"guide-markup\">valid tracking ID</strong> and a <strong class=\"guide-markup\">shipping invoice or proof of payment</strong> from your courier. <br class=\"guide-markup\"><br class=\"guide-markup\"> In regions with <strong class=\"guide-markup\">Fleek-Managed Shipping</strong>, reimbursements are limited to Fleek’s estimated or pre-calculated amount. </div> </details>\n<details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">7. In which regions is Fleek-Managed Shipping available?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> Fleek-Managed Shipping is currently available in: <ul style=\"margin-top: 4px;\" class=\"guide-markup\"> <li class=\"guide-markup\">Pakistan</li> <li class=\"guide-markup\">India</li> <li class=\"guide-markup\">United Kingdom (UK)</li> <li class=\"guide-markup\">United Arab Emirates (UAE)</li> </ul> </div> </details>\n<details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">8. How does Fleek-Managed Shipping work?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> When your order is ready, a <strong class=\"guide-markup\">Fleek-assigned driver</strong> collects the package, handles the delivery, and provides full tracking updates. <br class=\"guide-markup\"><br class=\"guide-markup\"> This ensures smooth, reliable, and on-time delivery for both you and your buyers. </div> </details>\n<details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">9. How can I estimate shipping costs before listing my product?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> Use Fleek’s <strong class=\"guide-markup\">Shipping Calculator</strong> available under the <em class=\"guide-markup\">Profile</em> section in your Vendor App, or the <strong class=\"guide-markup\">Custom Handpick Shipping Calculator</strong> in the Handpick listing flow. <br class=\"guide-markup\"><br class=\"guide-markup\"> Always confirm accurate <strong class=\"guide-markup\">category</strong>, <strong class=\"guide-markup\">weight</strong>, and <strong class=\"guide-markup\">dimensions</strong> to get the best estimate. </div> </details>\n<details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">10. What happens if I underestimate shipping charges to attract buyers?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> Underestimating shipping charges can lead to reduced payout or losses, as the shortfall will be deducted from your final payment. <br class=\"guide-markup\"><br class=\"guide-markup\"> Always use the <strong class=\"guide-markup\">Shipping Calculator</strong> to ensure accuracy. </div> </details>\n<details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">11. What documents do I need to claim shipping reimbursement?</span> </summary> <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\"> To claim shipping reimbursement, you must provide: <ul style=\"margin-top: 4px;\" class=\"guide-markup\"> <li class=\"guide-markup\">A valid tracking number</li> <li class=\"guide-markup\">A shipping invoice or payment proof from your courier</li> </ul> </div> </details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42543546606491,"title":"Order Fulfilment Policy","body":"<h3 class=\"guide-markup\" id=\"h_01K7Q8WXRX4HAKQ4NK68KKZZX0\" data-start=\"275\" data-end=\"324\"><strong class=\"guide-markup\" data-start=\"279\" data-end=\"324\">What is Fleek’s Order Fulfillment Policy?</strong></h3><p class=\"guide-markup\" data-start=\"335\" data-end=\"566\"><span style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\">Fleek’s <strong class=\"guide-markup\" data-start=\"343\" data-end=\"371\">Order Fulfillment Policy</strong></span></span> defines the standards and timelines every seller must follow to ensure their orders are <strong class=\"guide-markup\" data-start=\"460\" data-end=\"505\">processed, packed, and dispatched on time</strong> — maintaining a smooth and reliable experience for buyers.</p><p class=\"guide-markup\" data-start=\"568\" data-end=\"854\">This policy applies to <strong class=\"guide-markup\" data-start=\"591\" data-end=\"615\">all sellers on Fleek</strong>, including those operating in regions <strong class=\"guide-markup\" data-start=\"654\" data-end=\"708\">where pickup service is available or not available</strong>. It sets clear expectations for <strong class=\"guide-markup\" data-start=\"741\" data-end=\"795\">timely order acceptance, preparation, and handover</strong>, ensuring consistent service quality across all markets.</p><p class=\"guide-markup\" data-start=\"856\" data-end=\"995\">By following this policy, sellers help Fleek maintain <strong class=\"guide-markup\" data-start=\"910\" data-end=\"992\">on-time deliveries, higher buyer satisfaction, and efficient payout processing</strong>.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7Q98SQ8FENTHB83DEQDS66Q\" data-start=\"575\" data-end=\"604\"><strong class=\"guide-markup\" data-start=\"579\" data-end=\"604\">Purpose of the Policy</strong></h3><p class=\"guide-markup\" data-start=\"606\" data-end=\"828\">The purpose of this policy is to ensure that all sellers on Fleek follow a <strong class=\"guide-markup\" data-start=\"681\" data-end=\"717\">standardized fulfillment process</strong> — from order acceptance to final delivery. By maintaining clear timelines and quality checks, Fleek aims to:</p><ul class=\"guide-markup\" data-start=\"829\" data-end=\"1038\">\n<li class=\"guide-markup\" data-start=\"829\" data-end=\"890\" data-list-item-id=\"ea25bf58c268a52cca51e3a54a5cf8049\"><p class=\"guide-markup\" data-start=\"831\" data-end=\"890\">Provide buyers with a <strong class=\"guide-markup\" data-start=\"853\" data-end=\"888\">reliable and on-time experience</strong></p></li>\n<li class=\"guide-markup\" data-start=\"891\" data-end=\"961\" data-list-item-id=\"eead1947ddb13bc50059211c879fa3f0a\"><p class=\"guide-markup\" data-start=\"893\" data-end=\"961\">Support sellers in <strong class=\"guide-markup\" data-start=\"912\" data-end=\"959\">achieving faster payouts and fewer disputes</strong></p></li>\n<li class=\"guide-markup\" data-start=\"962\" data-end=\"1038\" data-list-item-id=\"e1194698c1d8276b9a5692a303d1f11d6\"><p class=\"guide-markup\" data-start=\"964\" data-end=\"1038\">Maintain consistent <strong class=\"guide-markup\" data-start=\"984\" data-end=\"1017\">service and product standards</strong> across all regions</p></li>\n</ul><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7Q9QVMZE6Q4NXJC3WJEP0K0\" data-start=\"212\" data-end=\"245\"><strong class=\"guide-markup\" data-start=\"216\" data-end=\"245\">Order Processing Timeline</strong></h3><p class=\"guide-markup\" data-start=\"247\" data-end=\"388\">To ensure smooth operations and timely deliveries, all sellers are required to follow Fleek’s standard order processing timelines strictly:</p><h4 id=\"h_01K8BMCV86GSV8TCYD0S48PB14\">🕒 <strong class=\"guide-markup\" data-start=\"393\" data-end=\"417\">1. Order Acceptance:</strong>\n</h4><p>Sellers must <strong class=\"guide-markup\" data-start=\"433\" data-end=\"489\">accept or acknowledge each new order within 24 hours</strong> from the time it is created in the system. Orders not accepted within this time may be automatically cancelled.</p><h4 id=\"h_01K8BMD04KZJBS8YMGZYD4N215\">📦 <strong class=\"guide-markup\" data-start=\"608\" data-end=\"633\">2. Order Fulfillment:</strong>\n</h4><p>Once accepted, sellers must <strong class=\"guide-markup\" data-start=\"664\" data-end=\"736\">pack and mark the order as Ready for Pickup within the next 24 hours</strong>. This ensures timely collection by the Fleek pickup team and smooth dispatch to the buyer.</p><h4 id=\"h_01K8BMEBBNSC26C7S02PMH8MNM\">🚚 <strong class=\"guide-markup\" data-start=\"949\" data-end=\"990\">3. Handover to Pickup Team / Courier:</strong>\n</h4><p>After marking the order as <em class=\"guide-markup\" data-start=\"1020\" data-end=\"1038\"><em>Ready for Pickup or accpetance</em></em>, sellers must <strong class=\"guide-markup\" data-start=\"1053\" data-end=\"1150\">handover the parcel to the Fleek pickup team or your choosed courier (if you are on a self shipped model) within the 48 hours of order creation</strong>. Any missed or delayed handovers can result in cancellation or delayed payout.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7QANHB2ZXEXK1SE4FKXTYZ5\" data-start=\"143\" data-end=\"190\"><strong class=\"guide-markup\" data-start=\"147\" data-end=\"188\">How Do You Process an Order on Fleek?</strong></h3><p class=\"guide-markup\" data-start=\"191\" data-end=\"357\">Processing an order on time is the key to smooth sales and happy buyers.<br><br>Click <a class=\"guide-markup\">here</a> to learn the simple steps for fulfilling your orders efficiently.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7T5EKN8X36703FYTMWQS01B\" data-start=\"143\" data-end=\"190\"><strong class=\"guide-markup\">Order Journey:</strong></h3><p class=\"guide-markup\" data-start=\"191\" data-end=\"357\">In Fleek, the order journey is simple and easy.</p><p class=\"guide-markup\" data-start=\"191\" data-end=\"357\">Click <a class=\"guide-markup\">here</a> to know more about Fleek's Order Journey.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7T5EKN8GAGHPX905R50RN88\" data-start=\"143\" data-end=\"190\"><strong class=\"guide-markup\">Order Cancellation:</strong></h3><p class=\"guide-markup\">At <strong class=\"guide-markup\" data-start=\"51\" data-end=\"60\">Fleek</strong>, we ensure a smooth experience for sellers and buyers. </p><p class=\"guide-markup\">Click <a class=\"guide-markup\">here</a> to learn more about our Order Cancellation Policy.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7QASHZ6M3JP7A80Y6ZYQ5B3\" data-start=\"143\" data-end=\"190\"><strong class=\"guide-markup\" data-start=\"147\" data-end=\"188\">Frequently Asked Questions:</strong></h3><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. What does order fulfilment mean on Fleek?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Order fulfilment means preparing, confirming, and handing over your accepted\n    orders within the given timelines — ensuring every buyer receives exactly\n    what they purchased in good condition.\n  </div>\n  </details>  \n  <details class=\"guide-markup\">\n      <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n        <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. What is the fulfilment timeline after accepting an order?</span>\n      </summary>\n      <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n        You must mark your order as <strong class=\"guide-markup\">Ready for Pickup</strong> within\n        48 hours\n        after accepting it. This ensures timely processing and dispatch.\n      </div>\n    </details>\n    <details class=\"guide-markup\">\n      <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n        <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. What happens if I delay fulfilment?</span>\n      </summary>\n      <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n        Delays can affect your <strong class=\"guide-markup\">Supplier Performance Score</strong>,\n        order\n        visibility, and payout timeline. Repeated delays may also lead to\n        penalties\n        or temporary listing restrictions.\n      </div>\n    </details>\n    <details class=\"guide-markup\">\n      <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n        <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. Can I cancel an order after accepting it?</span>\n      </summary>\n      <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n        Cancellations after acceptance are discouraged and only allowed under\n        valid\n        reasons (e.g., product out of stock or damaged). You must inform\n        Seller\n        Support\n        immediately to avoid negative performance impact.\n      </div>\n    </details>\n    <details class=\"guide-markup\">\n      <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n        <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. What should I do if the product is damaged or missing before dispatch?</span>\n      </summary>\n      <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n        Do not ship the order. Instead, report it immediately to\n        <strong class=\"guide-markup\">Seller Support</strong> with photos and details so the issue\n        can\n        be handled before it reaches the buyer.\n      </div>\n    </details>\n    <details class=\"guide-markup\">\n      <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n        <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">6. How do I mark my order as Ready for Pickup?</span>\n      </summary>\n      <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n        Go to the <strong class=\"guide-markup\">Orders</strong> section in your Fleek Vendor App,\n        select\n        the order, and tap <strong class=\"guide-markup\">Mark Ready for Pickup</strong> once it’s\n        fully\n        prepared for dispatch.\n      </div>\n    </details>\n    <details class=\"guide-markup\">\n      <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n        <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">7. What if the courier doesn’t arrive for pickup?</span>\n      </summary>\n      <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n        If pickup doesn’t happen within the assigned time, contact\n        <strong class=\"guide-markup\">Seller Support</strong> via app or WhatsApp. The team will\n        coordinate\n        with Operations to arrange a new pickup.\n      </div>\n    </details>\n    <details class=\"guide-markup\">\n      <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n        <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">8. What happens if I hand over a wrong or mismatched item?</span>\n      </summary>\n      <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n        Incorrect fulfilment may lead to a refund, penalty, or performance\n        deduction.\n        Always double-check order details such as size, condition, and tags\n        before\n        handing over the parcel. Fleek’s <strong class=\"guide-markup\">Quality Check (QC)</strong>\n        team\n        also serves as an additional layer to identify such errors. If any\n        issue\n        is highlighted, please ensure timely resolution to avoid delays or\n        disputes.\n      </div>\n    </details>\n    <details class=\"guide-markup\">\n      <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n        <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">9. What are Fleek’s pickup regions?</span>\n      </summary>\n      <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n        Fleek provides pickup services in selected regions. For others, suppliers\n        must dispatch via their own courier within 48 hours after marking\n        <strong class=\"guide-markup\">Ready for Pickup</strong>.\n      </div>\n    </details>\n    <details class=\"guide-markup\">\n      <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n        <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">10. What should I do after dispatching via my own courier?</span>\n      </summary>\n      <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n        Update the <strong class=\"guide-markup\">tracking ID</strong> in the Vendor App so Fleek\n        can\n        verify\n        delivery and process your payment once it’s marked as\n        <strong class=\"guide-markup\">Delivered</strong>.\n      </div>\n    </details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42543394608667,"title":"How to Process an Order?","body":"<div class=\"guide-markup\">Processing orders on time is key to ensuring a smooth selling experience and maintaining buyer satisfaction. This section guides you through each step — from receiving an order to preparing, packing, and dispatching it — so your orders are fulfilled accurately and within the required timeline. </div><p class=\"guide-markup\" data-start=\"0\" data-end=\"78\">In Fleek, there are two order fulfillment methods, depending on your region:</p><ul class=\"guide-markup\" data-start=\"80\" data-end=\"135\" data-is-last-node=\"\" data-is-only-node=\"\">\n<li class=\"guide-markup\" data-start=\"80\" data-end=\"110\" data-list-item-id=\"e9dcc63adf7f8dd23ff7d5ec71ba6ff8e\"><p class=\"guide-markup\" data-start=\"82\" data-end=\"110\">Fleek-Managed Shipping</p></li>\n<li class=\"guide-markup\" data-start=\"111\" data-end=\"135\" data-is-last-node=\"\" data-list-item-id=\"ef9984398d4bdaf79d6ec94675e956a66\"><p class=\"guide-markup\" data-start=\"113\" data-end=\"135\" data-is-last-node=\"\">Self-Shipped Model</p></li>\n</ul><p class=\"guide-markup\">Following these steps helps you avoid delays, penalties, and negative performance impact.</p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7SRCN8Z5J28QD3BNXE4G932\"><strong class=\"guide-markup\" data-start=\"133\" data-end=\"159\">Fleek-Managed Shipping</strong></h2><p class=\"guide-markup\" data-start=\"162\" data-end=\"537\">Fleek-Managed Shipping allows sellers to fulfill orders through Fleek’s trusted logistics partners. Once an order is ready, a Fleek-assigned driver collects the package and ensures safe, timely delivery to the buyer. This model simplifies the shipping process, offers end-to-end tracking, and provides sellers with reliable delivery support under Fleek’s logistics network.</p><p class=\"guide-markup\" data-start=\"0\" data-end=\"77\"><strong class=\"guide-markup\" data-start=\"0\" data-end=\"26\">Fleek-Managed Shipping</strong> is currently available in the following regions:</p><ul class=\"guide-markup\" data-start=\"79\" data-end=\"156\">\n<li class=\"guide-markup\" data-start=\"79\" data-end=\"91\" data-list-item-id=\"e2de34f9bafc397a085041c75289c117c\"><p class=\"guide-markup\" data-start=\"81\" data-end=\"91\">Pakistan</p></li>\n<li class=\"guide-markup\" data-start=\"92\" data-end=\"101\" data-list-item-id=\"e3928756efb076c449d68bf6be72fcf5f\"><p class=\"guide-markup\" data-start=\"94\" data-end=\"101\">India</p></li>\n<li class=\"guide-markup\" data-start=\"102\" data-end=\"125\" data-list-item-id=\"e976025d3a094d8ca990c188918560dd2\"><p class=\"guide-markup\" data-start=\"104\" data-end=\"125\">United Kingdom (UK)</p></li>\n<li class=\"guide-markup\" data-start=\"126\" data-end=\"156\" data-list-item-id=\"eb8eee76bf7101e3f998c0b86e2259873\"><p class=\"guide-markup\" data-start=\"128\" data-end=\"156\">United Arab Emirates (UAE)</p></li>\n</ul><p class=\"guide-markup\" data-start=\"158\" data-end=\"233\" data-is-last-node=\"\" data-is-only-node=\"\">Let’s walk you through the simple steps to process your order effortlessly.</p><h3 class=\"guide-markup\" id=\"h_01K7T3FPTGGS1YJA7RSJJZRDTK\" data-start=\"129\" data-end=\"161\"><strong class=\"guide-markup\">Step 1: Accept Order</strong></h3><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1920/1080;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42543385507867\" alt=\"How to Fulfill an Order (3).jpg\" width=\"1920\" height=\"1080\"></figure><h3 class=\"guide-markup\" id=\"h_01K7SRCY7RZK9NEBFS1DANCSY2\" data-start=\"544\" data-end=\"572\"><strong class=\"guide-markup\" data-start=\"548\" data-end=\"570\">Step 2: Ready For Pickup</strong></h3><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1920/1080;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42543394604699\" alt=\"11.jpg\" width=\"1920\" height=\"1080\"></figure><p class=\"guide-markup\">After your order is Picked up. It will be inbounded to the our <strong class=\"guide-markup\">Fleek Quality Check Warehouse </strong>for reviewing the quality of your items. </p><p class=\"guide-markup\">If your order put on hold by the QC team, please ensure timely resolution to avoid delays in further order processing and delays in payment.</p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7SYNN8B8G0PR775V2WNWVRA\"><strong class=\"guide-markup\" data-start=\"548\" data-end=\"570\">Self-Shipped Model</strong></h2><p class=\"guide-markup\" data-start=\"573\" data-end=\"949\">In the Self-Shipped Model, sellers manage their own packaging and delivery through their preferred courier service. Sellers are responsible for ensuring that orders are dispatched on time, delivered safely, and meet Fleek’s packaging and tracking requirements. This model offers greater flexibility but also places full responsibility for the shipping process on the seller.</p><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"318d904e-6976-4e83-b8ec-5266e27587d5\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\"><p class=\"guide-markup\" data-start=\"0\" data-end=\"118\" data-is-last-node=\"\" data-is-only-node=\"\">The <strong class=\"guide-markup\" data-start=\"4\" data-end=\"26\">Self-Shipped Model</strong> applies to all other regions where Fleek’s managed shipping services are not yet available.</p></div></div></div></div><div class=\"guide-markup\"><div class=\"guide-markup\"><div class=\"guide-markup\"><div class=\"guide-markup\"><div class=\"guide-markup\">Here are the simple step to process your order.</div></div></div></div></div><h3 class=\"guide-markup\" id=\"h_01K7T3FPTG7KXEC9T3RSN2NWXQ\" data-start=\"129\" data-end=\"161\"><strong class=\"guide-markup\">Step 1: Accept Order</strong></h3><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1920/1080;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42543385507867\" alt=\"How to Fulfill an Order (3).jpg\" width=\"1920\" height=\"1080\"></figure><h3 class=\"guide-markup\" id=\"h_01K7T3FPTG7YBR2ZGT5GEKBJ28\" data-start=\"544\" data-end=\"572\"><strong class=\"guide-markup\" data-start=\"548\" data-end=\"570\">Step 2: Ready and Handover your order</strong></h3><p class=\"guide-markup\" data-start=\"573\" data-end=\"949\">In the Self-Shipped Model, sellers manage their own packaging and delivery through their preferred courier. Please ensure careful packaging to avoid damages and hand over the parcel timely to the courier.</p><h3 class=\"guide-markup\" id=\"h_01K7T3FPTGXS5NEP1JDDPNEFDN\" data-start=\"544\" data-end=\"572\"><strong class=\"guide-markup\" data-start=\"548\" data-end=\"570\">Step 3: Update Shipping Details</strong></h3><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1920/1080;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42543385511195\" alt=\"12.jpg\" width=\"1920\" height=\"1080\"></figure><h4 class=\"guide-markup\" id=\"h_01K7T28AHR171848XACKNFT9V1\"><strong class=\"guide-markup\">Important Points:</strong></h4><p class=\"guide-markup\">Please keep the hand over receipt and invoice for you order after its been handed over to the courier. It may required for the postage or shipping charges reversal.</p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7T2FTCQ10KHYBMABQQ5PF38\"><strong class=\"guide-markup\" data-start=\"147\" data-end=\"188\">Frequently Asked Questions:</strong></h2><details class=\"guide-markup\"> <summary style=\"list-style: none; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">1. How much time do I have to process an order?</span> </summary> You must process your order within <b class=\"guide-markup\">24 hours</b> after accepting it to ensure timely dispatch and avoid cancellation or performance impact. </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">2. What happens if I miss the 24-hour processing window?</span> </summary> Missing the processing deadline can result in automatic order cancellation and negatively affect your <b class=\"guide-markup\">Supplier Performance Score</b>. Always aim to process on time to maintain your ratings. </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">3. Can I edit an order after marking it Ready for Pickup?</span> </summary> No. Once an order is processed and marked <b class=\"guide-markup\">Ready for Pickup</b>, you can no longer modify product details, price, or shipping information. </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">4. What should I do if I face a technical issue while processing an order?</span> </summary> If you encounter an issue in the <b class=\"guide-markup\">Fleek Vendor App</b>, contact <b class=\"guide-markup\">Seller Support</b> immediately through Chat or WhatsApp, or visit the <b class=\"guide-markup\">Help Center</b> for quick troubleshooting. </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">5. Why is timely order processing important?</span> </summary> Fast processing ensures <b class=\"guide-markup\">on-time delivery</b>, <b class=\"guide-markup\">higher buyer satisfaction</b>, and an improved <b class=\"guide-markup\">store ranking</b> — leading to more visibility and sales opportunities on Fleek. </details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42543244979227,"title":"Inventory Management Guide","body":"<p class=\"guide-markup\" data-start=\"139\" data-end=\"379\">Efficient inventory management is key to maintaining smooth sales, timely order fulfillment, and a positive buyer experience on <strong class=\"guide-markup\" data-start=\"267\" data-end=\"276\">Fleek</strong>. This guide will help you keep track of your stock, active or inactive, update listings, and avoid stock-related issues.</p><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7T678RY96XPVMHRC0V56F67\" data-start=\"386\" data-end=\"429\"><strong class=\"guide-markup\" data-start=\"390\" data-end=\"429\">1. Why Inventory Management Matters</strong></h3><ul class=\"guide-markup\" data-start=\"431\" data-end=\"670\">\n<li class=\"guide-markup\" data-start=\"431\" data-end=\"498\" data-list-item-id=\"e791fd856f1888a3636b50704fcc0a440\"><p class=\"guide-markup\" data-start=\"433\" data-end=\"498\">Ensures that products are always in stock and ready for buyers.</p></li>\n<li class=\"guide-markup\" data-start=\"499\" data-end=\"552\" data-list-item-id=\"e9747357742e506382e8d1ad614739870\"><p class=\"guide-markup\" data-start=\"501\" data-end=\"552\">Prevents cancellations due to out-of-stock items.</p></li>\n<li class=\"guide-markup\" data-start=\"553\" data-end=\"618\" data-list-item-id=\"e75a7c230ef60b83a3d24a3fe14324f0b\"><p class=\"guide-markup\" data-start=\"555\" data-end=\"618\">Helps maintain your Seller Score and overall performance.</p></li>\n<li class=\"guide-markup\" data-start=\"619\" data-end=\"670\" data-list-item-id=\"e88f1720c15053efdb03914e9b8065669\"><p class=\"guide-markup\" data-start=\"621\" data-end=\"670\">Reduces errors in pricing and product listings.</p></li>\n</ul><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7T6801QRKZPG0HTZW9C4WCR\" data-start=\"677\" data-end=\"712\"><strong class=\"guide-markup\" data-start=\"681\" data-end=\"712\">2. Accessing Your Inventory</strong></h3><ul class=\"guide-markup\">\n<li class=\"guide-markup\" data-start=\"714\" data-end=\"756\" data-list-item-id=\"e45e3ac8230430f6d5566914ca1703267\"><p class=\"guide-markup\" data-start=\"717\" data-end=\"756\"><strong class=\"guide-markup\" data-start=\"717\" data-end=\"727\">Log in</strong> to the Vendor Application.</p></li>\n<li class=\"guide-markup\" data-start=\"757\" data-end=\"796\" data-list-item-id=\"ec78193a87daf1fa1f75e172a084b4370\"><p class=\"guide-markup\" data-start=\"760\" data-end=\"796\">Navigate to the <strong class=\"guide-markup\" data-start=\"776\" data-end=\"789\">Inventory</strong> tab.</p></li>\n<li class=\"guide-markup\" data-start=\"797\" data-end=\"862\" data-list-item-id=\"e7027c8671ca6d0482da02fffda323b47\"><p class=\"guide-markup\" data-start=\"800\" data-end=\"862\">Browse or search for the product listing you want to manage.</p></li>\n</ul><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7T6J0JZB1T4936BGRSED638\"><strong class=\"guide-markup\" data-start=\"29\" data-end=\"65\">3. How to Update Your Inventory?</strong></h3><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1920/1080;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42543227816987\" alt=\"Manage Inventory (3).jpg\" width=\"1920\" height=\"1080\"></figure><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7T6RY22W20A5F1QJBDFAZH4\"><strong class=\"guide-markup\" data-start=\"29\" data-end=\"65\">3. How to Active your Listing?</strong></h3><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1920/1080;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42543244976027\" alt=\"Manage Inventory (2).jpg\" width=\"1920\" height=\"1080\"></figure><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7T7M4CB6FJ4ZXEJ3E1J6XEC\"><strong class=\"guide-markup\" data-start=\"29\" data-end=\"65\">4. How to In-active your Listing?</strong></h3><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1920/1080;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42543244976411\" width=\"1920\" height=\"1080\"></figure><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7T87XQEF6KBSWXXX7DTWF4C\"><strong class=\"guide-markup\">5. How to mark Out of stock?</strong></h3><figure class=\"wysiwyg-image guide-markup\"><img style=\"aspect-ratio: 1920/1080;\" class=\"guide-markup\" src=\"https://support.joinfleek.com/hc/article_attachments/42543244977435\" width=\"1920\" height=\"1080\"></figure><hr class=\"guide-markup\"><h3 class=\"guide-markup\" id=\"h_01K7T8JV9GWVPWWNN4Y5X0336M\" data-start=\"1765\" data-end=\"1815\"><strong class=\"guide-markup\" data-start=\"1769\" data-end=\"1815\">6. Best Practices for Inventory Management</strong></h3><ul class=\"guide-markup\" data-start=\"1817\" data-end=\"2132\">\n<li class=\"guide-markup\" data-start=\"1817\" data-end=\"1893\" data-list-item-id=\"e3c1f2e037002659d044f959cd44dd425\"><p class=\"guide-markup\" data-start=\"1819\" data-end=\"1893\">Regularly audit your stock to match physical inventory with app records.</p></li>\n<li class=\"guide-markup\" data-start=\"1970\" data-end=\"2057\" data-list-item-id=\"e39607f4bf4971755aaf2996b5109ef0d\"><p class=\"guide-markup\" data-start=\"1972\" data-end=\"2057\">Avoid editing listings that has already received an order orders to prevent pricing or fulfillment issues.</p></li>\n<li class=\"guide-markup\" data-start=\"2058\" data-end=\"2132\" data-list-item-id=\"e3ab07361778730852ea51fe688e76987\"><p class=\"guide-markup\" data-start=\"2060\" data-end=\"2132\">Maintain accurate product information for a seamless buyer experience.</p></li>\n<li class=\"guide-markup\" data-start=\"2058\" data-end=\"2132\" data-list-item-id=\"e10650a4fe76e3a30b79aae9c8ee429e5\"><p class=\"guide-markup\" data-start=\"2060\" data-end=\"2132\">Avoid keeping items that remain unsold for extended periods, as this can affect inventory efficiency and sales performance.</p></li>\n<li class=\"guide-markup\" data-start=\"2058\" data-end=\"2132\" data-list-item-id=\"eadbfe809bf6dcf0bb4aacf8e976cd526\"><p class=\"guide-markup\" data-start=\"2060\" data-end=\"2132\">Regularly review the demand list and trending items to stay ahead and optimize your inventory</p></li>\n</ul><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7T9T0NZXF08TVDQNH3PR8B3\"><strong class=\"guide-markup\">Frequently Asked Questions</strong></h2><details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. What happens if I edit a listing that already has active orders?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Avoid editing listings that have active orders, as changes may affect pricing,\n    product details, or fulfillment accuracy.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. Can I update multiple products at once?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    No. The <strong class=\"guide-markup\">bulk upload feature</strong> is currently unavailable. Each\n    product must be updated individually through the Vendor App.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. How do I track trending or high-demand products?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Regularly check <strong class=\"guide-markup\">Fleek’s Demand List</strong> and\n    <strong class=\"guide-markup\">Trending Items</strong> to identify and restock popular products,\n    ensuring you stay aligned with buyer demand and market trends.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. What should I do with products that remain unsold for a long time?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Consider promoting or discounting slow-moving products to increase their\n    visibility and encourage sales. This also helps free up inventory space for\n    new and trending items.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. How can I mark a product as out of stock?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Go to the <strong class=\"guide-markup\">Inventory</strong> tab, open the listing, change the\n    <strong class=\"guide-markup\">Status</strong> to <strong class=\"guide-markup\">Sold (Out of Stock)</strong>, and upload\n    the update. The product will automatically move to your\n    <strong class=\"guide-markup\">Out of Stock</strong> listings.\n  </div>\n\n</details>\n\n<details class=\"guide-markup\">\n\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">6. How do I reactivate an inactive product?</span>\n  </summary>\n\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    In the <strong class=\"guide-markup\">Inventory</strong> tab, filter by <strong class=\"guide-markup\">Inactive</strong>,\n    select the product, and click <strong class=\"guide-markup\">Re-list</strong>. The item will move\n    back to your <strong class=\"guide-markup\">Active Listings</strong>.\n  </div>\n\n</details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42543042225307,"title":"Product Listing — A Complete Guide for Suppliers","body":"<p class=\"guide-markup\" data-start=\"170\" data-end=\"407\">This guide is designed to help suppliers understand everything about listing products on the Fleek platform. Accurate and well-optimized product listings play a key role in attracting customers, improving visibility, and driving sales.</p><p class=\"guide-markup\" data-start=\"409\" data-end=\"447\">Through this document, you’ll learn:</p><ul class=\"guide-markup\" data-start=\"448\" data-end=\"895\">\n<li class=\"guide-markup\" data-start=\"448\" data-end=\"553\" data-list-item-id=\"ec6ea33936f14e80fbb7183fbffe4f032\"><p class=\"guide-markup\" data-start=\"450\" data-end=\"553\"><strong class=\"guide-markup\" data-start=\"450\" data-end=\"472\">Types of Products:</strong> Understand the different product categories and listing requirements for each.</p></li>\n<li class=\"guide-markup\" data-start=\"554\" data-end=\"686\" data-list-item-id=\"e5de3571eecc4cf70df6faad96787144a\"><p class=\"guide-markup\" data-start=\"556\" data-end=\"686\"><strong class=\"guide-markup\" data-start=\"556\" data-end=\"582\">How to List a Product:</strong> Step-by-step guidance on adding new products, uploading images, entering details, and setting prices.</p></li>\n<li class=\"guide-markup\" data-start=\"687\" data-end=\"792\" data-list-item-id=\"ef91288cafc198e45182ac84b3620555b\"><p class=\"guide-markup\" data-start=\"689\" data-end=\"792\"><strong class=\"guide-markup\" data-start=\"689\" data-end=\"708\">Best Practices:</strong> Tips to ensure your listings meet Fleek’s quality standards and appeal to buyers.</p></li>\n</ul><p class=\"guide-markup\" data-start=\"897\" data-end=\"1069\">By the end of this guide, you’ll have a clear understanding of how to create effective listings that stand out, comply with Fleek’s policies, and help your business grow.</p><hr class=\"guide-markup\"><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Types of Products:</strong></span></span></p><figure class=\"wysiwyg-table guide-markup\" style=\"width: 100%;\"><table class=\"guide-markup wysiwyg-table-resized\" style=\"border-style: solid; border-width: 1px; margin-left: 0px; margin-right: auto;\">\n<colgroup class=\"guide-markup\">\n<col style=\"width: 26%;\" class=\"guide-markup\">\n<col style=\"width: 74%;\" class=\"guide-markup\">\n</colgroup>\n<thead class=\"guide-markup\"><tr class=\"guide-markup\">\n<th style=\"border-style: solid; border-width: 1px;\" class=\"guide-markup\"><p class=\"wysiwyg-text-align-center guide-markup\">Type</p></th>\n<th style=\"border-style: solid; border-width: 1px;\" class=\"guide-markup\"><p class=\"wysiwyg-text-align-center guide-markup\">Description</p></th>\n</tr></thead>\n<tbody class=\"guide-markup\">\n<tr class=\"guide-markup\">\n<td style=\"border-style: solid; border-width: 1px;\" class=\"guide-markup\"><p class=\"wysiwyg-text-align-center guide-markup\"><span style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Exact Listing</strong></span></span></p></td>\n<td style=\"border-style: solid; border-width: 1px;\" class=\"guide-markup\">Products must match the listed item exactly — same brand, design, and details.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td style=\"border-style: solid; border-width: 1px;\" class=\"guide-markup\"><p class=\"wysiwyg-text-align-center guide-markup\"><span style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Representative Listing</strong></span></span></p></td>\n<td style=\"border-style: solid; border-width: 1px;\" class=\"guide-markup\">Items can vary slightly in design or material but should closely resemble the listed item.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td style=\"border-style: solid; border-width: 1px;\" class=\"guide-markup\"><p class=\"wysiwyg-text-align-center guide-markup\"><span style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Custom Handpick Listing</strong></span></span></p></td>\n<td style=\"border-style: solid; border-width: 1px;\" class=\"guide-markup\">Created after a buyer-seller agreement — buyers select items live during a video call.</td>\n</tr>\n</tbody>\n</table></figure><hr class=\"guide-markup\"><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">How to list a Product:</strong></span></span></p><div class=\"guide-markup\"><div class=\"guide-markup\" tabindex=\"-1\"><div class=\"guide-markup\"><div class=\"guide-markup\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"5737e26e-66bc-429d-a379-1205f2e9cc1d\" data-message-model-slug=\"gpt-5\"><div class=\"guide-markup\"><div class=\"guide-markup\">\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"51\" data-is-last-node=\"\" data-is-only-node=\"\">Listing your products on Fleek is a simple and hassle-free process. With just a few easy steps, you can showcase your items to thousands of buyers effortlessly.</p>\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"51\" data-is-last-node=\"\" data-is-only-node=\"\">Click <a href=\"https://drive.google.com/file/d/1-fgruGlK_a5rH462Tm1CSqCS4q8AZ2F4/view?usp=drive_link\">here</a> to see how to list product.</p>\n<hr class=\"guide-markup\">\n<p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">How to Manage your Inventory:</strong></span></span></p>\n<p class=\"guide-markup\" data-start=\"0\" data-end=\"51\" data-is-last-node=\"\" data-is-only-node=\"\">Click <a href=\"https://support.joinfleek.com/hc/en-us/articles/42543244979227\">here</a> to see how to manage your inventory or products.</p>\n<hr class=\"guide-markup\">\n</div></div></div></div></div></div><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Best Practices:</strong></span></span></p><figure class=\"wysiwyg-table guide-markup\" style=\"width: 100%;\"><table class=\"guide-markup wysiwyg-table-resized\" style=\"border-style: solid; border-width: 1px; margin-left: 0px; margin-right: auto;\">\n<colgroup class=\"guide-markup\">\n<col style=\"width: 21%;\" class=\"guide-markup\">\n<col style=\"width: 45%;\" class=\"guide-markup\">\n<col style=\"width: 34%;\" class=\"guide-markup\">\n</colgroup>\n<thead class=\"guide-markup\"><tr class=\"guide-markup\">\n<th style=\"border-style: solid; text-align: center;\" class=\"guide-markup\"><strong class=\"guide-markup\">Category</strong></th>\n<th style=\"text-align: center;\" class=\"guide-markup\"><strong class=\"guide-markup\">Best Practice</strong></th>\n<th style=\"text-align: center;\" class=\"guide-markup\"><strong class=\"guide-markup\">Why It Matters</strong></th>\n</tr></thead>\n<tbody class=\"guide-markup\">\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\"><strong class=\"guide-markup\">Quality Check</strong></td>\n<td class=\"guide-markup\">Inspect each item before listing — ensure correct grading, damages, or missing tags.</td>\n<td class=\"guide-markup\">Builds buyer trust and reduces returns or complaints.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\"><strong class=\"guide-markup\">High-Quality Presentation</strong></td>\n<td class=\"guide-markup\">Use clear, well-lit images on plain backgrounds and show multiple angles.</td>\n<td class=\"guide-markup\">Makes your product stand out and increases sales.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\"><strong class=\"guide-markup\">Accurate Product Details</strong></td>\n<td class=\"guide-markup\">Add brand, size, material, condition, and unique features in your listing.</td>\n<td class=\"guide-markup\">Helps buyers make informed purchase decisions.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\"><strong class=\"guide-markup\">Category Accuracy</strong></td>\n<td class=\"guide-markup\">Always list under the right product type or category.</td>\n<td class=\"guide-markup\">Boosts discoverability and avoids confusion.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\"><strong class=\"guide-markup\">Competitive &amp; Transparent Pricing</strong></td>\n<td class=\"guide-markup\">Set realistic prices and include accurate shipping costs.</td>\n<td class=\"guide-markup\">Improves buyer confidence and conversion rates.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\"><strong class=\"guide-markup\">Regular Stock Refresh</strong></td>\n<td class=\"guide-markup\">Upload new and trending items regularly.</td>\n<td class=\"guide-markup\">Keeps your store active and attracts repeat buyers.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\"><strong class=\"guide-markup\">Inventory Management</strong></td>\n<td class=\"guide-markup\">Keep stock updated and remove unavailable products.</td>\n<td class=\"guide-markup\">Prevents cancellations and maintains good ratings.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\"><strong class=\"guide-markup\">Customer Feedback Loop</strong></td>\n<td class=\"guide-markup\">Review buyer feedback and make improvements based on it.</td>\n<td class=\"guide-markup\">Shows professionalism and builds long-term relationships.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\"><strong class=\"guide-markup\">Trend Awareness</strong></td>\n<td class=\"guide-markup\">Track popular categories and seasonal styles.</td>\n<td class=\"guide-markup\">Helps align your listings with market demand.</td>\n</tr>\n<tr class=\"guide-markup\">\n<td class=\"guide-markup\"><strong class=\"guide-markup\">Communication</strong></td>\n<td class=\"guide-markup\">Stay responsive and transparent with buyers.</td>\n<td class=\"guide-markup\">Prevents disputes and strengthens your credibility.</td>\n</tr>\n</tbody>\n</table></figure><hr class=\"guide-markup\"><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Frequesntly Asked Questions:</strong></span></span></p><details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">1. What’s the difference between Exact, Representative, and Custom Handpick listings?</span>\n    </summary>\n    <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">Exact:</strong> Must match details and media exactly.\n      </li>\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">Representative:</strong> Similar but slight variations are\n        allowed.\n      </li>\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">Custom Handpick:</strong> Buyer selects items directly.\n      </li>\n    </ul>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">2. Can I use different images than the actual product?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      No. For <strong class=\"guide-markup\">Exact</strong> listings, images must match exactly. For\n      <strong class=\"guide-markup\">Representative</strong> listings, slight variations are allowed\n      but must reflect the real product.\n    </p>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">3. How do I set shipping charges in my Custom Handpick order?</span>\n    </summary>\n    <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">PK/India:</strong> Use “Calculate Shipping” or include it\n        in the base price.\n      </li>\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">ROW (Rest of World):</strong> Always include shipping in\n        the base price.\n      </li>\n    </ul>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">4. What happens if I don’t add shipping correctly in my Custom Handpick order?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      The buyer may see incorrect pricing, leading to disputes. Always calculate\n      or include shipping correctly.\n    </p>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">5. How do I inactivate a product?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      Long press → Tick box → Click <strong class=\"guide-markup\">Inactive</strong>.\n    </p>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">6. How do I re-activate a product?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      Go to <strong class=\"guide-markup\">Inactive</strong> tab → Long press → Tick box → Click\n      <strong class=\"guide-markup\">Re-activate</strong>.\n    </p>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">7. How long does approval take?</span>\n    </summary>\n    <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">New listings:</strong> 24 to 48 hours\n      </li>\n      <li class=\"guide-markup\">\n        <strong class=\"guide-markup\">Modifications:</strong> Up to 72 hours\n      </li>\n    </ul>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">8. Can I list multiple items under one Representative listing?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      Yes, as long as the items are similar in design or material with only\n      minor differences.\n    </p>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">9. Do I need buyer confirmation for Custom Handpick?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      Yes, always confirm with the buyer — usually via a video call.\n    </p>\n  </details>\n  <details class=\"guide-markup\">\n    <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 8px; cursor: pointer;\" class=\"guide-markup\">\n      <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">10. What if my listing is rejected?</span>\n    </summary>\n    <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n      Review the rejection reason, correct the issue, and re-submit for approval.\n    </p>\n  </details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    Pakistan: 11:00 AM – 7:00 PM PKT |\n    India: 10:30 AM – 6:30 PM IST |\n    UK: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n  </p>\n</div>"},{"id":42542918397723,"title":"App Walkthrough — Get Familiar with Your Supplier App","body":"<p class=\"guide-markup\" data-start=\"179\" data-end=\"488\"><span style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Welcome to your Fleek Supplier App!</strong></span></span><strong class=\"guide-markup\"> </strong>This application walkthrough is designed to help you explore and understand every key feature that empowers you to run your business seamlessly. From managing inventory to fulfilling orders, this guide will take you step by step through the essential tools and sections of the app.</p><p class=\"guide-markup\" data-start=\"490\" data-end=\"512\">You’ll learn how to:</p><ul class=\"guide-markup\" data-start=\"513\" data-end=\"955\">\n<li class=\"guide-markup\" data-start=\"513\" data-end=\"570\" data-list-item-id=\"ed9779273a9b947653c2fc0d131ada05d\"><p class=\"guide-markup\" data-start=\"515\" data-end=\"570\"><strong class=\"guide-markup\" data-start=\"515\" data-end=\"527\">Navigate</strong> the app easily and access all key areas.</p></li>\n<li class=\"guide-markup\" data-start=\"571\" data-end=\"656\" data-list-item-id=\"e924b1de4b16315a166629ab8184481ac\"><p class=\"guide-markup\" data-start=\"573\" data-end=\"656\"><strong class=\"guide-markup\" data-start=\"573\" data-end=\"612\">Manage Inventory &amp; Product Listings</strong> to keep your store updated and organized.</p></li>\n<li class=\"guide-markup\" data-start=\"657\" data-end=\"747\" data-list-item-id=\"e6962440434eeabe044a3a010e983b3a5\"><p class=\"guide-markup\" data-start=\"659\" data-end=\"747\"><strong class=\"guide-markup\" data-start=\"659\" data-end=\"688\">Handle Orders Efficiently</strong> — from receiving order to dispatch and tracking.</p></li>\n<li class=\"guide-markup\" data-start=\"748\" data-end=\"860\" data-list-item-id=\"e5a351dd754790a6d23b6c989875434ca\"><p class=\"guide-markup\" data-start=\"750\" data-end=\"860\"><strong class=\"guide-markup\" data-start=\"750\" data-end=\"770\">Use Seller Tools</strong> to participate in campaigns, create discounts, and manage your stocklist strategically.</p></li>\n<li class=\"guide-markup\" data-start=\"861\" data-end=\"955\" data-list-item-id=\"e8644bfd3428072eb9aa08e1fc06e7524\"><p class=\"guide-markup\" data-start=\"863\" data-end=\"955\"><strong class=\"guide-markup\" data-start=\"863\" data-end=\"911\">Understand Customer Demand &amp; Wishlist Trends</strong> to plan your collections and boost sales.</p></li>\n</ul><p class=\"guide-markup\" data-start=\"957\" data-end=\"1129\">By the end of this walkthrough, you’ll be confident in using the app to its fullest potential — helping you save time, stay informed, and grow your business effortlessly.</p><p class=\"guide-markup\" data-start=\"957\" data-end=\"1129\"><strong class=\"guide-markup\">Master your app in minutes — open </strong><a class=\"guide-markup\" target=\"_blank\" rel=\"noopener noreferrer\" data-garden-id=\"buttons.anchor\" data-garden-version=\"8.76.9\" href=\"https://drive.google.com/file/d/1b2CgzmfvAYSqZLunCiV6ha7KRRx3UhoD/view?usp=drive_link\"><span style=\"color: hsl(48,100%,50%);\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Vendor App Walkthrough</strong></span></span></a></p><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7T9VDVMEN3QQYAGNV390AWG\"><strong class=\"guide-markup\">Frequently Asked Questions</strong></h2><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">1. What makes the Vendor App Walkthrough important for you?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    The Vendor App Walkthrough helps suppliers understand how to use the Fleek\n    Vendor App — including navigation, product listing, inventory management,\n    order handling, and payout tracking — to manage their business effectively.\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">2. How can I list a new product on the app?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    Simply tap the <strong class=\"guide-markup\">“+” button</strong> in the bottom navigation bar and\n    select <strong class=\"guide-markup\">choose the relevant type</strong>. Fill in all required details — including\n    <strong class=\"guide-markup\">title, description, category, price, and images</strong> — then submit\n    for review. Once approved by the Fleek team, your product will go live and\n    be visible to buyers.\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">3. How do I check my payout details?</span>\n  </summary>\n  <ul style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    <li class=\"guide-markup\">\n      Go to <strong class=\"guide-markup\">Chat</strong>\n    </li>\n    <li class=\"guide-markup\">\n      Open the <strong class=\"guide-markup\">Payments Team</strong> channel\n    </li>\n    <li class=\"guide-markup\">Click the payout link shared there</li>\n  </ul>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    Payouts are shared weekly in your Vendor App.\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">4. How can I track my orders?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    Visit the <strong class=\"guide-markup\">Orders</strong> section in your Vendor App to view your\n    active, completed, and pending orders. You can track each order’s status\n    — from creation to delivery — in real time.\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">5. What are Seller Tools, and where can I find them?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    Seller Tools allow you to participate in campaigns, offer discounts, and\n    manage your stocklist. You can access them in the\n    <strong class=\"guide-markup\">Seller Tools</strong> tab on your app’s main menu.\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">6. Can I see what customers are demanding or adding to their wishlist?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    Yes! The <strong class=\"guide-markup\">Customer Demand</strong> and <strong class=\"guide-markup\">Wishlist</strong> features\n    give insights into trending products and what buyers are most interested\n    in — helping you plan your inventory better.\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">7. Who should I contact if I face any issue while using the app?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    If you experience any technical issue or need assistance, reach out to\n    <strong class=\"guide-markup\">Seller Support</strong> through the chat option in your Vendor App.\n    Our team will guide you accordingly.\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">8. Can I use the Vendor App on multiple devices?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    Yes, you can log in to your account on multiple devices; however, we recommend\n    using one primary device for smooth performance and secure access.\n  </p>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">9. How can I update or edit my listed products?</span>\n  </summary>\n  <p style=\"color: #333; margin-left: 22px;\" class=\"guide-markup\">\n    You can edit your listings anytime by going to\n    <strong class=\"guide-markup\">Inventory → Manage Listings</strong>, selecting the product, and\n    updating details such as price, stock, or images.\n  </p>\n</details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    Pakistan: 11:00 AM – 7:00 PM PKT |\n    India: 10:30 AM – 6:30 PM IST |\n    UK: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n  </p>\n</div>"},{"id":42540745279131,"title":"Order Journey — A Complete understanding for Suppliers","body":"<p class=\"guide-markup\" data-start=\"235\" data-end=\"494\">Efficient order fulfilment lies at the heart of a seamless customer experience. This document is designed to help suppliers understand the complete journey of an order — from the moment it’s placed on the platform to its successful delivery to the customer.</p><p class=\"guide-markup\" data-start=\"496\" data-end=\"729\">It provides a detailed, geo-specific overview of how Fleek’s fulfilment process operates across all regions, including </p><ul class=\"guide-markup\">\n<li class=\"guide-markup ck-list-marker-bold\" data-list-item-id=\"ef5e55f4e258a97838c1d2b02c77d061a\"><p class=\"guide-markup\" data-start=\"496\" data-end=\"729\"><strong class=\"guide-markup\" data-start=\"615\" data-end=\"694\">Pakistan (PK)</strong></p></li>\n<li class=\"guide-markup ck-list-marker-bold\" data-list-item-id=\"e902d52f719bd1b52e1f1bdc1c63e2261\"><p class=\"guide-markup\" data-start=\"496\" data-end=\"729\"><strong class=\"guide-markup\" data-start=\"615\" data-end=\"694\">India (IN)</strong></p></li>\n<li class=\"guide-markup ck-list-marker-bold\" data-list-item-id=\"e118f2bef4466f88ed9632923e2161263\"><p class=\"guide-markup\" data-start=\"496\" data-end=\"729\"><strong class=\"guide-markup\" data-start=\"615\" data-end=\"694\">United Kingdom (UK)</strong></p></li>\n<li class=\"guide-markup ck-list-marker-bold\" data-list-item-id=\"e5400bed9b6c98854443e3ae88049f6d9\"><p class=\"guide-markup\" data-start=\"496\" data-end=\"729\"><strong class=\"guide-markup\" data-start=\"615\" data-end=\"694\">United Arab Emirates (UAE)</strong></p></li>\n<li class=\"guide-markup ck-list-marker-bold\" data-list-item-id=\"e9702c12600e7058fcbe3fc982624ea6f\"><p class=\"guide-markup\" data-start=\"496\" data-end=\"729\"><strong class=\"guide-markup\" data-start=\"699\" data-end=\"726\">Rest of the World (ROW)</strong></p></li>\n</ul><p class=\"guide-markup\" data-start=\"731\" data-end=\"1093\">Through this guide, suppliers will gain clarity on each stage of the fulfilment cycle — including <strong class=\"guide-markup\" data-start=\"829\" data-end=\"933\">order creation, pickup, warehouse processing, quality checks, logistics handover, and final delivery</strong>. </p><p class=\"guide-markup\" data-start=\"731\" data-end=\"1093\">By understanding this flow, you can ensure smooth coordination, faster dispatches, and a consistently high-quality experience for buyers across all markets.</p><p class=\"guide-markup\" data-start=\"731\" data-end=\"1093\">Click <a href=\"https://drive.google.com/file/d/1VOKbeEHbOYAXCw7UhrP6lN0Kmy2xX_16/view?usp=drive_link\">here </a>to understand more</p><hr class=\"guide-markup\"><p class=\"guide-markup\"><span class=\"wysiwyg-font-size-large\"><span class=\"guide-markup\"><strong class=\"guide-markup\">Frequesntly Asked Questions:</strong></span></span></p><details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 15px;\" class=\"guide-markup\">What happens after I accept an order?</span> </summary> <div style=\"padding-left: 26px; margin-top: 4px;\" class=\"guide-markup\"> Once you accept an order in the <strong class=\"guide-markup\">Fleek Vendor App</strong>, it moves to the <strong class=\"guide-markup\">Processing</strong> stage. This means you should start preparing the product for dispatch — ensuring it’s ready, properly packed, and labeled for pickup. Once prepared, Fleek’s logistics partner or pickup team will schedule a collection. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 15px;\" class=\"guide-markup\">How is the pickup scheduled?</span> </summary> <div style=\"padding-left: 26px; margin-top: 4px;\" class=\"guide-markup\"> Once your order is marked <strong class=\"guide-markup\">Ready for Pickup</strong>, the system notifies the <strong class=\"guide-markup\">Operations Team</strong>. A courier is then assigned based on your pickup location and order type. You’ll receive a notification with the pickup date and time, and the rider will arrive during that window to collect the parcel. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 15px;\" class=\"guide-markup\">How do I mark my order as Ready for Pickup?</span> </summary> <div style=\"padding-left: 26px; margin-top: 4px;\" class=\"guide-markup\"> Once your order is packed and labeled, open the <strong class=\"guide-markup\">Fleek Vendor App</strong>, go to the <strong class=\"guide-markup\">Orders</strong> section, select the respective order, and tap <strong class=\"guide-markup\">Mark as Ready for Pickup</strong>. This action notifies Fleek’s <strong class=\"guide-markup\">Operations Team</strong> to schedule a courier for collection. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 15px;\" class=\"guide-markup\">When should I hand over the parcel to the courier?</span> </summary> <div style=\"padding-left: 26px; margin-top: 4px;\" class=\"guide-markup\"> If you’re in a region where Fleek provides <strong class=\"guide-markup\">Pickup Services</strong>, hand over the parcel during the assigned pickup time. Missing the slot may delay delivery and affect your supplier performance score. Always have your order packed and labeled before the pickup team arrives. <br class=\"guide-markup\"><br class=\"guide-markup\"> If Fleek doesn’t provide pickup in your region, you must hand over the order to your <strong class=\"guide-markup\">chosen courier</strong> within 48 hours. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 15px;\" class=\"guide-markup\">How can I track my order after dispatch?</span> </summary> <div style=\"padding-left: 26px; margin-top: 4px;\" class=\"guide-markup\"> Once your parcel is picked up, a <strong class=\"guide-markup\">Tracking ID</strong> will appear in your Fleek Vendor App. You can use it to view the live delivery status — including updates such as <strong class=\"guide-markup\">In Transit</strong>, <strong class=\"guide-markup\">Out for Delivery</strong>, and <strong class=\"guide-markup\">Delivered</strong>. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 15px;\" class=\"guide-markup\">What should I do if the courier misses the pickup?</span> </summary> <div style=\"padding-left: 26px; margin-top: 4px;\" class=\"guide-markup\"> If no one comes for pickup within the assigned time, report it immediately to the <strong class=\"guide-markup\">Seller Support Team</strong> via the app or WhatsApp. They’ll coordinate with the <strong class=\"guide-markup\">Operations Team</strong> to arrange a new pickup slot at the earliest. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 15px;\" class=\"guide-markup\">Can I cancel the order after accepting it?</span> </summary> <div style=\"padding-left: 26px; margin-top: 4px;\" class=\"guide-markup\"> Cancellations after accepting an order should be avoided. However, if absolutely necessary, contact <strong class=\"guide-markup\">Seller Support</strong> with a valid reason. Frequent cancellations can lead to penalties or a temporary hold on payouts for that order. </div> </details> <details class=\"guide-markup\"> <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\"> <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span> <span style=\"color: #ffcc00; font-weight: 700; font-size: 15px;\" class=\"guide-markup\">When and how will I receive my payment?</span> </summary> <div style=\"padding-left: 26px; margin-top: 4px;\" class=\"guide-markup\"> Payments are processed <strong class=\"guide-markup\">weekly</strong> once the order is marked <strong class=\"guide-markup\">Delivered</strong> and verified by Fleek. The payout includes your product price minus Fleek’s commission and applicable fees. You can view your complete payout details directly in your <strong class=\"guide-markup\">Payout Sheet</strong> or <strong class=\"guide-markup\">Vendor Dashboard</strong>. </div> </details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    Pakistan: 11:00 AM – 7:00 PM PKT |\n    India: 10:30 AM – 6:30 PM IST |\n    UK: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n  </p>\n</div>"},{"id":42540435572763,"title":"Seller Disintermediation Policy","body":"<h2 class=\"guide-markup\" id=\"h_01K7S5AXRHN4RRZ4ATKVMGCW2N\" data-start=\"140\" data-end=\"151\"><strong class=\"guide-markup\">Overview</strong></h2><p class=\"guide-markup\" data-start=\"152\" data-end=\"419\">To maintain a <strong class=\"guide-markup\" data-start=\"166\" data-end=\"211\">fair, transparent, and secure marketplace</strong>, sellers must conduct all transactions and communications through the platform. This article explains what disintermediation is, prohibited activities, potential consequences, and how to report violations.</p><p class=\"guide-markup\" data-start=\"421\" data-end=\"588\"><strong class=\"guide-markup\" data-start=\"421\" data-end=\"442\">Disintermediation</strong> occurs when a seller attempts to bypass the platform to transact directly with buyers, avoiding fees, policies, or oversight. Examples include:</p><ul class=\"guide-markup\" data-start=\"589\" data-end=\"852\">\n<li class=\"guide-markup\" data-start=\"589\" data-end=\"662\" data-list-item-id=\"e3e469f2736c019ecaefe97602f2b8819\"><p class=\"guide-markup\" data-start=\"591\" data-end=\"662\">Sharing personal contact details (phone number, email, social media).</p></li>\n<li class=\"guide-markup\" data-start=\"663\" data-end=\"723\" data-list-item-id=\"ec9706332003889f95223427f68627dc7\"><p class=\"guide-markup\" data-start=\"665\" data-end=\"723\">Encouraging buyers to pay or order outside the platform.</p></li>\n<li class=\"guide-markup\" data-start=\"724\" data-end=\"779\" data-list-item-id=\"e403aac75dd2d58db604a56d9a02edb5d\"><p class=\"guide-markup\" data-start=\"726\" data-end=\"779\">Fulfilling orders privately to avoid platform fees.</p></li>\n<li class=\"guide-markup\" data-start=\"780\" data-end=\"852\" data-list-item-id=\"e882954d1f6e396d4b1fedb908e28b2a6\"><p class=\"guide-markup\" data-start=\"782\" data-end=\"852\">Promoting external websites or online stores for off-platform sales.</p></li>\n</ul><hr class=\"guide-markup\" data-start=\"854\" data-end=\"857\"><h2 class=\"guide-markup\" id=\"h_01K7S8570W7BSMNK7BCXVZBKQH\" data-start=\"556\" data-end=\"598\"><strong class=\"guide-markup\">Why Off-Platform Transactions Are Risky</strong></h2><p class=\"guide-markup\" data-start=\"599\" data-end=\"671\">Sellers must avoid off-platform transactions because they can lead to:</p><ul class=\"guide-markup\" data-start=\"672\" data-end=\"890\">\n<li class=\"guide-markup\" data-start=\"672\" data-end=\"729\" data-list-item-id=\"e2e5ce4ac1060d33d42df5167b5fb72dc\"><p class=\"guide-markup\" data-start=\"674\" data-end=\"729\">Payment Risk.</p></li>\n<li class=\"guide-markup\" data-start=\"730\" data-end=\"786\" data-list-item-id=\"e2ac8ed695ef4c52aebc664ef3bf261d3\"><p class=\"guide-markup\" data-start=\"732\" data-end=\"786\">Risk of account suspension or permanent termination.</p></li>\n<li class=\"guide-markup\" data-start=\"787\" data-end=\"829\" data-list-item-id=\"ece9f298054b60754357bdf41b2da3dbb\"><p class=\"guide-markup\" data-start=\"789\" data-end=\"829\">Increased chance of fraud or disputes.</p></li>\n<li class=\"guide-markup\" data-start=\"830\" data-end=\"890\" data-list-item-id=\"e95177af85cc74a63b5665291e4398be3\"><p class=\"guide-markup\" data-start=\"832\" data-end=\"890\">Reduced trust in the marketplace, affecting all sellers.</p></li>\n</ul><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7S8560KNN0BZ9NV2EQS4ZQ0\" data-start=\"859\" data-end=\"880\"><strong class=\"guide-markup\">Prohibited Actions</strong></h2><p class=\"guide-markup\" data-start=\"881\" data-end=\"904\">Sellers <strong class=\"guide-markup\" data-start=\"889\" data-end=\"901\">must not</strong>:</p><ul class=\"guide-markup\" data-start=\"905\" data-end=\"1208\">\n<li class=\"guide-markup\" data-start=\"905\" data-end=\"971\" data-list-item-id=\"eb013850b1f91ade51319c131e905f40c\"><p class=\"guide-markup\" data-start=\"907\" data-end=\"971\">Ask buyers to cancel platform orders and repurchase elsewhere.</p></li>\n<li class=\"guide-markup\" data-start=\"972\" data-end=\"1045\" data-list-item-id=\"e94f59142991c7ad424e1f74fa149c577\"><p class=\"guide-markup\" data-start=\"974\" data-end=\"1045\">Share QR codes, payment links, contact number or other off-platform payment methods.</p></li>\n<li class=\"guide-markup\" data-start=\"1046\" data-end=\"1135\" data-list-item-id=\"eb166fa905ecbc2ea642a2a94fd3114d6\"><p class=\"guide-markup\" data-start=\"1048\" data-end=\"1135\">Mention alternative selling channels, prices, or special offers outside the platform.</p></li>\n<li class=\"guide-markup\" data-start=\"1136\" data-end=\"1208\" data-list-item-id=\"e7e04ed72831a428901ff3d0a834218e3\"><p class=\"guide-markup\" data-start=\"1138\" data-end=\"1208\">Encourage communication outside official platform messaging systems.</p></li>\n</ul><hr class=\"guide-markup\" data-start=\"1210\" data-end=\"1213\"><h2 class=\"guide-markup\" id=\"h_01K7S6R5V4YDKN92YD1PNG5TP6\" data-start=\"968\" data-end=\"1008\"><strong class=\"guide-markup\">Examples of Off-Platform Transactions</strong></h2><figure class=\"wysiwyg-table wysiwyg-table-align-left guide-markup\" style=\"width: 100%;\"><table class=\"guide-markup wysiwyg-table-resized\" style=\"margin-left: 0px; margin-right: auto;\" data-start=\"175\" data-end=\"1784\">\n<colgroup class=\"guide-markup\">\n<col style=\"width: 26%;\" class=\"guide-markup\">\n<col style=\"width: 74%;\" class=\"guide-markup\">\n</colgroup>\n<thead class=\"guide-markup\" data-start=\"175\" data-end=\"230\"><tr class=\"guide-markup\" data-start=\"175\" data-end=\"230\">\n<th style=\"text-align: center;\" class=\"guide-markup\" data-start=\"175\" data-end=\"201\" data-col-size=\"sm\"><strong class=\"guide-markup\" data-start=\"177\" data-end=\"200\">Action</strong></th>\n<th style=\"text-align: center;\" class=\"guide-markup\" data-start=\"201\" data-end=\"230\" data-col-size=\"xl\"><strong class=\"guide-markup\" data-start=\"203\" data-end=\"228\">Description / Example</strong></th>\n</tr></thead>\n<tbody class=\"guide-markup\" data-start=\"287\" data-end=\"1784\">\n<tr class=\"guide-markup\" data-start=\"287\" data-end=\"445\">\n<td class=\"guide-markup\" data-start=\"287\" data-end=\"317\" data-col-size=\"sm\">Sharing contact information</td>\n<td class=\"guide-markup\" data-col-size=\"xl\" data-start=\"317\" data-end=\"445\">Posting mobile numbers, email addresses, or any other personal contact details asking buyers to contact the seller directly.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"446\" data-end=\"559\">\n<td class=\"guide-markup\" data-start=\"446\" data-end=\"464\" data-col-size=\"sm\">Direct payments</td>\n<td class=\"guide-markup\" data-col-size=\"xl\" data-start=\"464\" data-end=\"559\">Asking buyers to pay directly to the seller’s bank account instead of through the platform.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"560\" data-end=\"742\">\n<td class=\"guide-markup\" data-start=\"560\" data-end=\"588\" data-col-size=\"sm\">Promoting external stores</td>\n<td class=\"guide-markup\" data-col-size=\"xl\" data-start=\"588\" data-end=\"742\">Encouraging buyers to purchase items from the seller’s store on another platform, often at a lower price or with a discount than the platform listing.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"974\" data-end=\"1131\">\n<td class=\"guide-markup\" data-start=\"974\" data-end=\"1005\" data-col-size=\"sm\">Sharing external store links</td>\n<td class=\"guide-markup\" data-col-size=\"xl\" data-start=\"1005\" data-end=\"1131\">Sending buyers links to personal websites, social media stores, or other e-commerce platforms to complete the transaction.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"1132\" data-end=\"1270\">\n<td class=\"guide-markup\" data-start=\"1132\" data-end=\"1172\" data-col-size=\"sm\">Using messaging apps for transactions</td>\n<td class=\"guide-markup\" data-col-size=\"xl\" data-start=\"1172\" data-end=\"1270\">Asking buyers to continue negotiations or payments via WhatsApp, Telegram, or other chat apps.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"1271\" data-end=\"1402\">\n<td class=\"guide-markup\" data-start=\"1271\" data-end=\"1313\" data-col-size=\"sm\">Offering discounts outside the platform</td>\n<td class=\"guide-markup\" data-col-size=\"xl\" data-start=\"1313\" data-end=\"1402\">Providing lower prices, free shipping, or promotions if buyers purchase off-platform.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"1403\" data-end=\"1530\">\n<td class=\"guide-markup\" data-start=\"1403\" data-end=\"1438\" data-col-size=\"sm\">Encouraging group or bulk orders</td>\n<td class=\"guide-markup\" data-col-size=\"xl\" data-start=\"1438\" data-end=\"1530\">Suggesting buyers combine orders outside the platform to avoid fees or get better rates.</td>\n</tr>\n<tr class=\"guide-markup\" data-start=\"1531\" data-end=\"1658\">\n<td class=\"guide-markup\" data-start=\"1531\" data-end=\"1565\" data-col-size=\"sm\">Manipulating reviews externally</td>\n<td class=\"guide-markup\" data-col-size=\"xl\" data-start=\"1565\" data-end=\"1658\">Requesting feedback or testimonials on external sites in exchange for discounts or gifts.</td>\n</tr>\n</tbody>\n</table></figure><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7S6QBZK130YZVEVFWFSFJKT\" data-start=\"1215\" data-end=\"1255\"><strong class=\"guide-markup\">Consequences of Violating This Policy</strong></h2><p class=\"guide-markup\" data-start=\"1256\" data-end=\"1337\">Any confirmed or attempted disintermediation may result in disciplinary action:</p><ul class=\"guide-markup\" data-start=\"1339\" data-end=\"1587\">\n<li class=\"guide-markup\" data-start=\"1339\" data-end=\"1413\" data-list-item-id=\"ec83f15d2bf6f413b60a3aa261e250b64\"><p class=\"guide-markup\" data-start=\"1341\" data-end=\"1413\"><strong class=\"guide-markup\" data-start=\"1341\" data-end=\"1361\">First Instance/ Violation:</strong> Written warning and increased account monitoring.</p></li>\n<li class=\"guide-markup\" data-start=\"1414\" data-end=\"1483\" data-list-item-id=\"e897f964a04991baf97381073c9e44262\"><p class=\"guide-markup\" data-start=\"1416\" data-end=\"1483\"><strong class=\"guide-markup\" data-start=\"1416\" data-end=\"1437\">Second Instance/ Violation:</strong> Temporary suspension of the seller account for 7 days. Chats will be freezed and the platform visibility will be also effected.</p></li>\n<li class=\"guide-markup\" data-start=\"1484\" data-end=\"1587\" data-list-item-id=\"e3a616af6f828ec4f1904ce385c3284ce\"><p class=\"guide-markup\" data-start=\"1486\" data-end=\"1587\"><strong class=\"guide-markup\" data-start=\"1486\" data-end=\"1520\">Third Instance/Violations:</strong> Permanent account termination and forfeiture of pending payouts.</p></li>\n</ul><hr class=\"guide-markup\" data-start=\"1702\" data-end=\"1705\"><h2 class=\"guide-markup\" id=\"h_01K7S5AXRTXDTM3YHQ01J9FVA6\" data-start=\"1707\" data-end=\"1734\"><strong class=\"guide-markup\">Reporting and Monitoring</strong></h2><p class=\"guide-markup\" data-start=\"1735\" data-end=\"1930\">The platform actively monitors transactions and communications to detect disintermediation.<br>If a buyer reaches out to you, requesting to go offline. Please report <strong class=\"guide-markup\" data-start=\"1872\" data-end=\"1897\">report it immediately</strong> via Seller Support channels.</p><hr class=\"guide-markup\" data-start=\"1932\" data-end=\"1935\"><h2 class=\"guide-markup\" id=\"h_01K7S5AXRV7E46PSBJN4ETQ2HM\" data-start=\"1937\" data-end=\"1957\"><strong class=\"guide-markup\">Seller Commitment</strong></h2><p class=\"guide-markup\" data-start=\"1958\" data-end=\"2001\">By selling on the platform, you agree to:</p><ul class=\"guide-markup\" data-start=\"2002\" data-end=\"2155\">\n<li class=\"guide-markup\" data-start=\"2002\" data-end=\"2062\" data-list-item-id=\"e68389a5b9c6c2fe7a6f779469413b5b3\"><p class=\"guide-markup\" data-start=\"2004\" data-end=\"2062\">Conduct all business through official platform channels.</p></li>\n<li class=\"guide-markup\" data-start=\"2063\" data-end=\"2155\" data-list-item-id=\"e8af12e0e9f33ea73b723552c1c37fefa\"><p class=\"guide-markup\" data-start=\"2065\" data-end=\"2155\">Follow this policy to help maintain trust, safety, and integrity across the marketplace.</p></li>\n</ul><hr class=\"guide-markup\"><h2 class=\"guide-markup\" id=\"h_01K7SA64WRQCA2CBVRK6VJYT2P\" data-start=\"1937\" data-end=\"1957\"><strong class=\"guide-markup\">Frequently Asked Question</strong></h2><details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">1. What counts as disintermediation?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Disintermediation means moving communication, negotiation, or transactions\n    away from the platform — including sharing contact details, taking payments\n    off-platform, or promoting external stores.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">2. Can I send a buyer my WhatsApp number for order updates?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    No. All order updates and communication must happen strictly through the\n    platform’s messaging system.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">3. Can I offer a discount if the buyer contacts me outside the platform?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    No. Discounts or promotions can only be offered through the platform to maintain\n    fairness and ensure buyer protection.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">4. What happens if a buyer suggests paying me directly?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Always decline politely and remind the buyer to complete the order through\n    the platform. You should also report the buyer’s request to support.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">5. Is it okay to share my website or social media links?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    No. Sharing external store links, personal websites, or social media\n    pages\n    for direct sales is strictly prohibited.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">6. How will the platform detect off-platform transactions?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    The platform monitors messaging, payment patterns, and user reports\n    to\n    identify\n    and investigate possible disintermediation cases.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">7. Can reporting a buyer request protect me from violations?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. Reporting suspicious messages or payment requests helps protect\n    your\n    account and shows your compliance with platform rules.\n  </div>\n</details>\n<details class=\"guide-markup\">\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\" class=\"guide-markup\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\" class=\"guide-markup\">▶</span><span style=\"color: #ffcc00; font-weight: 700;\" class=\"guide-markup\">8. Can buyers report me for disintermediation?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\" class=\"guide-markup\">\n    Yes. Buyers can report any attempt to move transactions off-platform.\n    Such\n    reports may trigger an investigation and potential penalties.\n  </div>\n</details><hr class=\"guide-markup\"><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"},{"id":42539527252891,"title":"Seller Payment Policy","body":"<h3 id=\"h_01K7SB5YGECC3E2HPGGZNTP1HD\" data-start=\"233\" data-end=\"248\"><strong data-start=\"237\" data-end=\"248\">Purpose</strong></h3><p data-start=\"249\" data-end=\"482\">This policy explains how and when Fleek processes payments to sellers for their orders. It ensures full transparency in payout timelines, methods, and applicable deductions, helping sellers track their earnings efficiently.</p><hr data-start=\"484\" data-end=\"487\"><h3 id=\"h_01K7SB5YGG1M27J8HNWFAMWNFT\" data-start=\"489\" data-end=\"514\"><strong data-start=\"493\" data-end=\"514\">1. Payment Method</strong></h3><p data-start=\"515\" data-end=\"639\">All seller payments are processed via <strong data-start=\"553\" data-end=\"570\">bank transfer</strong> to the verified bank account linked to the seller’s Fleek profile.</p><ul data-start=\"640\" data-end=\"894\">\n<li data-start=\"640\" data-end=\"746\" data-list-item-id=\"e9532dfe14e9049395282ec0753e48470\"><p data-start=\"642\" data-end=\"746\">Sellers must ensure their bank account details are accurate and up to date to avoid payout delays.</p></li>\n<li data-start=\"747\" data-end=\"894\" data-list-item-id=\"ec2ec717ba60540694b2acdf3dfab17bd\"><p data-start=\"749\" data-end=\"894\">In case of incorrect or invalid account details, payment processing will be temporarily held until the information is corrected and verified.</p></li>\n</ul><hr><h3 id=\"h_01K7SB8YPYC7HXV0WS91BVXW3M\" data-start=\"929\" data-end=\"953\"><strong data-start=\"933\" data-end=\"953\">2. Payment Cycle</strong></h3><p data-start=\"955\" data-end=\"1102\">Fleek follows a <strong data-start=\"971\" data-end=\"995\">weekly payment cycle</strong> for all sellers. Payments are based on the order’s <strong data-start=\"1047\" data-end=\"1064\">status change</strong> and <strong data-start=\"1069\" data-end=\"1086\">category type</strong> as shown below:</p><h4 id=\"h_01K7SB8YQ0J07B8NENZZQPTWHH\" data-start=\"1104\" data-end=\"1149\"><strong data-start=\"1109\" data-end=\"1149\">a. Payout Trigger Status by Category</strong></h4><figure style=\"height: 107.292px; width: 700px;\" class=\"wysiwyg-table\"><table style=\"border-collapse: collapse; border-spacing: 0px; border: 2px solid inherit; margin-left: 0px; margin-right: auto;\"><tbody>\n<tr>\n<td style=\"text-align: left;\" data-start=\"1151\" data-end=\"1166\" data-col-size=\"sm\"><strong data-start=\"1153\" data-end=\"1165\">Category</strong></td>\n<td style=\"text-align: left;\" data-start=\"1166\" data-end=\"1179\" data-col-size=\"sm\"><strong data-start=\"1168\" data-end=\"1178\">Status</strong></td>\n<td style=\"text-align: left;\" data-start=\"1179\" data-end=\"1198\" data-col-size=\"md\"><strong data-start=\"1181\" data-end=\"1196\">Explanation</strong></td>\n</tr>\n<tr>\n<td data-start=\"1248\" data-end=\"1263\" data-col-size=\"sm\"><strong data-start=\"1250\" data-end=\"1262\">Non-Zone</strong></td>\n<td data-col-size=\"sm\" data-start=\"1263\" data-end=\"1277\">QC Approved</td>\n<td data-col-size=\"md\" data-start=\"1277\" data-end=\"1328\">Once the order status changes to <em data-start=\"1312\" data-end=\"1325\"><em>QC Approved</em></em>.</td>\n</tr>\n<tr>\n<td data-start=\"1329\" data-end=\"1340\" data-col-size=\"sm\"><strong data-start=\"1331\" data-end=\"1339\">Zone</strong></td>\n<td data-col-size=\"sm\" data-start=\"1340\" data-end=\"1350\">Freight</td>\n<td data-col-size=\"md\" data-start=\"1350\" data-end=\"1404\">Once the order status changes to <em data-start=\"1385\" data-end=\"1401\"><em>Freight Flight</em></em>.</td>\n</tr>\n<tr>\n<td data-start=\"1405\" data-end=\"1431\" data-col-size=\"sm\"><strong data-start=\"1407\" data-end=\"1430\">ROW (Rest of World)</strong></td>\n<td data-col-size=\"sm\" data-start=\"1431\" data-end=\"1441\">Courier</td>\n<td data-col-size=\"md\" data-start=\"1441\" data-end=\"1488\">Once the order status changes to <em data-start=\"1476\" data-end=\"1485\"><em>Courier</em></em>.</td>\n</tr>\n</tbody></table></figure><h4 id=\"h_01K7SB8YQBQPC34E5367EZJJW5\" data-start=\"1490\" data-end=\"1526\"><strong data-start=\"1495\" data-end=\"1526\">b. Payment Processing Cycle</strong></h4><ul data-start=\"1757\" data-end=\"1857\">\n<li data-start=\"1757\" data-end=\"1799\" data-list-item-id=\"e9c800fdb38a27d22ee1d9613c67fada5\"><p data-start=\"1759\" data-end=\"1799\"><strong data-start=\"1759\" data-end=\"1778\">Statement Days:</strong> Monday to Saturday</p></li>\n<li data-start=\"1800\" data-end=\"1857\" data-list-item-id=\"efcf830a0cbb046105310fc057d81dcfa\"><p data-start=\"1802\" data-end=\"1857\"><strong data-start=\"1802\" data-end=\"1819\">Payment Days:</strong> Monday and Tuesday (following week)</p></li>\n</ul><p><img style=\"height: auto;\" src=\"https://support.joinfleek.com/hc/article_attachments/42539527248027\" alt=\"Payment Process Overview (1).png\" width=\"6000\" height=\"2813\"></p><div>\n<hr>\n<h3 id=\"h_01K7SDAR93QAHB7R31AZC762EG\" data-start=\"2425\" data-end=\"2454\"><strong data-start=\"2429\" data-end=\"2454\">3. Payout Eligibility</strong></h3>\n<p data-start=\"2455\" data-end=\"2477\">To qualify for payout:</p>\n<ul data-start=\"2478\" data-end=\"2896\">\n<li data-start=\"2478\" data-end=\"2562\" data-list-item-id=\"e046d4ba394ac82bc44538e0d9bab7718\"><p data-start=\"2480\" data-end=\"2562\">The order must reach its respective payout trigger status (as per category).</p></li>\n<li data-start=\"2563\" data-end=\"2645\" data-list-item-id=\"e22b737a0326a6002f429f61d56b93271\"><p data-start=\"2565\" data-end=\"2645\">The order must be completed and not under dispute or return investigation.</p></li>\n<li data-start=\"2646\" data-end=\"2708\" data-list-item-id=\"e8304cfa2f7feefbc6a1cf1fbbda0533b\"><p data-start=\"2648\" data-end=\"2708\">The seller’s bank details must be verified and active.</p></li>\n<li data-start=\"2709\" data-end=\"2896\" data-list-item-id=\"e820b54b3ecf92346fd435bf5c44d4169\"><p data-start=\"2711\" data-end=\"2896\">The minimum payout amount must exceed 20 GBP. If the total payout value is less than 20 GBP, it will be carried forward to the next payment cycle until the threshold is met.</p></li>\n</ul>\n<p data-start=\"2898\" data-end=\"2988\">Orders not meeting these criteria will automatically roll over to the next eligible cycle.</p>\n<hr>\n<h3 id=\"h_01K7SKBDSBWPQDDH9J8KC15F90\" data-start=\"2425\" data-end=\"2454\"><strong data-start=\"0\" data-end=\"31\" data-is-only-node=\"\">4. Where can I view my payout?</strong></h3>\n<p>You can view your payout details in the Fleek Vendor App under the payment channel in Chat.</p>\n<p>Click <a href=\"https://fleek9810.zendesk.com/hc/en-us/articles/41933958361883\" target=\"_blank\" rel=\"noopener noreferrer\">here</a> to learn how payout works</p>\n<hr>\n<h3 id=\"h_01K7SDBNC45EMRF8SE3QED1Z2V\" data-start=\"2036\" data-end=\"2067\"><strong data-start=\"2040\" data-end=\"2067\">5. Commission Deduction</strong></h3>\n<p data-start=\"2068\" data-end=\"2165\">Fleek charges a 15% commission on the base price of every successfully delivered order.</p>\n<ul data-start=\"2167\" data-end=\"2387\">\n<li data-start=\"2167\" data-end=\"2234\" data-list-item-id=\"ea70ff00724cd29a912d6809874272c77\"><p data-start=\"2169\" data-end=\"2234\">The commission is automatically deducted from the payout.</p></li>\n<li data-start=\"2235\" data-end=\"2321\" data-list-item-id=\"eb76d33fbbea5a4addcc660f892b81fec\"><p data-start=\"2237\" data-end=\"2321\">The remaining net amount is transferred to the seller’s verified bank account.</p></li>\n</ul>\n<hr>\n<h3 id=\"h_01K7SKBDSBMFNNVM1SQPKE0HH5\" data-start=\"2036\" data-end=\"2067\"><strong data-start=\"2040\" data-end=\"2067\">6. Fee Types</strong></h3>\n<p>Yes — in addition to the standard commission, Fleek may apply certain fees based on specific scenarios and policies. Any applicable charges will be clearly displayed in your <strong data-start=\"190\" data-end=\"208\">payout summary</strong>.</p>\n<p>Click here to learn about Fleek’s Fee Policy</p>\n<hr>\n<h3 id=\"h_01K7SD581BS29JQ9XY4CRS973F\" data-start=\"2995\" data-end=\"3020\"><strong data-start=\"2999\" data-end=\"3020\">7. Payment Delays</strong></h3>\n<p data-start=\"3021\" data-end=\"3069\">Payment processing may experience delays due to:</p>\n<ul data-start=\"3070\" data-end=\"3202\">\n<li data-start=\"3070\" data-end=\"3117\" data-list-item-id=\"e8d8e43b2805d5a01d87aec02c3ff7cc0\"><p data-start=\"3072\" data-end=\"3117\">Bank holidays</p></li>\n<li data-start=\"3118\" data-end=\"3162\" data-list-item-id=\"e18a7ed029e8d4bf50d7a8d35b6090d34\"><p data-start=\"3120\" data-end=\"3162\">Unverified or incorrect bank details</p></li>\n<li data-start=\"3163\" data-end=\"3202\" data-list-item-id=\"ee5b5eff8e61113508482b60d0fd4160b\"><p data-start=\"3165\" data-end=\"3202\">Pending dispute or return claim</p></li>\n<li data-start=\"3163\" data-end=\"3202\" data-list-item-id=\"e754eb41cd30a88912b53575589bd1571\"><p data-start=\"3165\" data-end=\"3202\">Late Quality Check approval</p></li>\n</ul>\n<hr>\n<h3 id=\"h_01K7SKBDSB3Z6H008PBZVY2DF2\" data-start=\"2995\" data-end=\"3020\">\n<strong data-start=\"2999\" data-end=\"3020\">8.</strong><strong data-start=\"3101\" data-end=\"3126\"> Dispute Resolution</strong>\n</h3>\n<p data-start=\"3127\" data-end=\"3202\">If a seller identifies any issue in payout (missing or incorrect amount):</p>\n<ol data-start=\"3203\" data-end=\"3419\">\n<li data-start=\"3203\" data-end=\"3265\" data-list-item-id=\"e22ed51249575799bdce8f8a90996ad7a\"><p data-start=\"3206\" data-end=\"3265\">Submit a <strong data-start=\"3215\" data-end=\"3233\">support ticket</strong> through the Fleek Vendor App.</p></li>\n<li data-start=\"3266\" data-end=\"3343\" data-list-item-id=\"ede657ee79ca8fe8898201734373cd13e\"><p data-start=\"3269\" data-end=\"3343\">Attach <strong data-start=\"3276\" data-end=\"3289\">order IDs</strong>, <strong data-start=\"3291\" data-end=\"3311\">payout statement</strong>, or <strong data-start=\"3316\" data-end=\"3340\">reference screenshot</strong>.</p></li>\n<li data-start=\"3344\" data-end=\"3419\" data-list-item-id=\"e8289c6b12ae57c344ef61b8f3b784246\"><p data-start=\"3347\" data-end=\"3419\">The team will review and respond within <strong data-start=\"3395\" data-end=\"3416\">2-3 business days</strong>.</p></li>\n</ol>\n<hr>\n</div><p>Disclaimer: Fleek reserves the right to modify this policy in line with financial, operational, or regulatory changes. Any updates will be communicated through official seller channels and reflected in the Help Center.</p><hr><h3 id=\"h_01K7SKBDSBAABK55Z5F8TRVNAV\" data-start=\"2995\" data-end=\"3020\"><strong>Frequently Asked Questions</strong></h3><details>\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\">1. When will I receive my payment?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\">\n    Fleek processes payments <strong>weekly</strong>.  \n    Orders delivered and reaching the required status (<strong>QC Approved</strong>, <strong>Freight</strong>, or <strong>Courier</strong>) between Monday and Saturday are paid on <strong>Monday or Tuesday</strong> of the following week.\n  </div>\n</details>\n\n<details>\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\">2. What is the minimum payout amount?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\">\n    The minimum payout threshold is <strong>20 GBP</strong>.  \n    If your total payable amount is less than 20 GBP, it will be <strong>carried forward</strong> to the next payment cycle until the threshold is met.\n  </div>\n</details>\n\n<details>\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\">3. What deductions are applied before payment?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\">\n    A <strong>15% commission</strong> is deducted from the base price of each successfully delivered order.  \n    If you’re using a <strong>business account</strong>, a fixed transaction fee of <strong>USD 15 (≈ GBP 12)</strong> is also applied per payment transfer.\n  </div>\n</details>\n\n<details>\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\">4. What is the difference between statement days and payment days?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\">\n    <strong>Statement Days (Mon–Sat):</strong> Period when orders are finalized and listed for payout.<br><br>\n    <strong>Payment Days (Mon–Tue, following week):</strong> Actual transfer of funds to your verified bank account.\n  </div>\n</details>\n\n<details>\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\">5. How can I check my payout status?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\">\n    You can view your payout statements and transaction history directly in the <strong>Fleek Vendor App</strong> under the relevant payment channel in <strong>Chat</strong>.\n  </div>\n</details>\n\n<details>\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\">6. Why is my payment delayed?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\">\n    Your payment may be delayed due to:<br><br>\n    • Bank holidays<br>\n    • Unverified or incorrect bank details<br>\n    • Ongoing dispute or return investigation<br><br>\n    Once resolved, your payment will be processed in the next available cycle.\n  </div>\n</details>\n\n<details>\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\">7. What should I do if my payment amount seems incorrect?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\">\n    If your payout appears missing or incorrect:<br><br>\n    • Raise a <strong>support ticket</strong> through the Vendor App.<br>\n    • Attach your <strong>Order ID(s)</strong> and payout reference details.<br><br>\n    Our Finance team will review and respond within <strong>5–7 business days</strong>.\n  </div>\n</details>\n\n<details>\n  <summary style=\"list-style: none; -webkit-appearance: none; appearance: none; padding-left: 0; display: flex; align-items: center; gap: 6px; cursor: pointer;\">\n    <span style=\"color: #ffcc00; font-weight: 700; font-size: 16px;\">▶</span>\n    <span style=\"color: #ffcc00; font-weight: 700;\">8. Do I get notified when a payment is processed?</span>\n  </summary>\n  <div style=\"padding-left: 26px; margin-top: 6px;\">\n    Yes. You’ll receive a <strong>transfer receipt</strong> in the same payment channel once your amount is successfully transferred to your verified bank account.\n  </div>\n</details>\n<hr><div style=\"text-align: center; margin: 20px 0; font-family: Arial, sans-serif;\">\n  <img src=\"https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg\" alt=\"WhatsApp\" style=\"height: 120px; margin-bottom: 20px;\">\n  <p style=\"font-size: 20px; font-weight: 600; margin: 10px 0; color: #000;\">\n    Fleek Seller Support\n  </p>\n  <a href=\"https://wa.me/447435853808\" target=\"_blank\" style=\"display: inline-block; background-color: #25D366; color: white; font-size: 14px; font-weight: normal; text-decoration: none; padding: 6px 14px; border-radius: 20px; margin-top: 10px;\">\n    Continue to Chat\n  </a>\n  <p style=\"margin-top: 18px; font-size: 14px; color: #444;\">\n    <strong>Support Hours (Mon–Sat):</strong>\n    </p>\n     <strong class=\"guide-markup\">Pakistan</strong>: 11:00 AM – 7:00 PM PKT |\n     <strong class=\"guide-markup\">India</strong>: 10:30 AM – 6:30 PM IST |\n     <strong class=\"guide-markup\">UK</strong>: 7:00 AM – 3:00 PM BST | 6:00 AM - 2:00 PM GMT\n</div>"}];
